-- 3. إدخال الفقرات الـ 45
INSERT INTO public.chunks (id, chapter_id, lesson_id, chunk_index, chunk_title, en_chunk_title, type, icon_emoji, xp_reward, stars_reward, summary, audio_narration_text, en_audio_narration_text, ai_tutor_prompt, simplified_explanation, key_terms, content_cards)
VALUES ('ch1-l1-c1', 1, '1-1', 1, 'المراحل الخمس التاريخية لتطور الحوسبة', 'The 5 Historical Eras of Computing Evolution', 'chunk', '⏳', 30, 1, 'المحطات الخمس الكبرى: من حواسب الصمامات المفرغة الضخمة (ENIAC) إلى ثورة الحواسيب الشخصية والإنترنت والهواتف والحوسبة السحابية.', 'مرحباً يا بطل في بداية رحلتنا في هذه المحطة التعليمية! تكنولوجيا المعلومات مرت بخمس محطات تاريخية رئيسية: الأولى في الأربعينيات مع حواسيب الصمامات المفرغة الضخمة مثل حاسوب إينياك للأغراض العسكرية، ثم السبعينيات مع انتشار الحواسيب الشخصية في المنازل، ثم التسعينيات بإتاحة الإنترنت تجارياً وظهور الويب، ثم العقد الأول من الألفية مع ثورة الهواتف الذكية، وأخيراً من العقد الثاني فصاعداً مع الحوسبة السحابية والبيانات الضخمة والذكاء الاصطناعي.', 'Welcome champion! Information technology evolved through five major historical eras: first, the 1940s brought giant vacuum-tube electronic computers like ENIAC for military and scientific calculations. Second, the 1970s and 80s witnessed the personal computer revolution entering homes and offices. Third, the 1990s introduced commercial internet and the World Wide Web. Fourth, the 2000s ushered in mobile smartphones. And fifth, from 2010 onward, cloud computing and big data transformed IT into on-demand services.', 'عاش يا بطل! استوعبت المحطات الخمس لتطور الحوسبة من حاسوب إينياك حتى السحابة الذكية؟ ولا تحب نراجعها بمثال سريع؟', 'الكمبيوتر في البداية كان جهازاً ضخماً بحجم غرفة كاملة وبطيئاً جداً، ومع مرور العقود صغر حجمه حتى دخل المنازل، ثم اتصل بالإنترنت، ثم تحول لهاتف ذكي في جيبك، واليوم أصبح عقل حاسوبي سحابي خارق!', '[{"term":"حاسوب ENIAC","en":"ENIAC","definition":"أول حاسوب إلكتروني رقمي للأغراض العامة في الأربعينيات، اعتمد على الصمامات المفرغة وشغل حجماً كبيراً جداً لأغراض عسكرية وعلمية.","example":"كان وزنه يبلغ 30 طناً ويستهلك كهرباء تكفي لقرية كاملة!","examTip":"سؤال متكرر: المكون الأساسي للجيل الأول هو الصمامات المفرغة (Vacuum Tubes)."},{"term":"الحوسبة السحابية","en":"Cloud Computing","definition":"تقديم موارد تكنولوجيا المعلومات (الخوادم، التخزين، والمعالجة) كخدمة عبر الإنترنت مع الدفع حسب الاستهلاك.","example":"تخزين ملفاتك على Google Drive أو تشغيل نماذج الذكاء الاصطناعي دون جهاز باهظ الثمن.","examTip":"المحطة الخامسة بدأت من العقد الثاني من الألفية فصاعداً ودعمت ثورة البيانات الضخمة."}]'::jsonb, '[{"type":"concept","title":"جدول المحطات الخمس لتطور تكنولوجيا المعلومات (كتاب الوزارة ص 7):","points":["1️⃣ الأربعينيات – الستينيات: ظهور الحواسيب الإلكترونية (ENIAC) والصمامات المفرغة للحسابات العسكرية والعلمية.","2️⃣ السبعينيات – الثمانينيات: انتشار الحواسب الشخصية (PCs) في المنازل والمكاتب.","3️⃣ التسعينيات: إتاحة الإنترنت تجارياً وظهور الويب والبريد الإلكتروني والوصول العالمي للمعلومة.","4️⃣ العقد الأول من الألفية: ظهور الهواتف الذكية والإنترنت المتنقل في كل مكان.","5️⃣ العقد الثاني فصاعداً: البيانات الضخمة والحوسبة السحابية والذكاء الاصطناعي (IT as a Service)."]},{"type":"teacherTip","title":"💡 مفتاح الحفظ السريع الامتحاني:","text":"احفظها بالترتيب الزمني: إينياك عملاق الأربعينيات ← كمبيوتر شخصي بالسبعينيات ← إنترنت التسعينيات ← هاتف الألفية الذكي ← سحابة وذكاء اصطناعي اليوم!"}]'::jsonb)
ON CONFLICT (id) DO UPDATE SET chunk_title = EXCLUDED.chunk_title, summary = EXCLUDED.summary, key_terms = EXCLUDED.key_terms, content_cards = EXCLUDED.content_cards;
INSERT INTO public.chunks (id, chapter_id, lesson_id, chunk_index, chunk_title, en_chunk_title, type, icon_emoji, xp_reward, stars_reward, summary, audio_narration_text, en_audio_narration_text, ai_tutor_prompt, simplified_explanation, key_terms, content_cards)
VALUES ('ch1-l1-c2', 1, '1-1', 2, 'قانون مور وحدود السيليكون الفيزيائية والبدائل', 'Moore''s Law, Silicon Physical Limits & Alternatives', 'chunk', '🔬', 35, 1, 'ملاحظة تضاعف الترانزستورات كل سنتين، تحديات النفق الكمومي وتيارات التسرب والحرارة، والحلول بالمعالجة المتوازية وتعدد الأنوية.', 'قانون مور هو ملاحظة تجريبية شهيرة لاحظها جوردون مور، وتنص على أن عدد الترانزستورات في الشريحة يتضاعف تقريباً كل عامين. هذا القانون قاد تطور الصناعة لعقود وخفّض الأسعار وزاد السرعة، لكنه اليوم يواجه حدوداً فيزيائية حتمية مثل تيارات التسرب وظاهرة النفق الكمومي وتوليد الحرارة الفائقة. ولذلك لجأت الصناعة إلى تعدد الأنوية والمعالجة المتوازية بدلاً من مجرد زيادة تردد المعالج المنفرد.', 'Moore''s Law is an empirical observation stating that the number of transistors on a microchip doubles approximately every two years. Today, it encounters physical barriers: when transistors shrink to nanometer scales, quantum tunneling occurs, electrical leakage increases, and heat dissipation becomes overwhelming. Engineers solve this using multi-core processors and parallel computing architectures.', 'ممتاز يا بطل! فهمت ليه الترانزستور ما نقدرش نصغره إلى ما لا نهاية بسبب حاجز الذرة والحرارة؟ ولا تحب نوضحها أكتر؟', 'تخيل أنك ترسم خطوطاً بقلم: كلما كان سن القلم أدق رسمت تفاصيل أكثر، لكن عند الوصول لحجم الذرة، الحبر يبدأ يسيل من تلقاء نفسه! لذلك أصبح الحل وضع عدة عقول (أنوية) تفكر معاً بدلاً من تصغير القلم فقط!', '[{"term":"قانون مور","en":"Moore''s Law","definition":"ملاحظة تجريبية تفيد بأن عدد الترانزستورات في الدائرة المتكاملة يتضاعف تقريباً كل عامين.","example":"هاتفك الذكي الحالي يحمل مليارات الترانزستورات وأقوى بملايين المرات من حواسيب رحلة أبوللو!","examTip":"سؤال صح وخطأ: قانون مور هو قانون فيزيائي حتمي ثابت؟ الإجابة خطأ؛ هو ملاحظة وتوجيه تجريبي للصناعة."},{"term":"النفق الكمومي","en":"Quantum Tunneling","definition":"ظاهرة في ميكانيكا الكم تجعل الإلكترونات تقفز عبر الحواجز العازلة الدقيقة جداً عند الاقتراب من حجم الذرة.","example":"تسبب تسرباً للتيار وأخطاء في تشغيل الترانزستور (0 و 1).","examTip":"أحد التحديات الفيزيائية الرئيسية التي تحد من استمرار تصغير الترانزستور."}]'::jsonb, '[{"type":"concept","title":"التحديات الفيزيائية الثلاثة لقانون مور (كتاب الوزارة ص 6):","points":["⚡ تيارات التسرب (Leakage): تسرب الإلكترونات حتى في حالة إيقاف الترانزستور بسبب دقة النانومتر.","⚛️ التأثيرات الكمومية (Quantum Tunneling): قفز الإلكترونات عبر الحواجز العازلة دون تحكم.","🔥 توليد الحرارة الفائقة: الكثافة الهائلة لمليارات الترانزستورات يصعب تبريدها بالوسائل المعتادة."]},{"type":"concept","title":"الحلول الهندسية والبدائل التكنولوجية:","points":["🧩 تعدد الأنوية (Multi-core): دمج عدة أنوية في الشريحة وتوزيع الأعباء بالتوازي.","🚀 المعالجات المتخصصة: تصميم رقائق مخصصة للذكاء الاصطناعي (TPU/NPU) والحوسبة السحابية."]}]'::jsonb)
ON CONFLICT (id) DO UPDATE SET chunk_title = EXCLUDED.chunk_title, summary = EXCLUDED.summary, key_terms = EXCLUDED.key_terms, content_cards = EXCLUDED.content_cards;
INSERT INTO public.chunks (id, chapter_id, lesson_id, chunk_index, chunk_title, en_chunk_title, type, icon_emoji, xp_reward, stars_reward, summary, audio_narration_text, en_audio_narration_text, ai_tutor_prompt, simplified_explanation, key_terms, content_cards)
VALUES ('ch1-l1-c3', 1, '1-1', 3, 'التحولات المجتمعية الخمسة لتكنولوجيا المعلومات', 'The 5 Societal Shifts of Information Technology', 'chunk', '🌐', 35, 1, 'التحولات الخمسة التي أعادت صياغة حياة المجتمع: شبكات التواصل الاجتماعي، التجارة الإلكترونية، العمل عن بُعد، التعلم عبر الإنترنت، والدفع غير النقدي.', 'لم تكتفِ تكنولوجيا المعلومات بتطوير أجهزة أسرع؛ بل غيرت أسلوب حياة المجتمع تماماً في خمسة مجالات: شبكات التواصل الاجتماعي لنشر ومشاركة المعلومات، التجارة الإلكترونية لبيع وشراء السلع عبر الحدود، العمل عن بعد الذي وفر مرونة وتجاوز المسافات، التعلم عبر الإنترنت لتحقيق تكافؤ الفرص في المعرفة، والدفع غير النقدي كالنقود الإلكترونية ورموز الاستجابة السريعة كيو آر.', 'Information technology profoundly revolutionized human society across five fundamental pillars: first, E-Commerce enabling global retail shopping from home. Second, Remote Work allowing collaborative telecommuting across continents. Third, Cashless Digital Payments eliminating physical cash. Fourth, E-Learning providing customized digital instruction. And fifth, Social Networking Services connecting billions of people worldwide.', 'عظيم جداً يا بطل! عرفت التحولات الخمسة التي غيرت شكل المجتمع وطريقة تعاملنا مع التعليم والعمل والأموال؟ تحب نبدأ أسئلتها؟', 'قبل التكنولوجيا: كنت تضطر للسفر لشراء سلعة، والذهاب للمكتب للعمل، وحمل نقود ورقية ثقيلة. اليوم: بضغطة زر تشتري، وتعمل، وتتعلم، وتدفع أموالك وأنت في بيتك!', '[{"term":"شبكات التواصل الاجتماعي","en":"SNS","definition":"منصات رقمية تربط المستخدمين فيما بينهم لنشر ومشاركة المعلومات والتفاعل الفوري دون حواجز جغرافية.","example":"تطبيقات المحادثات والمواقع التفاعلية الإخبارية.","examTip":"تعريف نصي في كتاب الوزارة ص 12."},{"term":"الدفع غير النقدي","en":"Cashless Payment","definition":"إجراء المعاملات المالية دون استخدام النقد الورقي، مثل البطاقات البنكية، والمحافظ الإلكترونية، ورموز QR.","example":"الدفع عبر فودافون كاش أو إنستاباي أو بطاقة ميزة.","examTip":"سؤال امتحاني: ميزته توثيق المعاملات وسرعتها؛ ومصدر القلق هو استبعاد غير القادرين تقنياً ومخاطر انقطاع الشبكة."}]'::jsonb, '[{"type":"concept","title":"التحولات المجتمعية الخمسة (كتاب الوزارة ص 6–7):","points":["💬 1. شبكات التواصل (SNS): نشر ومشاركة المعلومات وتجاوز الحواجز الجغرافية.","🛒 2. التجارة الإلكترونية (E-Commerce): تسوق عالمي، مقارنة أسعار، وخفض تكاليف المتاجر.","💼 3. العمل عن بُعد (Remote Work): إنجاز المهام من أي موقع، خفض الازدحام، ومرونة الوقت.","🎓 4. التعلم عبر الإنترنت (Online Learning): تكافؤ الفرص والوصول لمصادر تعليمية ثرية في أي وقت.","💳 5. الدفع غير النقدي (Cashless Payment): أمان ضد السرقة، سرعة الإجراءات، وتوثيق الإنفاق إلكترونياً."]},{"type":"teacherTip","title":"⚠️ تنبيه وزاري على سؤال الامتحان (6 درجات):","text":"في الامتحان لو سألك عن تحديات المجتمع الرقمي: اذكر الفجوة الرقمية (استبعاد كبار السن أو من لا يملكون أجهزة) ومخاطر الأمن السيبراني وانقطاع الكهرباء والإنترنت!"}]'::jsonb)
ON CONFLICT (id) DO UPDATE SET chunk_title = EXCLUDED.chunk_title, summary = EXCLUDED.summary, key_terms = EXCLUDED.key_terms, content_cards = EXCLUDED.content_cards;
INSERT INTO public.chunks (id, chapter_id, lesson_id, chunk_index, chunk_title, en_chunk_title, type, icon_emoji, xp_reward, stars_reward, summary, audio_narration_text, en_audio_narration_text, ai_tutor_prompt, simplified_explanation, key_terms, content_cards)
VALUES ('ch1-l1-c4', 1, '1-1', 4, 'التقنيات الناشئة: القيادة الذاتية، AR/VR، والكمومية', 'Emerging Technologies: Autonomous Vehicles, AR/VR & Quantum', 'chunk', '🚀', 35, 1, 'التقنيات الناشئة المعتمدة بالمنهج: القيادة الذاتية والحوسبة الطرفية (Edge Computing)، الواقع المعزز (AR) والواقع الافتراضي (VR)، والحوسبة الكمومية ومفهوم الكيوبت والتراكب.', 'التقنيات الناشئة هي التي تصنع المستقبل اليوم: أولاً، السيارات ذاتية القيادة، والتي تعتمد على الحوسبة الطرفية لمعالجة البيانات فورياً على متن السيارة لتفادي الحوادث دون انتظار السحابة. ثانياً، الواقع المعزز الذي يركب عناصر رقمية فوق عالمنا الحقيقي، مقابل الواقع الافتراضي الذي يغمرك في عالم رقمي ثلاثي الأبعاد بالكامل. ثالثاً، الحوسبة الكمومية التي تعتمد على الكيوبت ومبدأ التراكب الكمومي لتمثيل الصفر والواحد في نفس الوقت، مما يحل معضلات حسابية هائلة تعجز عنها أقوى الحواسيب الخارقة.', 'Emerging technologies represent the frontier of modern computing: Autonomous vehicles use AI, computer vision, and LiDAR sensors to navigate safely without human drivers. Augmented Reality overlays synthetic digital information onto the real physical world, whereas Virtual Reality immerses users into completely simulated 3D environments. Quantum computing utilizes qubits, superposition, and quantum entanglement to solve calculations that classical computers cannot solve in millennia.', 'ممتاز يا عبقري! أتقنت الفارق الجوهري بين الواقع المعزز والواقع الافتراضي، ولماذا تعتمد السيارة ذاتية القيادة على الحوسبة الطرفية؟', 'الواقع المعزز AR مثل فلاتر السناب شات (وجهك حقيقي ونظارة رقمية فوقه)، والواقع الافتراضي VR مثل ارتداء خوذة مغلقة تعيش داخل لعبة فضائية! أما السيارة فتفكر بمخها الداخلي (طرفي) لأن الانتظار ثانية واحدة للسحابة قد يسبب حادثاً!', '[{"term":"الحوسبة الطرفية","en":"Edge Computing","definition":"معالجة البيانات محلياً على متن الجهاز أو المركبة نفسها بالقرب من مصدر البيانات دون انتظار إرسالها للسحابة لتقليل زمن التأخير وحفظ السلامة.","example":"كمبيوتر السيارة ذاتية القيادة يفرمل فوراً عند ظهور عائق في أجزاء من الثانية.","examTip":"سؤال وزاري: لماذا تعتمد السيارات ذاتية القيادة على الحوسبة الطرفية؟ الإجابة: لأن التأخير يمس السلامة ويجب اتخاذ القرار محلياً فوراً."},{"term":"الكيوبت والتراكب الكمومي","en":"Qubit & Superposition","definition":"وحدة الحوسبة الكمومية التي تمثل حالتي (0 و 1) معاً في آن واحد بفضل التراكب الكمومي، على عكس البت الكلاسيكي الذي يحمل حالة واحدة فقط.","example":"تتيح للحاسوب الكمي استكشاف ملايين الاحتمالات بالتوازي في ثوانٍ.","examTip":"البت الكلاسيكي يحمل 0 أو 1؛ بينما الكيوبت Qubit يحمل الحالتين معاً في تراكب كمومي."}]'::jsonb, '[{"type":"concept","title":"التقنيات الناشئة الثلاث المعتمدة بنص كتاب الوزارة (ص 8):","points":["🚗 1. القيادة الذاتية والحوسبة الطرفية: مستشعرات وذكاء اصطناعي يتخذ القرار على متن المركبة لحماية الأرواح وتفادي بطء السحابة.","🥽 2. الواقع المعزز (AR) مقابل الافتراضي (VR): الـ AR يدمج الرقمي بالواقع الحقيقي • الـ VR يعزلك داخل عالم افتراضي بالكامل.","⚛️ 3. الحوسبة الكمومية (Quantum): تعتمد على مبادئ ميكانيكا الكم والكيوبت لمعالجة أعقد العمليات العلمية والتشفير."]},{"type":"teacherTip","title":"💡 قارن في خطوة واحدة (سؤال امتحان ص 12):","text":"البريد الإلكتروني والحواسب الشخصية تقنيات سابقة • أما القيادة الذاتية، AR، VR، والحوسبة الكمومية هي التقنيات الناشئة!"}]'::jsonb)
ON CONFLICT (id) DO UPDATE SET chunk_title = EXCLUDED.chunk_title, summary = EXCLUDED.summary, key_terms = EXCLUDED.key_terms, content_cards = EXCLUDED.content_cards;
INSERT INTO public.chunks (id, chapter_id, lesson_id, chunk_index, chunk_title, en_chunk_title, type, icon_emoji, xp_reward, stars_reward, summary, audio_narration_text, en_audio_narration_text, ai_tutor_prompt, simplified_explanation, key_terms, content_cards)
VALUES ('ch1-l1-exam', 1, '1-1', 5, '🏆 التحدي الختامي: اختبار إتقان الدرس (1-1) الشامل', '🏆 Final Challenge: Lesson (1-1) Mastery Exam', 'lesson_exam', '🏆', 100, 3, 'اختبار امتحاني وزاري شامل مجمع يغطي كل محاور وفقرات الدرس (1-1): مراحل التطور، قانون مور، التحولات المجتمعية، والتقنيات الناشئة.', 'أهلاً بك يا بطل في التحدي الختامي لاجتياز الدرس الأول كاملاً! هذا الاختبار يجمع الأسئلة الوزارية الشاملة من كتاب الوزارة ص 11 و 12. عند اجتيازك هذا التحدي ستحصل على كأس التفوق والنجوم الثلاثة ويفتح لك الدرس الثاني مباشرة!', 'You have arrived at the Final Mastery Challenge of Lesson 1-1! Answer all five comprehensive questions correctly to claim your Golden Trophy and unlock the next lesson!', '', '', '[]'::jsonb, '[]'::jsonb)
ON CONFLICT (id) DO UPDATE SET chunk_title = EXCLUDED.chunk_title, summary = EXCLUDED.summary, key_terms = EXCLUDED.key_terms, content_cards = EXCLUDED.content_cards;
INSERT INTO public.chunks (id, chapter_id, lesson_id, chunk_index, chunk_title, en_chunk_title, type, icon_emoji, xp_reward, stars_reward, summary, audio_narration_text, en_audio_narration_text, ai_tutor_prompt, simplified_explanation, key_terms, content_cards)
VALUES ('ch1-l2-c1', 1, '1-2', 1, 'مفهوم الذكاء الاصطناعي وهرميته (AI vs ML vs DL vs GenAI)', 'Artificial Intelligence: Machine Learning, Deep Learning & Generative AI', 'chunk', '🧠', 35, 1, 'العلاقة الهرمية المتداخلة: الذكاء الاصطناعي (المظلة الأكبر) ← تعلم الآلة (ML) ← التعلم العميق (DL) ← الذكاء الاصطناعي التوليدي (GenAI).', 'الذكاء الاصطناعي ليس مصطلحاً مبهماً بل هو هرمية واضحة كطبقات القبة: المظلة الكبرى هي الذكاء الاصطناعي (AI) لمحاكاة الذكاء البشري، وبداخله مجال تعلم الآلة (Machine Learning) لتدريب النظم على البيانات دون برمجة صريحة، وبداخله التعلم العميق (Deep Learning) بالشبكات العصبية متعددة الطبقات، وفي قلبه اليوم الذكاء الاصطناعي التوليدي (Generative AI) لإنشاء نصوص وصور وأكواد جديدة كلياً.', 'Artificial Intelligence is the broad umbrella science of creating machines that simulate human cognitive intelligence. Inside AI sits Machine Learning, where systems learn mathematical patterns from training data rather than following hardcoded rules. Within ML lies Deep Learning, which uses deep multi-layered Artificial Neural Networks. And inside Deep Learning sits Generative AI, capable of producing entirely new text, images, and audio from user prompts.', 'عاش يا بطل! استوعبت شكل الهرمية المتداخلة بين الذكاء الاصطناعي وتعلم الآلة والتعلم العميق والتوليدي؟ تحب نختبر فهمك؟', 'الذكاء الاصطناعي مثل شجرة ضخمة: جذعها هو الذكاء الاصطناعي، فرعها الرئيسي هو تعلم الآلة، أغصانها هي التعلم العميق، وأحدث ثمارها العبقرية هو الذكاء التوليدي!', '[{"term":"الذكاء الاصطناعي (AI)","en":"Artificial Intelligence","definition":"المجال العام في علوم الحاسوب الذي يهدف لبناء أنظمة وبرمجيات قادرة على محاكاة القدرات الذهنية البشرية كالتفكير والتعلم والاستنتاج.","example":"المساعدات الصوتية الذكية وأنظمة التعرف على الوجوه.","examTip":"المظلة الكبرى التي تشمل بداخلها التعلم الآلي والتعلم العميق."},{"term":"الذكاء الاصطناعي التوليدي","en":"Generative AI","definition":"نماذج متطورة من التعلم العميق قادرة على ابتكار وإنشاء محتوى جديد تماماً (نصوص، صور، فيديو، صوت، أكواد برمجة).","example":"ChatGPT, Gemini, Midjourney.","examTip":"يقع في أدق وأحدث طبقات هرمية الذكاء الاصطناعي اليوم."}]'::jsonb, '[{"type":"concept","title":"هرمية الذكاء الاصطناعي ذات الطبقات الأربعة المتداخلة:","points":["🌐 1. الذكاء الاصطناعي (AI): المظلة الشاملة لمحاكاة السلوك الذكي.","📊 2. تعلم الآلة (ML): تدريب الخوارزميات على استخراج الأنماط من البيانات.","🧠 3. التعلم العميق (DL): استخدام شبكات عصبية اصطناعية عميقة متعددة الطبقات تحاكي خلايا المخ.","✨ 4. الذكاء التوليدي (GenAI): توليد محتوى إبداعي جديد بناءً على تدريب ملياري."]},{"type":"teacherTip","title":"💡 معادلة م / محمد راشد الذهبية:","text":"الذكاء الاصطناعي (المحيط) ⊃ تعلم الآلة (البحر) ⊃ التعلم العميق (البحيرة) ⊃ الذكاء التوليدي (الينبوع المبدع)!"}]'::jsonb)
ON CONFLICT (id) DO UPDATE SET chunk_title = EXCLUDED.chunk_title, summary = EXCLUDED.summary, key_terms = EXCLUDED.key_terms, content_cards = EXCLUDED.content_cards;
INSERT INTO public.chunks (id, chapter_id, lesson_id, chunk_index, chunk_title, en_chunk_title, type, icon_emoji, xp_reward, stars_reward, summary, audio_narration_text, en_audio_narration_text, ai_tutor_prompt, simplified_explanation, key_terms, content_cards)
VALUES ('ch1-l2-c2', 1, '1-2', 2, 'الأنماط الثلاثة لتعلم الآلة: الموجه وغير الموجه والتعزيزي', 'Artificial Neural Networks (ANN): Input, Hidden & Output Layers', 'chunk', '⚡', 35, 1, 'خوارزميات التعلم الثلاث: التعلم الخاضع للإشراف (Supervised - ببيانات موسومة)، غير الخاضع للإشراف (Unsupervised - استكشاف أنماط وتجميع)، والتعلم التعزيزي (Reinforcement - مكافأة وعقاب).', 'كيف تتعلم الآلة؟ هناك ثلاث طرق رئيسية معتمدة: أولاً، التعلم الموجه أو الخاضع للإشراف، حيث نقدم للآلة بيانات ومعها الإجابة الصحيحة كالمعلم الذي يصحح للطالب. ثانياً، التعلم غير الخاضع للإشراف، حيث نقدم بيانات بدون تسميات ونترك الآلة تستكشف المجموعات والأنماط المخفية بنفسها. ثالثاً، التعلم التعزيزي، حيث تتعلم الآلة بالتجربة والخطأ عبر نظام المكافآت والعقوبات مثل تدريب الروبوتات على المشي أو الفوز في ألعاب الشطرنج.', 'Artificial Neural Networks are computational architectures inspired by biological brain neurons. An ANN consists of three principal layers: first, the Input Layer which ingests raw data features. Second, one or more Hidden Layers that calculate weighted sums, apply non-linear mathematical activation functions, and extract deep features. Third, the Output Layer which produces final classifications or predictions. During training, the network adjusts its connection weights using an algorithm called Backpropagation.', 'عظيم يا بطل! هل تفرّق بين التعلم الموجه وغير الموجه والتعزيزي من حيث نوع البيانات ودور المكافأة؟', 'إذا أعطيت الحاسوب صور قطط ومكتوب عليها ''قطة'' فهذا تعلم موجه. وإذا أعطيته صوراً كثيرة وقلت له رتب المتشابهين فهذا غير موجه. وإذا دربته على قيادة سيارة وأعطيته نقطة لكل ثانية دون اصطدام فهذا تعزيزي!', '[{"term":"التعلم الخاضع للإشراف","en":"Supervised Learning","definition":"تدريب النموذج على بيانات موسومة (Labeled Data) تتضمن المدخلات ومخرجاتها المستهدفة الصحيحة.","example":"توقع أسعار المنازل بناءً على مساحتها، أو تصنيف رسائل البريد (مهم / غير مرغوب Spam).","examTip":"يستخدم لحل مشاكل التصنيف (Classification) والانحدار (Regression)."},{"term":"التعلم التعزيزي","en":"Reinforcement Learning","definition":"تعلم الوكيل البرمجي (Agent) عبر التفاعل مع البيئة وتجربة القرارات لتعظيم المكافآت (Rewards) وتقليل العقوبات.","example":"روبوت يتعلم تخطي العقبات، أو نظام AlphaGo في لعبة جو.","examTip":"يعتمد على المحاولة والخطأ ودالة المكافأة/العقاب."}]'::jsonb, '[{"type":"concept","title":"الأنماط الثلاثة لتعلم الآلة في مقارنة حاسمة:","points":["🎯 1. الموجه (Supervised): بيانات موسومة (Labels) ← تصنيف وتوقع قيم مستقبلية.","🔍 2. غير الموجه (Unsupervised): بيانات غير موسومة ← كشف الأنماط، والتجميع (Clustering).","🎮 3. التعزيزي (Reinforcement): بيئة تفاعلية + نظام مكافأة وعقاب ← اتخاذ قرارات متتابعة."]},{"type":"teacherTip","title":"💡 تشبيه م / محمد راشد للأنماط الثلاثة:","text":"الموجه مثل طالب يذاكر ومعه كتاب الإجابات النموذجية؛ غير الموجه مثل محقق يبحث عن خيوط جريمة غامضة؛ والتعزيزي مثل طفل يتعلم المشي ويقفز فرحاً إذا نجح ويتفادى السقوط!"}]'::jsonb)
ON CONFLICT (id) DO UPDATE SET chunk_title = EXCLUDED.chunk_title, summary = EXCLUDED.summary, key_terms = EXCLUDED.key_terms, content_cards = EXCLUDED.content_cards;
INSERT INTO public.chunks (id, chapter_id, lesson_id, chunk_index, chunk_title, en_chunk_title, type, icon_emoji, xp_reward, stars_reward, summary, audio_narration_text, en_audio_narration_text, ai_tutor_prompt, simplified_explanation, key_terms, content_cards)
VALUES ('ch1-l2-c3', 1, '1-2', 3, 'الشبكات العصبية الاصطناعية (ANN) وبنية الطبقات', 'Generative AI, Hallucinations, and Verification', 'chunk', '🤖', 35, 1, 'محاكاة الخلايا العصبية البيولوجية: طبقة المدخلات (Input Layer)، الطبقات المخفية (Hidden Layers)، طبقة المخرجات (Output Layer)، ودور الأوزان والانحياز ودوال التنشيط.', 'الشبكات العصبية الاصطناعية تحاكي تشابك خلايا المخ البشري: تتكون من عُقد متصلة موزعة على ثلاث طبقات رئيسية: طبقة المدخلات لاستقبال البيانات، وطبقات مخفية في المنتصف تستخرج الأنماط والملامح المعقدة، وأخيراً طبقة المخرجات لتقديم القرار أو التوقع النهائي. وكل اتصال يحمل وزناً رقمياً يتعدل أثناء التدريب، بالإضافة إلى دوال التنشيط التي تحدد متى تنشط الخلية العصبية الرقمية.', 'Generative AI models, such as Large Language Models, generate responses by predicting the statistically most probable next word or token. Because they predict probabilities rather than verifying truth, they are prone to AI Hallucinations—producing fabricated statements that sound convincingly authoritative. Students must therefore always apply critical thinking and human fact-checking to any AI-generated output.', 'ممتاز يا بطل! عرفت دور الطبقات المخفية في استخراج الملامح تدريجياً؟ تحب نبدأ أسئلتها؟', 'الشبكة العصبية مثل لجنة مصغرة: في البداية يستلم الأعضاء الملف (مدخلات)، يمررونه للمساعدين في الغرف المغلقة للتحليل والتدقيق (طبقات مخفية)، وأخيراً يخرج المتحدث الرسمي بالقرار النهائي (مخرجات)!', '[{"term":"الطبقات المخفية","en":"Hidden Layers","definition":"الطبقات الواقعة بين المدخلات والمخرجات داخل الشبكة العصبية، ومسؤوليتها استخراج الميزات الحسابية والأنماط المعقدة تدريجياً.","example":"في التعرف على الوجوه: طبقة تكتشف الحواف، تليها طبقة تكتشف العين والأنف، ثم طبقة تدرك الوجه كاملاً.","examTip":"كلما زادت الطبقات المخفية، أصبحت الشبكة ''عميقة'' (Deep Neural Network)."},{"term":"دالة التنشيط","en":"Activation Function","definition":"معادلة رياضية تحدد ما إذا كانت الخلية العصبية ستمرر الإشارة للطبقة التالية أم لا، وتضفي صفة اللاخطية (Non-linearity) على النموذج.","example":"دوال مثل ReLU و Sigmoid.","examTip":"بدونها تكون الشبكة مجرد معادلة خطية بسيطة غير قادرة على حل المشكلات المعقدة."}]'::jsonb, '[{"type":"concept","title":"التشريح الهندسي للشبكة العصبية الاصطناعية:","points":["📥 1. طبقة المدخلات (Input Layer): تستقبل البيانات الأولية (قيم بكسلات الصورة، نصوص، أرقام).","⚙️ 2. الطبقات المخفية (Hidden Layers): معالجة الأوزان (Weights) وحساب الأنماط المعقدة.","📤 3. طبقة المخرجات (Output Layer): إعطاء النتيجة النهائية (مثلاً: 98% هذا قط).","🔄 4. الانتشار الخلفي (Backpropagation): خوارزمية تعديل الأوزان لتقليل نسبة الخطأ."]}]'::jsonb)
ON CONFLICT (id) DO UPDATE SET chunk_title = EXCLUDED.chunk_title, summary = EXCLUDED.summary, key_terms = EXCLUDED.key_terms, content_cards = EXCLUDED.content_cards;
INSERT INTO public.chunks (id, chapter_id, lesson_id, chunk_index, chunk_title, en_chunk_title, type, icon_emoji, xp_reward, stars_reward, summary, audio_narration_text, en_audio_narration_text, ai_tutor_prompt, simplified_explanation, key_terms, content_cards)
VALUES ('ch1-l2-exam', 1, '1-2', 4, '🏆 التحدي الختامي: اختبار إتقان الدرس (1-2) الشامل', '🏆 Final Challenge: Lesson (1-2) Mastery Exam', 'lesson_exam', '⏳', 100, 3, 'اختبار وزاري شامل يجمع مفاهيم الدرس (1-2): هرمية الذكاء الاصطناعي، أنماط تعلم الآلة الثلاثة، وبنية الشبكات العصبية.', 'وصلت للتحدي النهائي للدرس الثاني! استعد لخوض هذا الاختبار الامتحاني الشامل لإثبات إتقانك لكيفية عمل الذكاء الاصطناعي وخوارزمياته!', 'Welcome to the Lesson 1-2 Mastery Challenge! Test your deep understanding of neural networks, machine learning paradigms, and generative AI to claim your trophy!', '', '', '[]'::jsonb, '[]'::jsonb)
ON CONFLICT (id) DO UPDATE SET chunk_title = EXCLUDED.chunk_title, summary = EXCLUDED.summary, key_terms = EXCLUDED.key_terms, content_cards = EXCLUDED.content_cards;
INSERT INTO public.chunks (id, chapter_id, lesson_id, chunk_index, chunk_title, en_chunk_title, type, icon_emoji, xp_reward, stars_reward, summary, audio_narration_text, en_audio_narration_text, ai_tutor_prompt, simplified_explanation, key_terms, content_cards)
VALUES ('ch1-l3-c1', 1, '1-3', 1, 'تطبيقات الذكاء الاصطناعي في الصحة والطب والتعليم', 'AI in Healthcare, Personalized Medicine & Adaptive Learning', 'chunk', '🏥', 35, 1, 'تحليل الأشعة والتشخيص المبكر للأمراض، اكتشاف الأدوية وتسريع التجارب، ومنظومات التعلم التكيفي المخصص لكل طالب.', 'أحدث الذكاء الاصطناعي ثورة إنقاذية في القطاع الطبي؛ حيث أصبحت الخوارزميات قادرة على فحص آلاف صور الرنين المغناطيسي والأشعة في ثوانٍ بدقة تفوق أحياناً العين البشرية لاكتشاف الأورام في مراحلها المبكرة، وتسريع تصميم وتركيب جزيئات الأدوية الجديدة. وفي التعليم، فتح الذكاء الاصطناعي الباب لمنصات التعلم التكيفي التي تصمم مساراً تعليمياً مخصصاً لكل طالب وفق نقاط قوته وسرعة استيعابه.', 'Artificial intelligence has transformed healthcare and education: In medicine, AI models analyze radiographic imagery (X-rays, MRIs, and CT scans) to detect early-stage oncological tumors with remarkable diagnostic accuracy, and accelerate drug discovery from decades to months. In education, intelligent adaptive learning platforms track individual student progress and dynamically calibrate lesson difficulty.', 'عظيم يا بطل! كيف يسهم الذكاء الاصطناعي في إنقاذ الأرواح وتحسين التعليم؟ تحب نخوض التحدي؟', 'في الطب: الذكاء الاصطناعي مثل مجهر ذكي يرى أصغر خلية مريضة قبل أن يراها الطبيب. وفي التعليم: مثل معلم خصوصي يجلس بجوارك ويفهم سرعتك وأسلوبك المفضل في الفهم!', '[{"term":"التشخيص الطبي المعزز بالذكاء الاصطناعي","en":"AI Medical Diagnostics","definition":"استخدام خوارزميات الرؤية الحاسوبية والتعلم العميق لتحليل الصور الطبية والفحوصات لاكتشاف الأمراض بدقة وسرعة فائقة.","example":"اكتشاف أمراض اعتلال الشبكية أو أورام الرئة في مراحل مبكرة جداً.","examTip":"الهدف هو مساعدة الطبيب وتعزيز قدرته وليس الاستغناء الكامل عن الخبرة الطبية البشرية."},{"term":"التعلم التكيفي","en":"Adaptive Learning","definition":"نظام تعليمي رقمي ذكي يغير صعوبة المحتوى والتمارين وسرعة الشرح تلقائياً بناءً على أداء واستجابة كل طالب.","example":"تطبيقات اللغات مثل Duolingo ومنصات المناهج الذكية.","examTip":"يحقق الفردية وتكافؤ الفرص في التحصيل الأكاديمي."}]'::jsonb, '[{"type":"concept","title":"مجالات التطبيق في الصحة والتعليم:","points":["🏥 الصحة: تحليل الأشعة المقطعية، التنبؤ بالانتكاسات الصحية، وتصميم أدوية مخصصة للجينات.","📚 التعليم: المنصات التكيفية الذكية، التقييم الآلي الفوري للواجبات، وتوفير مساعد ذكي لكل طالب طوال 24 ساعة."]}]'::jsonb)
ON CONFLICT (id) DO UPDATE SET chunk_title = EXCLUDED.chunk_title, summary = EXCLUDED.summary, key_terms = EXCLUDED.key_terms, content_cards = EXCLUDED.content_cards;
INSERT INTO public.chunks (id, chapter_id, lesson_id, chunk_index, chunk_title, en_chunk_title, type, icon_emoji, xp_reward, stars_reward, summary, audio_narration_text, en_audio_narration_text, ai_tutor_prompt, simplified_explanation, key_terms, content_cards)
VALUES ('ch1-l3-c2', 1, '1-3', 2, 'تطبيقات الذكاء الاصطناعي في النقل والتصنيع والمدن الذكية', 'Predictive Maintenance, Smart Manufacturing & Smart Cities', 'chunk', '🏭', 35, 1, 'إدارة إشارات المرور الذكية، التنبؤ بأعطال المصانع (الصيانة التنبؤية Predictive Maintenance)، والروبوتات الصناعية في خطوط الإنتاج.', 'في قطاع النقل، يحلل الذكاء الاصطناعي بيانات الحركة المرورية من الكاميرات والمستشعرات لضبط توقيت إشارات المرور آلياً وتقليل الاختناقات وحوادث الطرق. وفي قطاع الصناعة، أحدثت تقنية الصيانة التنبؤية نقلة نوعية؛ حيث ترصد الحساسات اهتزازات وحرارة الآلات وتتنبأ بالعطل قبل وقوعه بأسابيع، مما يوفر مليارات الدولارات ويمنع توقف خطوط الإنتاج، بجانب الروبوتات الذكية التي تتعاون مع العمال بأمان.', 'In industrial and urban domains, AI enables Predictive Maintenance: IoT sensors continuously monitor vibration, temperature, and wear on industrial machines, allowing AI to forecast component failures before breakdowns occur. In Smart Cities, AI optimizes dynamic traffic light signaling to alleviate urban congestion, and manages power grids to minimize carbon emissions.', 'رائع يا بطل! كيف تمنع الصيانة التنبؤية كوارث التوقف في المصانع؟ جاهز لتحدي الأسئلة؟', 'الصيانة القديمة كانت تنتظر حتى تنكسر الماكينة لتصلحها، أو تغير قطع غيار سليمة بدون داعٍ. الصيانة التنبؤية مثل طبيب يسمع نبض الآلة ويقول: هذه القطعة ستتعب بعد أسبوع، غيرها الآن وأنت مستريح!', '[{"term":"الصيانة التنبؤية","en":"Predictive Maintenance","definition":"تقنية تعتمد على الذكاء الاصطناعي ومستشعرات إنترنت الأشياء (IoT) للتنبؤ بأعطال الماكينات قبل حدوثها وإجراء الصيانة في الوقت المثالي.","example":"تنبيه مصنع بأن توربين معين سيتعطل بعد 15 يوماً بسبب ارتفاع طفيف في اهتزاز التروس.","examTip":"توفر تكاليف الصيانة الدورية وتمنع التوقف المفاجئ للمصانع."},{"term":"المدن الذكية","en":"Smart Cities","definition":"مدن حضرية تستخدم تكنولوجيا المعلومات وإنترنت الأشياء والذكاء الاصطناعي لإدارة الموارد والطاقة والمرور والنفايات بكفاءة واستدامة.","example":"التحكم في إضاءة الشوارع حسب وجود المشاة والسيارات.","examTip":"تسهم في تقليل التلوث وترشيد استهلاك الطاقة وتسهيل حياة المواطنين."}]'::jsonb, '[{"type":"concept","title":"التطبيقات الصناعية والحضرية البارزة:","points":["🚦 النقل الذكي: تحسين مسارات الشحن، تقليل الازدحام بنسب تصل لـ 30%، وتنسيق أساطيل الحافلات.","🏭 التصنيع الذكي: خطوط إنتاج ذاتية التعديل، فحص الجودة بالرؤية الحاسوبية، والصيانة التنبؤية.","🏙️ المدن الذكية: ترشيد شبكات الكهرباء والمياه، والاستجابة السريعة لحالات الطوارئ."]}]'::jsonb)
ON CONFLICT (id) DO UPDATE SET chunk_title = EXCLUDED.chunk_title, summary = EXCLUDED.summary, key_terms = EXCLUDED.key_terms, content_cards = EXCLUDED.content_cards;
INSERT INTO public.chunks (id, chapter_id, lesson_id, chunk_index, chunk_title, en_chunk_title, type, icon_emoji, xp_reward, stars_reward, summary, audio_narration_text, en_audio_narration_text, ai_tutor_prompt, simplified_explanation, key_terms, content_cards)
VALUES ('ch1-l3-exam', 1, '1-3', 3, '🏆 التحدي الختامي: اختبار إتقان الدرس (1-3) الشامل', '🏆 Final Challenge: Lesson (1-3) Mastery Exam', 'lesson_exam', '⏳', 100, 3, 'اختبار امتحاني شامل يغطي تطبيقات الذكاء الاصطناعي في الطب، التعليم، النقل، والصيانة التنبؤية والمدن الذكية.', 'وصلت لاختبار إتقان الدرس الثالث! أجب عن الأسئلة الامتحانية لتنال كأس التميز وتفتح الدرس الرابع من الفصل الأول!', 'You have reached the Lesson 1-3 Mastery Exam! Show your expertise in industrial AI applications, healthcare technologies, and smart city infrastructure to earn your gold trophy!', '', '', '[]'::jsonb, '[]'::jsonb)
ON CONFLICT (id) DO UPDATE SET chunk_title = EXCLUDED.chunk_title, summary = EXCLUDED.summary, key_terms = EXCLUDED.key_terms, content_cards = EXCLUDED.content_cards;
INSERT INTO public.chunks (id, chapter_id, lesson_id, chunk_index, chunk_title, en_chunk_title, type, icon_emoji, xp_reward, stars_reward, summary, audio_narration_text, en_audio_narration_text, ai_tutor_prompt, simplified_explanation, key_terms, content_cards)
VALUES ('ch1-l4-c1', 1, '1-4', 1, 'التحيز الخوارزمي وعدالة البيانات (Algorithmic Bias)', 'Algorithmic Bias, Fairness & Accountability', 'chunk', '⚖️', 35, 1, 'كيف ينتقل التحيز البشري إلى الخوارزميات عبر بيانات التدريب غير المتوازنة، ومخاطر التمييز في التوظيف والقروض والقضاء.', 'الذكاء الاصطناعي لا ينشأ محايداً بذاته؛ بل يعكس بدقة طبيعة البيانات التي تم تدريبه عليها! فإذا كانت بيانات التدريب تحتوي على تحيزات بشرية أو تمثيلاً ناقصاً لفئة معينة، ستتعلم الخوارزمية هذا التحيز وتكرره في قراراتها، كأن تفضل فئة معينة في التوظيف أو تقييم القروض. ولذلك يُعد التحيز الخوارزمي وعدالة البيانات من أخطر القضايا الأخلاقية التي تستوجب مراجعة دقيقة وتدقيقاً مستمراً للبيانات.', 'Because artificial intelligence learns from human-generated historical data, it can absorb, amplify, and perpetuate systemic social prejudices—a dilemma known as Algorithmic Bias. If a loan assessment or hiring algorithm is trained on biased historical records, it will discriminate against certain demographic groups. Ethical AI mandates Fairness, Accountability, and Explainability (XAI) so human stakeholders understand how decisions are reached.', 'عاش يا بطل! استوعبت ليه الآلة ممكن تكون متحيزة إذا درّبناها ببيانات غير عادلة؟ جاهز للأسئلة؟', 'الذكاء الاصطناعي مثل طفل صغير يتعلم مما يراه حوله: لو ربيته في بيئة تشاهد لوناً واحداً فقط وتكره باقي الألوان، سيكبر وهو يظن أن هذا هو الصواب! الخوارزمية مرآة لبياناتنا!', '[{"term":"التحيز الخوارزمي","en":"Algorithmic Bias","definition":"حدوث أخطاء منهجية ومتكررة في نظام الذكاء الاصطناعي تؤدي لمعاملة غير عادلة أو تفضيل فئة ضد أخرى نتيجة تحيز بيانات التدريب.","example":"خوارزمية توظيف تستبعد طلبات النساء لأن بيانات التوظيف التاريخية كانت أغلبيتها رجالاً.","examTip":"السبب الرئيسي للتحيز الخوارزمي هو عدم توازن أو عدالة بيانات التدريب البشرية."},{"term":"عدالة البيانات","en":"Data Fairness","definition":"ضمان تمثيل جميع الفئات المجتمعية بنزاهة وتوازن في مجموعات البيانات المستخدمة لتدريب النماذج.","example":"تدريب نظام التعرف على الوجوه بصور تمثل كل الأعراق والأعمار والظروف.","examTip":"الحل التقني الأول لمنع التمييز الآلي."}]'::jsonb, '[{"type":"concept","title":"أسباب ومظاهر التحيز الخوارزمي:","points":["📉 بيانات التدريب غير المتوازنة: نقص تمثيل فئات معينة يقلل دقة النموذج معها.","⚖️ تكرار التحيزات التاريخية: الخوارزمية تتعلم التمييز الموجود تاريخياً وتضخمه.","🚨 مجالات الخطر: قرارات التوظيف، الموافقات الائتمانية، والتشخيص الطبي."]}]'::jsonb)
ON CONFLICT (id) DO UPDATE SET chunk_title = EXCLUDED.chunk_title, summary = EXCLUDED.summary, key_terms = EXCLUDED.key_terms, content_cards = EXCLUDED.content_cards;
INSERT INTO public.chunks (id, chapter_id, lesson_id, chunk_index, chunk_title, en_chunk_title, type, icon_emoji, xp_reward, stars_reward, summary, audio_narration_text, en_audio_narration_text, ai_tutor_prompt, simplified_explanation, key_terms, content_cards)
VALUES ('ch1-l4-c2', 1, '1-4', 2, 'الخصوصية، معضلة الصندوق الأسود، والمسؤولية القانونية', 'AI Governance, Regulations & The AI Act', 'chunk', '📦', 35, 1, 'حماية البيانات الشخصية، مشكلة الصندوق الأسود (Black Box Problem) وصعوبة تفسير القرارات، ومن يتحمل المسؤولية القانونية عند وقوع أخطاء؟', 'تواجه حوكمة الذكاء الاصطناعي ثلاثة تحديات جوهرية: أولاً، حماية الخصوصية ومنع استغلال بيانات الأفراد دون موافقتهم الصريحة. ثانياً، معضلة الصندوق الأسود، حيث تصل الشبكات العصبية العميقة لقرارات بالغة التعقيد دون أن يتمكن حتى المهندسون من شرح ''لماذا اتخذت الآلة هذا القرار بالتحديد؟''؛ مما يثير قلقاً في الطب والقضاء. وثالثاً، المسؤولية القانونية: لو تسببت سيارة ذاتية القيادة في حادث، فمن المسؤول؟ المبرمج أم الشركة المصنعة أم الراكب؟', 'To prevent technological abuses, global governments and international institutions have enacted rigorous AI Governance frameworks, such as the European Union''s Artificial Intelligence Act (AI Act). These regulations categorize AI deployments into distinct risk tiers: Unacceptable Risk systems (like biometric social scoring) which are strictly outlawed, High-Risk systems (in healthcare, policing, and employment) requiring strict audits and data controls, and Low-Risk systems requiring basic transparency.', 'عظيم يا بطل! لماذا تمثل معضلة الصندوق الأسود تحدياً كبيراً في الطب والقضاء؟ تحب نراجعها؟', 'لو أن طبيباً قال لك: ''عليك إجراء جراحة عاجلة لكن لا أعرف السبب والكمبيوتر قال هكذا!'' هل ستوافق؟ بالتأكيد لا! لذلك يجب أن يكون الذكاء الاصطناعي شفافاً ويشرح أسبابه بدلاً من الصندوق الأسود المغلق!', '[{"term":"معضلة الصندوق الأسود","en":"Black Box Problem","definition":"عجز المطورين والمستخدمين عن فهم وتفسير الآلية الداخلية التي اتبعتها الشبكة العصبية العميقة للوصول إلى قرار معين.","example":"خوارزمية ترفض علاجاً لمريض دون إبداء أسباب طبية واضحة يمكن للطبيب مراجعتها.","examTip":"الحل المنشود في الأبحاث الحديثة هو الذكاء الاصطناعي القابل للتفسير (Explainable AI - XAI)."},{"term":"المسؤولية القانونية الأخلاقية","en":"Legal & Ethical Accountability","definition":"تحديد الطرف البشري أو المؤسسي المسؤول نظامياً وقانونياً عند وقوع أضرار أو أخطاء ناتجة عن قرارات الذكاء الاصطناعي.","example":"تحديد المسؤولية في حوادث السيارات ذاتية القيادة أو أخطاء التشخيص الآلي.","examTip":"القوانين الحديثة تؤكد أن المسؤولية تقع دائماً على عاتق البشر والشركات المطورة وليس الآلة المجردة."}]'::jsonb, '[{"type":"concept","title":"التحديات الأخلاقية الثلاثية:","points":["🔒 الخصوصية والبيانات: ضرورة التشفير وموافقة المستخدم الصريحة (Consent).","📦 الصندوق الأسود (Black Box): غياب الشفافية في القرارات المصيرية وصعوبة التفسير.","⚖️ المسؤولية والمساءلة: تشريعات أطر الذكاء الاصطناعي الموثوق (Trustworthy AI)."]}]'::jsonb)
ON CONFLICT (id) DO UPDATE SET chunk_title = EXCLUDED.chunk_title, summary = EXCLUDED.summary, key_terms = EXCLUDED.key_terms, content_cards = EXCLUDED.content_cards;
INSERT INTO public.chunks (id, chapter_id, lesson_id, chunk_index, chunk_title, en_chunk_title, type, icon_emoji, xp_reward, stars_reward, summary, audio_narration_text, en_audio_narration_text, ai_tutor_prompt, simplified_explanation, key_terms, content_cards)
VALUES ('ch1-l4-exam', 1, '1-4', 3, '🏆 التحدي الختامي: اختبار إتقان الدرس (1-4) الشامل', '🏆 Final Challenge: Lesson (1-4) Mastery Exam', 'lesson_exam', '⏳', 100, 3, 'اختبار امتحاني شامل يغطي أخلاقيات وحوكمة الذكاء الاصطناعي: التحيز الخوارزمي، عدالة البيانات، معضلة الصندوق الأسود، والمسؤولية القانونية.', 'وصلت للتحدي النهائي للدرس الرابع وختام الفصل الأول كاملاً! اجتيازك لهذا الاختبار يؤكد تمكنك من أخلاقيات وحوكمة الذكاء الاصطناعي، ويمنحك كأس الفصل الأول الذهبي!', 'Welcome to the Lesson 1-4 Mastery Challenge! Conclude Chapter 1 by proving your knowledge of AI ethics, fairness, and global governance regulations!', '', '', '[]'::jsonb, '[]'::jsonb)
ON CONFLICT (id) DO UPDATE SET chunk_title = EXCLUDED.chunk_title, summary = EXCLUDED.summary, key_terms = EXCLUDED.key_terms, content_cards = EXCLUDED.content_cards;
INSERT INTO public.chunks (id, chapter_id, lesson_id, chunk_index, chunk_title, en_chunk_title, type, icon_emoji, xp_reward, stars_reward, summary, audio_narration_text, en_audio_narration_text, ai_tutor_prompt, simplified_explanation, key_terms, content_cards)
VALUES ('ch2-l1-c1', 2, '2-1', 1, 'أهداف أمن المعلومات ومثلث CIA الثلاثي', 'Information Security Goals & The CIA Triad', 'chunk', '🔐', 35, 1, 'الركائز الثلاث لأمن المعلومات: السرية (Confidentiality)، السلامة والنزاهة (Integrity)، والتوافر (Availability).', 'مرحباً بك في الفصل الثاني: الأمن السيبراني! كل استراتيجية أمنية في العالم تقوم على مثلث شهير يُدعى ثالوث CIA: أولاً، السرية (Confidentiality) لضمان عدم اطلاع غير المصرح لهم على البيانات. ثانياً، السلامة والنزاهة (Integrity) للتأكد من أن البيانات لم يتم تعديلها أو العبث بها أثناء النقل. ثالثاً، التوافر (Availability) لضمان أن النظام والبيانات متاحة للمستخدمين الشرعيين في أي وقت دون انقطاع.', 'Welcome to Chapter 2 on Cybersecurity! Information security stands upon three universal pillars known as the CIA Triad: Confidentiality ensures sensitive information is shielded from unauthorized access through encryption. Integrity guarantees that data has not been altered or tampered with in transit or storage. And Availability ensures that critical systems remain resilient and accessible whenever authorized users need them.', 'عاش يا بطل! استوعبت أركان مثلث CIA الثلاثة لأمن المعلومات؟ تحب نختبرك فيها؟', 'تخيل أنك ترسل رسالة في صندوق مقفل: السرية أن القفل لا يفتحه إلا صديقك؛ السلامة أن محتوى الرسالة يصل دون شطب كلمة واحدة؛ والتوافر أن ساعي البريد يوصلها فوراً دون تأخير!', '[{"term":"مثلث CIA","en":"CIA Triad","definition":"النموذج الأمني العالمي المكون من ثلاث ركائز: السرية، سلامة البيانات، وتوافر الخدمة.","example":"تطبيق بنكي يضمن أن رصيدك سري، لم يُعدل فيه قرش واحد بالخطأ، والتطبيق يعمل 24 ساعة.","examTip":"سؤال متكرر: ما هي أركان مثلث أمن المعلومات الثلاثة؟ السرية، السلامة، والتوافر."},{"term":"سلامة البيانات","en":"Data Integrity","definition":"حماية البيانات من أي تعديل غير مصرح به أو تشويه أثناء التخزين أو الانتقال عبر الشبكة.","example":"استخدام دوال التجزئة (Hash) للتحقق من عدم تلاعب أحد بالملف.","examTip":"تُقاس وتُضمن بواسطة دوال الهاش والتوقيعات الرقمية."}]'::jsonb, '[{"type":"concept","title":"أركان مثلث أمن المعلومات CIA الثلاثة:","points":["🔒 السرية (Confidentiality): التشفير ومنع الوصول غير المصرح به للبيانات الحساسة.","🛡️ السلامة (Integrity): التحقق من عدم التلاعب بالبيانات أو تغييرها بأي شكل.","⚡ التوافر (Availability): صمود الأنظمة ضد هجمات حجب الخدمة لتبقى جاهزة للعمل دائماً."]}]'::jsonb)
ON CONFLICT (id) DO UPDATE SET chunk_title = EXCLUDED.chunk_title, summary = EXCLUDED.summary, key_terms = EXCLUDED.key_terms, content_cards = EXCLUDED.content_cards;
INSERT INTO public.chunks (id, chapter_id, lesson_id, chunk_index, chunk_title, en_chunk_title, type, icon_emoji, xp_reward, stars_reward, summary, audio_narration_text, en_audio_narration_text, ai_tutor_prompt, simplified_explanation, key_terms, content_cards)
VALUES ('ch2-l1-c2', 2, '2-1', 2, 'التشفير المتماثل والتشفير غير المتماثل (Symmetric vs Asymmetric)', 'Symmetric vs Asymmetric Encryption (Symmetric vs Asymmetric)', 'chunk', '🛡️', 35, 1, 'مقارنة التشفير بمفتاح واحد مشترك (Symmetric) والتشفير بزوج المفاتيح العام والخاص (Asymmetric / Public-Private Key).', 'التشفير هو تحويل النص المفهوم إلى نص مشفر غير مفهوم لحمايته: وينقسم لنوعين رئيسيين: التشفير المتماثل، ويستخدم مفتاحاً واحداً سرياً مشتركاً لنفس عمليتي التشفير وفك التشفير؛ ويتميز بالسرعة العالية لكن عيبه صعوبة مشاركة المفتاح بأمان. والنوع الثاني هو التشفير غير المتماثل، ويعتمد على زوجين من المفاتيح: المفتاح العام المتاح للجميع لتشفير الرسائل، والمفتاح الخاص السري الذي يحتفظ به المستلم وحده لفك التشفير.', 'Cryptographic encryption scrambles human-readable plaintext into unreadable ciphertext. In Symmetric Encryption (such as AES), the same secret key encrypts and decrypts the data—making it lightning fast for large files, but vulnerable to the key exchange problem. In Asymmetric Encryption (such as RSA), two mathematically linked keys are used: a Public Key that anyone can use to encrypt messages, and a secret Private Key held solely by the recipient to decrypt them.', 'عظيم يا بطل! عرفت الفرق بين التشفير بمفتاح واحد والتشفير بزوج المفاتيح العام والخاص؟ تحب نختبرك؟', 'التشفير المتماثل مثل قفل له مفتاح واحد متطابق معك ومع صديقك. أما التشفير غير المتماثل فصديقك يوزع أقفالاً مفتوحة للجميع (المفتاح العام)، وأي شخص يقفل الصندوق بقفل صديقك، وصديقك فقط هو من يملك المفتاح السري (الخاص) لفتحه!', '[{"term":"التشفير المتماثل","en":"Symmetric Encryption","definition":"نظام تشفير يستخدم مفتاحاً سرياً واحداً مشتركاً لتشفير البيانات وفك تشفيرها.","example":"خوارزمية AES الشهيرة لتشفير الأقراص الصلبة.","examTip":"سريع جداً في معالجة البيانات الضخمة ولكن مشكلته كيفية تبادل المفتاح السري بأمان."},{"term":"التشفير غير المتماثل","en":"Asymmetric Encryption","definition":"نظام تشفير يستخدم زوجين متكاملين رياضياً: مفتاح عام (Public Key) للتشفير، ومفتاح خاص (Private Key) لفك التشفير.","example":"خوارزمية RSA المستخدمة في بروتوكولات HTTPS وشهادات الأمان.","examTip":"يحل معضلة تبادل المفاتيح، ولكن عملياته الحسابية أبطأ من التشفير المتماثل."}]'::jsonb, '[{"type":"concept","title":"مقارنة حاسمة بين نوعي التشفير:","points":["🔑 التشفير المتماثل (Symmetric): مفتاح واحد مشترك • سريع جداً • عيبه نقل المفتاح السري.","🔐 التشفير غير المتماثل (Asymmetric): مفتاح عام ومفتاح خاص • آمن جداً في التبادل • أبطأ حسابياً.","🌐 الحل الهجين في الويب (HTTPS): استخدام غير المتماثل لتبادل مفتاح الجلسة، ثم إكمال الاتصال بالمتماثل للسرعة!"]}]'::jsonb)
ON CONFLICT (id) DO UPDATE SET chunk_title = EXCLUDED.chunk_title, summary = EXCLUDED.summary, key_terms = EXCLUDED.key_terms, content_cards = EXCLUDED.content_cards;
INSERT INTO public.chunks (id, chapter_id, lesson_id, chunk_index, chunk_title, en_chunk_title, type, icon_emoji, xp_reward, stars_reward, summary, audio_narration_text, en_audio_narration_text, ai_tutor_prompt, simplified_explanation, key_terms, content_cards)
VALUES ('ch2-l1-exam', 2, '2-1', 3, '🏆 التحدي الختامي: اختبار إتقان الدرس (2-1) الشامل', '🏆 Final Challenge: Lesson (2-1) Mastery Exam', 'lesson_exam', '⏳', 100, 3, 'اختبار امتحاني وزاري شامل مجمع يغطي مثلث CIA الأمني، والتشفير المتماثل وغير المتماثل وتقنيات المصادقة الرقمية.', 'وصلت لاختبار إتقان الدرس الأول من الفصل الثاني! أثبت جدارتك في أساسيات الأمن السيبراني والتشفير لتنال النجوم الثلاثة وتفتح الدرس التالي!', 'Welcome to the Lesson 2-1 Mastery Exam! Demonstrate your thorough knowledge of cryptographic algorithms, public-private keypairs, and the CIA Triad to claim your gold trophy!', '', '', '[]'::jsonb, '[]'::jsonb)
ON CONFLICT (id) DO UPDATE SET chunk_title = EXCLUDED.chunk_title, summary = EXCLUDED.summary, key_terms = EXCLUDED.key_terms, content_cards = EXCLUDED.content_cards;
INSERT INTO public.chunks (id, chapter_id, lesson_id, chunk_index, chunk_title, en_chunk_title, type, icon_emoji, xp_reward, stars_reward, summary, audio_narration_text, en_audio_narration_text, ai_tutor_prompt, simplified_explanation, key_terms, content_cards)
VALUES ('ch2-l2-c1', 2, '2-2', 1, 'عناصر أمان الشبكة: جدار الحماية، VPN، والمنطقة المعزولة DMZ', 'Network Security Elements: Firewalls, VPN & The DMZ', 'chunk', '🧱', 35, 1, 'مراقبة حركة المرور بجدار الحماية (Firewall)، وتأمين الاتصال عن بُعد عبر شبكة خاصة مشفرة (VPN)، وعزل الخوادم العامة في المنطقة المعزولة (DMZ).', 'أهلاً بك في الدرس الثاني من الفصل الثاني في هذه المحطة التعليمية! كيف تصمم المؤسسة شبكة آمنة تصمد أمام الاختراقات؟ نستخدم ثلاثة عناصر أساسية: أولاً جدار الحماية Firewall الذي يراقب حركة البيانات ويسمح بها أو يمنعها استناداً لقواعد محددة. ثانياً، الشبكة الافتراضية الخاصة VPN التي تنشئ نفقاً مشفراً يتيح للموظف الاتصال الآمن بشبكة الشركة من المنزل أو عبر شبكات الواي فاي العامة. وثالثاً، المنطقة المعزولة DMZ، وهي شبكة فرعية منفصلة نضع فيها خوادم الويب العامة لعزلها عن الشبكة الداخلية الحساسة وقواعد البيانات.', 'Network security safeguards data moving across digital conduits: A Firewall inspects incoming and outgoing network traffic, filtering packets based on IP addresses, port numbers, and connection states. To securely publish public-facing servers (such as web or email servers), organizations isolate them in a Demilitarized Zone (DMZ)—a neutral perimeter subnet situated between the untrusted internet and the trusted internal corporate network. Virtual Private Networks (VPN) create encrypted tunnels across public networks.', 'عاش يا بطل! استوعبت دور جدار الحماية و VPN ولماذا نعزل خادم الويب في DMZ؟ جاهز للأسئلة؟', 'جدار الحماية هو الحارس على البوابة، والـ VPN هو سيارة مصفحة تنقلك في شارع عام، والـ DMZ هي غرفة استقبال معزولة للغرباء حتى لا يدخلوا غرف نوم البيت!', '[{"term":"جدار الحماية","en":"Firewall","definition":"نظام أو برنامج يراقب حركة مرور الشبكة ويسمح بها أو يمنعها عند نقطة دخول أو خروج الشبكة استناداً إلى قواعد أمنية محددة مسبقاً.","example":"السماح بالوصول لخادم الويب ومنع الوصول المباشر من الإنترنت لقاعدة البيانات.","examTip":"سؤال وزاري: يسمح بالاتصال أو يمنعه استناداً لقواعد محددة مسبقاً (ص 40)."},{"term":"الشبكة الافتراضية الخاصة","en":"VPN","definition":"اتصال أو شبكة منطقية خاصة عبر شبكة عامة كالإنترنت، تستخدم التشفير وتقنيات النفق لنقل البيانات بأمان وحمايتها من التنصت.","example":"اتصال الموظف بشبكة المؤسسة من المنزل بأمان تام عبر Wi-Fi عام.","examTip":"يقلل مخاطر التنصت وسرقة البيانات، ولا يقوم بحذف الفيروسات (ص 43)."},{"term":"المنطقة المعزولة","en":"DMZ (Demilitarized Zone)","definition":"شبكة فرعية توضع فيها الخوادم المعرضة للشبكة الخارجية (كالويب والبريد) معزولة عن الشبكة الداخلية وقواعد البيانات.","example":"خادم الويب يقع بين جداري حماية، فلو تم اختراقه تظل قواعد البيانات الداخلية محمية.","examTip":"الهدف: تقليل احتمال وصول الهجوم للشبكة الداخلية عند سقوط خادم عام."}]'::jsonb, '[{"type":"concept","title":"العناصر الثلاثة لتأمين الشبكة (كتاب الوزارة ص 40):","points":["🧱 جدار الحماية (Firewall): نقطة حراسة عند الحدود لمنع الاتصالات غير المصرح بها.","🔒 الشبكة الافتراضية (VPN): نفق مشفر لتأمين العمل عن بُعد وربط الفروع.","🛡️ المنطقة المعزولة (DMZ): عزل الخوادم المواجهة للجمهور لحماية القلب الداخلي."]},{"type":"teacherTip","title":"💡 مفتاح الفهم الامتحاني:","text":"الـ DMZ مثل صالة الاستقبال في الفندق؛ الضيوف يدخلونها بحرية، لكنها معزولة بأبواب سرية عن خزائن وإدارة الفندق الداخلية!"}]'::jsonb)
ON CONFLICT (id) DO UPDATE SET chunk_title = EXCLUDED.chunk_title, summary = EXCLUDED.summary, key_terms = EXCLUDED.key_terms, content_cards = EXCLUDED.content_cards;
INSERT INTO public.chunks (id, chapter_id, lesson_id, chunk_index, chunk_title, en_chunk_title, type, icon_emoji, xp_reward, stars_reward, summary, audio_narration_text, en_audio_narration_text, ai_tutor_prompt, simplified_explanation, key_terms, content_cards)
VALUES ('ch2-l2-c2', 2, '2-2', 2, 'الدفاع في العمق (Defense in Depth) ونهج انعدام الثقة (Zero Trust)', 'Defense in Depth & The Zero Trust Architecture', 'chunk', '🏰', 35, 1, 'الحماية متعددة الطبقات المتتالية لامتصاص الهجمات، ونهج انعدام الثقة (Zero Trust) القائم على التحقق المستمر من كل عملية وصول.', 'القاعدة الأمنية الذهبية في كتاب الوزارة تقول: لا تكفي وسيلة حماية واحدة أبداً في المؤسسات؛ فإذا فشلت أو تم اختراقها، تتعرض الشبكة بأكملها للخطر. لذلك يُصمم الأمان بمفهوم الدفاع في العمق لتتولى طبقات الحماية المتتالية امتصاص الهجوم؛ فلو اخترق مهاجم خادم الويب في DMZ، يمنعه جدار الحماية الداخلي والتشفير من الوصول لبيانات الرواتب! ومع انتشار الحوسبة السحابية والأجهزة المتنقلة، أصبح نهج انعدام الثقة Zero Trust أساسياً: لا تمنح الثقة تلقائياً لأي مستخدم أو جهاز حتى لو كان داخل مبنى الشركة، وافحص وتحقق من كل عملية وصول بدقة.', 'Modern cybersecurity recognizes that single security perimeters can be breached. Therefore, organizations employ Defense in Depth: layering multiple defensive safeguards—firewalls, endpoint antivirus, multi-factor authentication, data encryption, and employee awareness training. Furthermore, the modern paradigm has evolved to Zero Trust: ''Never Trust, Always Verify.'' Under Zero Trust, no user or device is trusted by default, even if they reside physically inside the internal corporate office.', 'ممتاز يا بطل! فهمت لماذا لا نعتمد على جدار الحماية وحده وما هو مبدأ Zero Trust؟', 'مثل القلعة القديمة: لا تكتفي بباب خارجي واحد؛ بل تضع خندق ماء، ثم سوراً أول، ثم حراساً، ثم أبواباً حديدية مقفلة داخلية؛ حتى لو كسر اللص الباب الأول يجد نفسه محاصراً أمام جدران أخرى!', '[{"term":"الدفاع في العمق","en":"Defense in Depth","definition":"استراتيجية تطبيق طبقات دفاعية متتالية ومتنوعة لحماية الأصول؛ بحيث إذا فشلت طبقة تصد الطبقات التالية المهاجم وتمنع وصوله للبيانات الحساسة.","example":"جدار حماية + شبكة VPN + منطقة DMZ + مكافحة فيروسات + تشفير البيانات.","examTip":"سؤال وزاري: لماذا يحمي تكديس الإجراءات المؤسسة أفضل من جدار الحماية وحده؟ (كتاب ص 43)."},{"term":"نهج انعدام الثقة","en":"Zero Trust","definition":"نموذج أمني يقوم على مبدأ ''لا تثق أبداً وتحقق دائماً''؛ حيث لا تُمنح الثقة تلقائياً لأي موقع أو جهاز أو مستخدم، وتُفحص كل عملية وصول.","example":"مطالبة الموظف بمصادقة ثنائية والتحقق من هوية جهازه عند كل محاولة دخول للملفات السحابية.","examTip":"سؤال اختر: الوصف الأدق لنهج Zero Trust هو فحص كل عملية وصول وعدم منح ثقة تلقائية (ص 44)."}]'::jsonb, '[{"type":"concept","title":"طبقات الدفاع الأربعة في المؤسسة (كتاب ص 43):","points":["🚪 مدخل الشبكة: جدار الحماية Firewall لفحص الحزم والتحكم بالمرور.","🛣️ مسار الاتصال: التشفير بنفق VPN لمنع التنصت الخارجي.","🏰 وضع الخوادم: عزل خوادم الويب في منطقة معزولة DMZ.","💻 الأجهزة الطرفية: برامج مكافحة الفيروسات والتحديثات والمصادقة الصارمة."]}]'::jsonb)
ON CONFLICT (id) DO UPDATE SET chunk_title = EXCLUDED.chunk_title, summary = EXCLUDED.summary, key_terms = EXCLUDED.key_terms, content_cards = EXCLUDED.content_cards;
INSERT INTO public.chunks (id, chapter_id, lesson_id, chunk_index, chunk_title, en_chunk_title, type, icon_emoji, xp_reward, stars_reward, summary, audio_narration_text, en_audio_narration_text, ai_tutor_prompt, simplified_explanation, key_terms, content_cards)
VALUES ('ch2-l2-exam', 2, '2-2', 3, '🏆 التحدي الختامي: اختبار إتقان الدرس (2-2) الشامل', '🏆 Final Challenge: Lesson (2-2) Mastery Exam', 'lesson_exam', '⏳', 100, 3, 'اختبار امتحاني وزاري شامل مجمع يغطي جدران الحماية، والـ VPN، والمنطقة المعزولة DMZ، والدفاع في العمق، ونهج Zero Trust.', 'وصلت لاختبار إتقان الدرس الثاني من الفصل الثاني! أجب عن الأسئلة الامتحانية الوزارية بنجاح لتنال كأس التميز وتفتح الدرس الثالث!', 'Welcome to the Lesson 2-2 Mastery Challenge! Test your deep understanding of network boundaries, firewall filtering, DMZ segmentation, and Zero Trust architectures to earn your gold trophy!', '', '', '[]'::jsonb, '[]'::jsonb)
