INSERT INTO public.chunks (id, chapter_id, lesson_id, chunk_index, chunk_title, en_chunk_title, type, icon_emoji, xp_reward, stars_reward, summary, audio_narration_text, en_audio_narration_text, ai_tutor_prompt, simplified_explanation, key_terms, content_cards)
VALUES ('ch2-l3-c1', 2, '2-3', 1, 'ماهية الحادث الأمني والمراحل الست للاستجابة المنهجية', 'Security Incidents & The 6-Stage NIST Incident Response Lifecycle', 'chunk', '🚨', 35, 1, 'مفهوم الحادث الأمني وانتهاك ثالوث CIA، والنموذج المنهجي للاستجابة عبر 6 مراحل: التحضير، الاكتشاف، الاحتواء، الاستئصال، الاستعادة، والدروس المستفادة.', 'مرحباً يا بطل في الدرس الثالث من الفصل الثاني! الحادث الأمني هو أي حدث ينتهك سرية المعلومات أو سلامتها أو توافرها أو يخالف السياسة الأمنية، مثل تسرب البيانات أو التلاعب بها أو انقطاع الخدمة بهجمات حجب الخدمة. وعند وقوع الحادث، تتبع المؤسسة ست مراحل منهجية منظمة: نبدأ بالتحضير وتدريب الفرق ووضع خطط الطوارئ مسبقاً، ثم الاكتشاف وتأكيد وقوع الحادث وتحديد نطاقه، يليه الاحتواء الفوري لعزل الأجهزة المصابة ومنع تفشي الضرر، ثم الاستئصال بإزالة البرمجيات الخبيثة وسد الثغرات، ثم الاستعادة وإعادة تشغيل الأنظمة بأمان من نسخ احتياطية نظيفة، وأخيراً توثيق الدروس المستفادة وتحسين الضوابط لمنع تكرار الكارثة!', 'A security incident occurs when an organization''s confidentiality, integrity, or availability is compromised. Organizations follow the standardized 6-stage Incident Response Lifecycle defined by NIST: Phase 1 is Preparation (establishing policies and CSIRT teams). Phase 2 is Detection & Analysis (identifying suspicious activity). Phase 3 is Containment (isolating infected machines to stop spread). Phase 4 is Eradication (removing malware and closing vulnerabilities). Phase 5 is Recovery (restoring systems from clean backups). And Phase 6 is Lessons Learned (documenting findings to prevent recurrence).', 'عاش يا بطل! رتبت مراحل الاستجابة الست وعرفت الفرق بين عزل المشكلة (الاحتواء) وإزالتها (الاستئصال)؟', 'لو اشتعلت نار في غرفة: أولاً نغلق باب الغرفة لعزل النار ومنع امتدادها للبيت (احتواء)، ثم نطفئ النار تماماً (استئصال)، ثم ننظف الغرفة ونفرشها من جديد (استعادة)، وأخيراً نركب جهاز إنذار حريق حتى لا يتكرر ذلك (دروس مستفادة)!', '[{"term":"الحادث الأمني","en":"Security Incident","definition":"حدث يؤثر في سرية المعلومات أو سلامتها أو توافرها (ثالوث CIA)، أو يهددها بجدية، أو يخالف سياسة أمنية معتمدة.","example":"تسرب بيانات العملاء، أو تعديل أرصدة البنوك، أو تعطيل موقع وزارة بهجوم DoS.","examTip":"سؤال وزاري: املأ الفراغ: يُسمى الحدث الذي يهدد سرية أو سلامة أو توافر البيانات بالحادث الأمني (ص 50)."},{"term":"الاحتواء","en":"Containment","definition":"المرحلة الثالثة في الاستجابة؛ وتستهدف عزل الجزء المتأثر (مثل فصل الجهاز عن الشبكة) للحد من انتشار الضرر إلى باقي الأنظمة.","example":"سحب كابل الإنترنت فوراً عن الخادم المصاب ببرمجية فدية لمنع إصابة بقية الخوادم.","examTip":"يجب أن يسبق مرحلة الاستئصال والاستعادة لمنع تفشي التهديد (كتاب ص 47)."},{"term":"الاستئصال","en":"Eradication","definition":"المرحلة الرابعة؛ وتتضمن إزالة التهديد ومسبباته جذرياً بحذف البرمجيات الخبيثة ومعالجة الثغرات الأمنية المستغلة.","example":"تنظيف الأقراص وتحديث البرمجيات وسد الثغرة البرمجية التي دخل منها المهاجم.","examTip":"الفرق بين الاحتواء والاستئصال: الاحتواء يعزل ويحاصر، والاستئصال يزيل ويطهر."}]'::jsonb, '[{"type":"concept","title":"المراحل الست للاستجابة للحوادث السيبرانية (كتاب ص 46–47):","points":["1️⃣ التحضير (Preparation): إعداد خطط الاستجابة وتدريب الفريق مسبقاً.","2️⃣ الاكتشاف (Detection): رصد التنبيهات وتأكيد الحادث وتحديد حجمه.","3️⃣ الاحتواء (Containment): عزل الأنظمة المصابة لمنع تفشي الهجوم.","4️⃣ الاستئصال (Eradication): حذف الملفات الخبيثة وسد الثغرات المستغلة.","5️⃣ الاستعادة (Recovery): إعادة التشغيل بأمان من نسخ احتياطية نظيفة.","6️⃣ الدروس والتحسين: توثيق النتائج وسد الثغرات لمنع التكرار مستقبلاً."]},{"type":"teacherTip","title":"💡 تنبيه امتحاني هام الامتحاني:","text":"انتبه لسؤال الترتيب: الاحتواء يأتي دائماً قبل الاستئصال والاستعادة؛ لأنه لو بدأنا بالاستعادة والبرمجية لا تزال نشطة، ستدمر النسخ الاحتياطية فوراً!"}]'::jsonb)
ON CONFLICT (id) DO UPDATE SET chunk_title = EXCLUDED.chunk_title, summary = EXCLUDED.summary, key_terms = EXCLUDED.key_terms, content_cards = EXCLUDED.content_cards;
INSERT INTO public.chunks (id, chapter_id, lesson_id, chunk_index, chunk_title, en_chunk_title, type, icon_emoji, xp_reward, stars_reward, summary, audio_narration_text, en_audio_narration_text, ai_tutor_prompt, simplified_explanation, key_terms, content_cards)
VALUES ('ch2-l3-c2', 2, '2-3', 2, 'إدارة وتقييم المخاطر السيبرانية ومصفوفة الأولويات', 'Cyber Risk Assessment & Prioritization Matrix', 'chunk', '📈', 35, 1, 'معادلة تقييم الخطر (درجة الخطر = التأثير × الاحتمالية)، مصفوفة تحديد الأولويات (3×3)، وسيناريو برمجية الفدية Ransomware وخطة التعافي.', 'الخطر السيبراني هو احتمال تسبب تهديد في إلحاق ضرر بالأصول الرقمية. ولكي تقرر المؤسسة أي التهديدات تعالج أولاً بمواردها المحدودة، تستخدم المعادلة المنهجية: درجة الخطر تساوي حجم التأثير مضروباً في احتمالية الحدوث! التأثير يقاس من 1 إلى 3 (منخفض، متوسط، مرتفع)، والاحتمالية من 1 إلى 3 (نادر، محتمل، شبه مؤكد). والتهديد ذو الناتج الأعلى (الأحمر الحرج) يأخذ الأولوية القصوى للمعالجة الفورية. ومن أخطر السيناريوهات هجوم برمجيات الفدية Ransomware؛ حيث لا يجب أبداً دفع الفدية للمجرمين، بل يتم فصل الأجهزة واستئصال الفيروس واستعادة البيانات من نسخ احتياطية منفصلة وآمنة.', 'Cyber Risk Management is the process of identifying, evaluating, and mitigating digital threats. Risk is mathematically assessed as a function of three variables: Threat (the potential malicious agent or event), Vulnerability (a security flaw or weakness in the system), and Impact (the financial or operational damage if breached). Organizations map risks onto a Risk Matrix evaluating Likelihood vs Impact, and select from four treatment strategies: Mitigation, Transfer, Avoidance, or Acceptance.', 'ممتاز يا بطل! لو عندك تهديد A درجته 6 وتهديد B درجته 3، بأيهما تبدأ معالجة؟ جاهز لتطبيق المعادلة؟', 'لو عندك سقف يسرب نقطة ماء خفيفة (تأثير ضعيف)، وأنبوبة غاز فيها شرخ خطير (تأثير كارثي واحتراق مؤكد)؛ تبدأ فوراً بإصلاح الغاز لأن ناتج خطره حرج جداً! هذا هو معنى التأثير × الاحتمالية!', '[{"term":"معادلة تقييم الخطر","en":"Risk Formula","definition":"معادلة كمية لتحديد مستوى الخطر: درجة الخطر (Risk Score) = حجم التأثير (Impact) × احتمالية الحدوث (Likelihood).","example":"تأثير مرتفع (3) × احتمالية متوسطة (2) = درجة خطر (6)، وهي أعلى أولوية من تأثير منخفض (1) × احتمالية مرتفعة (3) = (3).","examTip":"سؤال حسابي وزاري مكرر: احسب درجة الخطر وحدد الأولوية (كتاب ص 48)."},{"term":"برمجية الفدية","en":"Ransomware","definition":"نوع خطير من البرمجيات الخبيثة يشفر ملفات المستخدم أو المؤسسة ويطلب فدية مالية مقابل فك التشفير.","example":"تشفير سجلات مستشفى والمطالبة بعملات رقمية لفتحها.","examTip":"الحل النموذجي: عدم دفع الفدية، عزل الشبكة، واستعادة الملفات من النسخ الاحتياطية النظيفة."}]'::jsonb, '[{"type":"concept","title":"مصفوفة تقييم المخاطر وتحديد أولويات المعالجة (كتاب ص 48):","points":["🔴 نطاق الخطر الحرج (6 – 9): يتطلب إجراءات فورية وسريعة دون تأخير.","🟠 نطاق الخطر المتوسط (3 – 4): معالجة مخططة ومتابعة منتظمة.","🟢 نطاق الخطر المنخفض (1 – 2): مراقبة وقبول المخاطرة مع المتابعة الدورية."]}]'::jsonb)
ON CONFLICT (id) DO UPDATE SET chunk_title = EXCLUDED.chunk_title, summary = EXCLUDED.summary, key_terms = EXCLUDED.key_terms, content_cards = EXCLUDED.content_cards;
INSERT INTO public.chunks (id, chapter_id, lesson_id, chunk_index, chunk_title, en_chunk_title, type, icon_emoji, xp_reward, stars_reward, summary, audio_narration_text, en_audio_narration_text, ai_tutor_prompt, simplified_explanation, key_terms, content_cards)
VALUES ('ch2-l3-exam', 2, '2-3', 3, '🏆 التحدي الختامي: اختبار إتقان الدرس (2-3) الشامل', '🏆 Final Challenge: Lesson (2-3) Mastery Exam', 'lesson_exam', '⏳', 100, 3, 'اختبار امتحاني وزاري شامل مجمع يغطي الحادث الأمني، والمراحل الست للاستجابة، وحسابات تقييم المخاطر وسيناريوهات الفدية.', 'وصلت لاختبار إتقان الدرس الثالث وختام الفصل الثاني كاملاً! أجب عن الأسئلة الامتحانية بنجاح لتنال كأس التميز الذهبي للفصل الثاني!', 'Welcome to the Lesson 2-3 Mastery Challenge! Conclude Chapter 2 by demonstrating your mastery of incident response lifecycles and cybersecurity risk matrices!', '', '', '[]'::jsonb, '[]'::jsonb)
ON CONFLICT (id) DO UPDATE SET chunk_title = EXCLUDED.chunk_title, summary = EXCLUDED.summary, key_terms = EXCLUDED.key_terms, content_cards = EXCLUDED.content_cards;
INSERT INTO public.chunks (id, chapter_id, lesson_id, chunk_index, chunk_title, en_chunk_title, type, icon_emoji, xp_reward, stars_reward, summary, audio_narration_text, en_audio_narration_text, ai_tutor_prompt, simplified_explanation, key_terms, content_cards)
VALUES ('ch3-l1-c1', 3, '3-1', 1, 'بنية العميل والخادم والطبقات الثلاث (3-Tier Architecture)', 'Client-Server Architecture & The 3-Tier Model', 'chunk', '🏢', 35, 1, 'نموذج Client-Server، والطبقات الثلاث الأساسية لأي موقع ويب: طبقة العرض (Presentation)، طبقة منطق التطبيق (Logic Tier)، وطبقة البيانات (Data Tier).', 'أهلاً بك في الفصل الثالث: تطبيقات الويب! كيف تعمل المواقع الحديثة مثل فيسبوك أو أمازون؟ تعمل وفق بنية شهيرة تُدعى بنية الطبقات الثلاث: الطبقة الأولى هي طبقة العرض وتعمل في متصفح العميل بالـ HTML و CSS لعرض الواجهة والأزرار. والطبقة الثانية هي طبقة منطق العمل وتعمل على خادم الويب بمعالجة الأكواد والقرارات والحسابات. والطبقة الثالثة هي طبقة قاعدة البيانات لتخزين واسترجاع بيانات المستخدمين والمنتجات بأمان.', 'Welcome to Chapter 3 on Web Applications! Modern web platforms rely on the Client-Server model, organized through a 3-Tier Architecture: Tier 1 is the Presentation Tier, running in the user''s web browser using HTML, CSS, and JavaScript. Tier 2 is the Application/Logic Tier, running on backend servers using Python, Node.js, or PHP to process business rules. Tier 3 is the Data Tier, using relational or NoSQL database management systems for secure, persistent storage.', 'عاش يا بطل! استوعبت دور كل طبقة من الطبقات الثلاث لتطبيقات الويب؟ تحب نبدأ أسئلتها؟', 'تخيل أنك في مطعم: قائمة الطعام والطاولة الأنيقة هي طبقة العرض؛ النادل والمطبخ الذي يطبخ الطعام هو طبقة المنطق؛ ومخزن وثلاجة المكونات هو طبقة قاعدة البيانات!', '[{"term":"بنية الطبقات الثلاث","en":"3-Tier Architecture","definition":"معمارية برمجية تفصل نظام الويب إلى ثلاث طبقات مستقلة: طبقة واجهة المستخدم، طبقة المعالجة ومنطق الأعمال، وطبقة قاعدة البيانات.","example":"المتصفح (واجهة) ← خادم Node.js/Python (منطق) ← قاعدة بيانات MySQL (بيانات).","examTip":"سؤال متكرر: ما هي الطبقات الثلاث؟ Presentation Tier, Application/Logic Tier, Data Tier."},{"term":"نموذج العميل والخادم","en":"Client-Server Model","definition":"هيكل برمجي يقوم فيه العميل (المرسل) بطلب خدمة أو صفحة، ويقوم الخادم بمعالجة الطلب وإرجاع الاستجابة.","example":"متصفحك يطلب صفحة، وخادم الويب يرد بالملفات المطلوبة.","examTip":"أساس عمل بروتوكولات الإنترنت كـ HTTP."}]'::jsonb, '[{"type":"concept","title":"الطبقات الثلاث بالتفصيل:","points":["💻 1. طبقة العرض (Presentation Tier): المتصفح وأكواد HTML/CSS/JS والتفاعل البصري.","⚙️ 2. طبقة المنطق (Logic/Application Tier): الخادم ولغات الخادم (PHP/Python/Node) ومعالجة الحسابات.","🗄️ 3. طبقة البيانات (Data Tier): قواعد البيانات (SQL/NoSQL) للتخزين الدائم والآمن."]}]'::jsonb)
ON CONFLICT (id) DO UPDATE SET chunk_title = EXCLUDED.chunk_title, summary = EXCLUDED.summary, key_terms = EXCLUDED.key_terms, content_cards = EXCLUDED.content_cards;
INSERT INTO public.chunks (id, chapter_id, lesson_id, chunk_index, chunk_title, en_chunk_title, type, icon_emoji, xp_reward, stars_reward, summary, audio_narration_text, en_audio_narration_text, ai_tutor_prompt, simplified_explanation, key_terms, content_cards)
VALUES ('ch3-l1-c2', 3, '3-1', 2, 'تدفق تعاون الطبقات الثلاث والمواقع الثابتة والديناميكية', '3-Tier Collaboration Flow: Static vs Dynamic Websites', 'chunk', '🔄', 35, 1, 'الخطوات الست المرتبة لتعاون الطبقات عند طلب خدمة (مثل البحث عن منتج أو حجز قطار)، وماذا يحدث عند انقطاع قاعدة البيانات، وحدود الواجهة الأمامية.', 'كيف تتعاون الطبقات الثلاث فعلياً عندما تبحث عن منتج أو تحجز تذكرة قطار؟ تبدأ الرحلة في الواجهة الأمامية باستقبال كلمات البحث، ثم ترسل الأمامية طلباً عبر بروتوكول HTTP للخادم الخلفي، الخادم الخلفي بدوره يستعلم من قاعدة البيانات ويطلب السجلات المطابقة، فتعيد قاعدة البيانات البيانات المطلوبة للخادم الخلفي، وهنا يقوم الخادم الخلفي بمعالجة النتائج وتجهيز الرد، وأخيراً تعرض الواجهة الأمامية النتائج المنمقة للمستخدم! وإذا انقطعت قاعدة البيانات مؤقتاً، تظل الصفحة الأمامية ظاهرة، لكن يعجز الخادم عن مطابقة كلمات المرور أو جلب البيانات ويرسل رمز خطأ مثل 500 للمتصفح.', 'Web content is either Static or Dynamic: A Static website consists of pre-built HTML, CSS, and image files stored on a server; every visitor receives the exact same identical page. A Dynamic website, however, generates personalized content on the fly: when a user submits an action, the Presentation tier dispatches a request to the Logic tier, which queries the Data tier, constructs an individualized HTML response, and sends it back to the client.', 'عاش يا بطل! رتبت خطوات تدفق البيانات وعرفت لماذا لا يمكن للأمامية حفظ البيانات الدائمة بمفردها؟ جاهز للأسئلة؟', 'لو طلبت وجبة في مطعم: أنت تعطي الطلب للنادل (أمامية)، النادل يذهب للمطبخ (خلفية)، الطباخ يأخذ اللحم من الثلاجة (قاعدة بيانات)، ثم يطبخ الوجبة (خلفية)، والنادل يقدمها لك ساخنة على الطاولة (أمامية)!', '[{"term":"تدفق تعاون الطبقات","en":"Three-Tier Data Flow","definition":"التسلسل المنظم للبيانات: المستخدم ← الواجهة الأمامية (مدخلات) ← الواجهة الخلفية (معالجة) ← قاعدة البيانات (استرجاع) ← الواجهة الخلفية (تجهيز) ← الواجهة الأمامية (عرض).","example":"حجز مقعد قطار: اختيار المقعد في الأمامية، فحص توفره في الخلفية، تسجيله في قاعدة البيانات، وإرسال رمز QR للمستخدم.","examTip":"سؤال ترتيب وزاري: احفظ الخطوات الست لتدفق تعاون الطبقات (كتاب ص 52)."},{"term":"حدود الواجهة الأمامية","en":"Front-end Limitations","definition":"المهام التي تعجز الواجهة الأمامية عن القيام بها بمفردها مثل حفظ البيانات الدائمة أو معالجة المدفوعات البنكية لعدم امتلاكها صلاحيات سرية أو تخزين مشترك.","example":"تخزين سجلات الطلاب الدائمة أو معالجة الأرصدة البنكية يحتاج حصراً لخادم وقاعدة بيانات.","examTip":"سؤال وزاري مباشر: حدد مهمة لا يمكن للواجهة الأمامية القيام بها وحدها ولماذا (كتاب ص 55)."}]'::jsonb, '[{"type":"concept","title":"خطوات تدفق البيانات الست عند البحث عن منتج (كتاب ص 52):","points":["1️⃣ إدخال البيانات: استقبال كلمات البحث من المستخدم في الواجهة الأمامية.","2️⃣ إرسال الطلب: نقل كلمات البحث للخادم الخلفي عبر HTTP.","3️⃣ استعلام البيانات: طلب الخادم من قاعدة البيانات السجلات المطابقة.","4️⃣ إرجاع النتائج: إرسال قاعدة البيانات للسجلات المطلوبة للخلفية.","5️⃣ تجهيز الرد: معالجة النتائج وصياغتها كاستجابة جاهزة.","6️⃣ العرض للمستخدم: عرض النتائج المنسقة على الشاشة بالواجهة الأمامية."]}]'::jsonb)
