INSERT INTO public.chunks (id, chapter_id, lesson_id, chunk_index, chunk_title, en_chunk_title, type, icon_emoji, xp_reward, stars_reward, summary, audio_narration_text, en_audio_narration_text, ai_tutor_prompt, simplified_explanation, key_terms, content_cards)
VALUES ('ch3-l1-exam', 3, '3-1', 2, '🏆 التحدي الختامي: اختبار إتقان الدرس (3-1) الشامل', '🏆 Final Challenge: Lesson (3-1) Mastery Exam', 'lesson_exam', '⏳', 100, 3, 'اختبار امتحاني شامل يغطي نموذج العميل والخادم، وبنية الطبقات الثلاث، والمقارنة بين المواقع الثابتة والديناميكية.', 'وصلت لاختبار إتقان الدرس الأول من الفصل الثالث! أجب عن الأسئلة الامتحانية بنجاح لتنال كأس التميز وتفتح الدرس التالي!', 'Welcome to the Lesson 3-1 Mastery Exam! Demonstrate your thorough command of multi-tier web architecture and server-side processing to earn your gold trophy!', '', '', '[]'::jsonb, '[]'::jsonb)
ON CONFLICT (id) DO UPDATE SET chunk_title = EXCLUDED.chunk_title, summary = EXCLUDED.summary, key_terms = EXCLUDED.key_terms, content_cards = EXCLUDED.content_cards;
INSERT INTO public.chunks (id, chapter_id, lesson_id, chunk_index, chunk_title, en_chunk_title, type, icon_emoji, xp_reward, stars_reward, summary, audio_narration_text, en_audio_narration_text, ai_tutor_prompt, simplified_explanation, key_terms, content_cards)
VALUES ('ch3-l2-c1', 3, '3-2', 1, 'نموذج العميل/الخادم وبروتوكول HTTP مقابل HTTPS وطرق الطلب', 'HTTP vs HTTPS Protocols & Request Methods', 'chunk', '📡', 35, 1, 'تبادل الطلبات والاستجابات بين العميل والخادم، الفارق بين HTTP الصريح و HTTPS المشفر بنفق TLS، وطرق الطلب المنهجية (GET لجلب البيانات، POST لإرسال ومعالجة البيانات).', 'مرحباً بك في الدرس الثاني من الفصل الثالث في هذه المحطة التعليمية! كيف تتواصل متصفحات الإنترنت مع الخوادم السحابية؟ عبر نموذج العميل والخادم وبروتوكول HTTP. يرسل العميل طلباً Request بطرق محددة: طريقة GET لجلب وقراءة البيانات دون تعديلها مثل فتح صفحة إخبارية وتظهر في رابط الصفحة URL، أما طريقة POST فتُستخدم لإرسال ومعالجة بيانات حساسة مثل تسجيل الدخول أو إدخال كلمة المرور وتكون مخفية داخل جسم الطلب. والأهم هو استخدام بروتوكول HTTPS المشفر بنفق TLS بدلاً من HTTP العادي؛ لأن HTTP ينقل النصوص صريحة ومكشوفة لأي متجسس على الشبكة، بينما HTTPS يحمي سرية البيانات ومصادقة الموقع بالكامل!', 'Communication between web browsers and servers is governed by the HyperText Transfer Protocol (HTTP). Standard HTTP transmits data in unencrypted plaintext, leaving sensitive information vulnerable to eavesdropping. HTTPS solves this by adding an encryption layer via SSL/TLS. When communicating with web servers, clients use HTTP Request Methods: GET retrieves data from the server, while POST securely sends new data (such as login credentials or payment forms) to be processed.', 'عاش يا بطل! عرفت متى نستخدم GET ومتى نستخدم POST ولماذا HTTPS ضروري في تسجيل الدخول؟', 'الـ GET مثل بطاقة بريدية مكشوفة يقرأ ساعي البريد ما عليها لجلب الكتاب المناسب لك. والـ POST مثل ظرف مغلق ومختوم لا يرى أحد محتواه لإرسال أوراقك الهامة بأمان!', '[{"term":"نموذج العميل والخادم","en":"Client-Server Model","definition":"بنية اتصالية يقوم فيها العميل (كالطالب أو المتصفح) بطلب خدمة أو صفحة، ويقوم الخادم باستقبال الطلب ومعالجته وإرجاع الاستجابة المناسبة.","example":"متصفحك يطلب صفحة جوجل، وخادم جوجل يعيد ملف HTML.","examTip":"سؤال متكرر: العميل هو الطرف الطالب للخدمة، والخادم هو الطرف المستجيب (كتاب ص 57)."},{"term":"بروتوكول HTTPS","en":"HTTPS","definition":"بروتوكول نقل النص الفائق الآمن؛ وهو استخدام HTTP عبر نفق تشفير TLS يحمي سرية البيانات ويضمن مصادقة الخادم لمنع التنصت والتزوير.","example":"رمز القفل في شريط عنوان المتصفح عند الشراء بالبطاقة الائتمانية.","examTip":"سؤال تعليل وزاري: لماذا تستخدم صفحات تسجيل الدخول HTTPS؟ لمنع قراءة كلمات المرور كنص صريح (ص 58)."},{"term":"طريقة GET مقابل POST","en":"GET vs POST Methods","definition":"أساليب طلب HTTP: GET لجلب الموارد وقراءتها فقط، و POST لإرسال بيانات جديدة لمعالجتها أو حفظها في قاعدة البيانات.","example":"تصفح المنتجات = GET | إرسال استمارة التسجيل أو كلمة المرور = POST.","examTip":"سؤال تطبيقي وزاري: تسجيل الدخول يستخدم POST، وعرض جدول الحصص يستخدم GET (ص 58)."}]'::jsonb, '[{"type":"concept","title":"مقارنة أساليب طلب HTTP (كتاب ص 58):","points":["🔍 GET: لجلب وقراءة الموارد فقط، تظهر بياناتها في الرابط URL، وتُستخدم لتصفح الصفحات وقوائم الأسعار.","✉️ POST: لإرسال بيانات جديدة لحفظها أو معالجتها، تكون مشفرة ومحمية في جسم الطلب، وتُستخدم لتسجيل الدخول والدفع.","✏️ PUT / DELETE: لتحديث بيانات موجودة (PUT) أو إزالة مورد (DELETE) في واجهات برمجة التطبيقات."]}]'::jsonb)
ON CONFLICT (id) DO UPDATE SET chunk_title = EXCLUDED.chunk_title, summary = EXCLUDED.summary, key_terms = EXCLUDED.key_terms, content_cards = EXCLUDED.content_cards;
INSERT INTO public.chunks (id, chapter_id, lesson_id, chunk_index, chunk_title, en_chunk_title, type, icon_emoji, xp_reward, stars_reward, summary, audio_narration_text, en_audio_narration_text, ai_tutor_prompt, simplified_explanation, key_terms, content_cards)
VALUES ('ch3-l2-c2', 3, '3-2', 2, 'رموز حالة HTTP وواجهات برمجة التطبيقات API وصيغة JSON', 'HTTP Status Codes, REST APIs & The JSON Format', 'chunk', '📄', 35, 1, 'دلالات رموز الحالة (200 OK للنجاح، 400 خطأ صياغة، 404 المورد غير موجود كخطأ عميل، 500 خطأ خادم)، ودور واجهات API وصيغة JSON الخفيفة.', 'عندما ينتهي الخادم من معالجة الطلب، يعيد رمز حالة HTTP لإخبار المتصفح بالنتيجة: الرمز الشهير 200 يعني نجاح العملية بالكامل وإعادة البيانات. والرمز 400 يعني خطأ في صياغة الطلب من جانب العميل. أما الرمز الشهير 404 فيعني أن الصفحة أو المورد غير موجود على الخادم، وهو خطأ من جانب العميل لأنه طلب رابطاً غير صحيح! بينما الرمز 500 يعني حدوث عطل داخلي بالخادم أثناء المعالجة. ولتبادل البيانات بين تطبيقات الموبايل والمواقع المختلفة، نستخدم واجهات برمجة التطبيقات API مع صيغة البيانات النصية الخفيفة JSON التي توفر طريقة قياسية وسريعة لتبادل المعلومات.', 'When a web server responds to an HTTP request, it issues an HTTP Status Code: 200 OK signals successful retrieval. 404 Not Found indicates the requested URL does not exist. And 500 Internal Server Error reveals a crash in backend server code. Modern web applications exchange data between frontend and backend via REST APIs using JSON (JavaScript Object Notation)—a lightweight, human-readable key-value text format.', 'عاش يا بطل! لو ظهر لك 404 على الشاشة، تعرف الخطأ عند من وماذا يعني؟ جاهز للأسئلة؟', 'رمز 200 يعني ''طلبك وصل وجاهز!''، رمز 404 يعني ''أنت طلبت غرفة رقم 999 وهي غير موجودة في الفندق أصلاً!''، ورمز 500 يعني ''المطبخ تعطل وسنصلحه قريباً!''', '[{"term":"رموز حالة HTTP","en":"HTTP Status Codes","definition":"أرقام ثلاثية معيارية تُرسل مع استجابة الخادم للإبلاغ عن نتيجة معالجة الطلب (200 نجاح، 404 غير موجود، 500 خطأ خادم).","example":"200 OK = نجاح | 404 Not Found = الصفحة غير موجودة (خطأ عميل) | 500 = عطل بالخادم.","examTip":"سؤال لغز وزاري: إذا استقبل المتصفح رمز 404، فأي جانب وقع فيه الخطأ؟ جانب العميل (كتاب ص 58)."},{"term":"واجهة برمجة التطبيقات","en":"API","definition":"واجهة برمجية وقواعد محددة تتيح لأنظمة وتطبيقات مختلفة تبادل البيانات والوظائف بسلاسة وأمان.","example":"تطبيق حجز الطيران يطلب مواعيد الرحلات من خوادم شركات الطيران المختلفة عبر API.","examTip":"سؤال اختر: واجهة تتيح لبرنامج طلب بيانات ووظائف من برنامج آخر هي API (ص 59)."},{"term":"صيغة JSON","en":"JSON","definition":"صيغة بيانات نصية قياسية خفيفة وسريعة تعتمد على أزواج المفتاح والقيمة (Key-Value) لتبادل البيانات بين الخوادم والتطبيقات.","example":"{\"name\": \"عمر\", \"grade\": 98}","examTip":"سؤال طابق: صيغة بيانات نصية خفيفة لتبادل البيانات بين النظم هي JSON (ص 59)."}]'::jsonb, '[{"type":"concept","title":"جدول رموز حالة HTTP المنهجية (كتاب ص 58–59):","points":["🟢 200 OK: تمت معالجة الطلب بنجاح والنتيجة متاحة.","🟡 400 Bad Request: خطأ في صياغة أو معاملات الطلب من جانب العميل.","🟠 404 Not Found: الصفحة أو المورد المطلوب غير موجود (خطأ عميل).","🔴 500 Server Error: حدث عطل أو خطأ داخلي في الخادم أثناء المعالجة."]}]'::jsonb)
ON CONFLICT (id) DO UPDATE SET chunk_title = EXCLUDED.chunk_title, summary = EXCLUDED.summary, key_terms = EXCLUDED.key_terms, content_cards = EXCLUDED.content_cards;
INSERT INTO public.chunks (id, chapter_id, lesson_id, chunk_index, chunk_title, en_chunk_title, type, icon_emoji, xp_reward, stars_reward, summary, audio_narration_text, en_audio_narration_text, ai_tutor_prompt, simplified_explanation, key_terms, content_cards)
VALUES ('ch3-l2-exam', 3, '3-2', 3, '🏆 التحدي الختامي: اختبار إتقان الدرس (3-2) الشامل', '🏆 Final Challenge: Lesson (3-2) Mastery Exam', 'lesson_exam', '⏳', 100, 3, 'اختبار امتحاني وزاري شامل مجمع يغطي نموذج العميل والخادم، وطرق طلب GET و POST، ورموز HTTP، وصيغة JSON وواجهات API.', 'وصلت لاختبار إتقان الدرس الثاني من الفصل الثالث! أجب عن الأسئلة الامتحانية بنجاح لتنال كأس التميز وتفتح الدرس الثالث!', 'Welcome to the Lesson 3-2 Mastery Challenge! Test your thorough knowledge of web protocols, HTTPS encryption, status codes, and API data payloads to claim your gold trophy!', '', '', '[]'::jsonb, '[]'::jsonb)
ON CONFLICT (id) DO UPDATE SET chunk_title = EXCLUDED.chunk_title, summary = EXCLUDED.summary, key_terms = EXCLUDED.key_terms, content_cards = EXCLUDED.content_cards;
INSERT INTO public.chunks (id, chapter_id, lesson_id, chunk_index, chunk_title, en_chunk_title, type, icon_emoji, xp_reward, stars_reward, summary, audio_narration_text, en_audio_narration_text, ai_tutor_prompt, simplified_explanation, key_terms, content_cards)
VALUES ('ch3-l3-c1', 3, '3-3', 1, 'ثلاثية تطوير الواجهة الأمامية: HTML و CSS و JavaScript', 'The Front-End Triad: HTML, CSS & JavaScript Roles', 'chunk', '💻', 35, 1, 'التشبيه المنهجي لهيكل المبنى: لغة HTML لبناء الهيكل والعناصر، ولغة CSS للتنسيق والمظهر، ولغة JavaScript للسلوك التفاعلي.', 'مرحباً بك في الدرس الثالث من الفصل الثالث في هذه المحطة التعليمية! واجهات الويب التي تراها كل يوم مبنية على ثلاثية تقنية لا غنى عنها؛ يشبهها كتاب الوزارة ببناء مبنى معماري متكامل: لغة HTML تمثل الهيكل الخرساني والجدران الأساسية؛ حيث تبني العناوين والفقرات والأزرار والجداول واستمارات التسجيل. ولغة CSS تمثل التصميم والديكور والألوان؛ حيث تحدد المظهر والخطوط وتناسق التخطيط. ولغة JavaScript تمثل الكهرباء والمصاعد؛ حيث توفر السلوك التفاعلي واستجابة الأزرار والتحقق الفوري من صحة المدخلات. وعند بناء استمارة تسجيل متجاوبة، تتعاون التقنيات الثلاث: HTML تنشئ الحقول، CSS تمنحها التنسيق المتجاوب، و JS تفحص صحة البيانات فورياً!', 'Every visual web page in the world is constructed using three core front-end languages: HTML (HyperText Markup Language) builds the structural skeleton using semantic tags like headings, paragraphs, and forms. CSS (Cascading Style Sheets) decorates the appearance, controlling color palettes, fonts, grid layouts, and animations. And JavaScript acts as the nervous system, adding dynamic interactivity, handling button clicks, validating forms, and fetching API data asynchronously without refreshing the page.', 'عاش يا بطل! استوعبت دور كل لغة من الثلاثية: HTML للهيكل، CSS للمظهر، و JS للتفاعل؟ جاهز للتحدي؟', 'HTML هي عظام جسم الإنسان، CSS هي الملابس الأنيقة والملامح، و JavaScript هي العضلات والأعصاب التي تمكنه من الحركة والكلام والتفاعل!', '[{"term":"لغة HTML","en":"HTML","definition":"لغة ترميز النص الفائق المسؤولة عن بناء الهيكل العظمي لصفحة الويب وإدراج العناصر الأساسية كالعناوين والنصوص والصور والروابط.","example":"<h1>عنوان رئيسي</h1> و <p>فقرة</p> و <button>زر</button>.","examTip":"سؤال الفراغات: تتولى HTML بناء الهيكل (كتاب ص 67)."},{"term":"لغة CSS","en":"CSS","definition":"لغة أوراق الأنماط المتتالية المسؤولة عن تنسيق المظهر البصري والجماليات: الألوان، الخطوط، وتخطيط الصفحة المتجاوب.","example":"تلوين الأزرار وتحديد المسافات وترتيب العناصر في شبكة أنيقة.","examTip":"سؤال صواب وخطأ: تتولى CSS تحديد مظهر الصفحة وتخطيطها وألوانها (صواب ص 66)."},{"term":"لغة JavaScript","en":"JavaScript","definition":"لغة البرمجة التفاعلية المسؤولة عن إضافة الحركة والسلوك الديناميكي والاستجابة لضغطات المستخدم وفحص المدخلات.","example":"إظهار رسالة تحذيرية فورية عند كتابة بريد إلكتروني غير صحيح دون إعادة تحميل الصفحة.","examTip":"توفر السلوك التفاعلي وتعديل محتوى الصفحة لحظياً (ص 67)."}]'::jsonb, '[{"type":"concept","title":"ثلاثية تطوير الواجهة الأمامية (تشبيه هيكل المبنى ص 63):","points":["🏛️ 1. لغة HTML: ''الهيكل الخرساني'' - إنشاء البنية والعناصر وحقول الاستمارة.","🎨 2. لغة CSS: ''التصميم والطلاء'' - تحديد المظهر والألوان والتخطيط الجذاب.","⚡ 3. لغة JavaScript: ''الكهرباء والتفاعل'' - السلوك الحركي وفحص صحة البيانات."]}]'::jsonb)
ON CONFLICT (id) DO UPDATE SET chunk_title = EXCLUDED.chunk_title, summary = EXCLUDED.summary, key_terms = EXCLUDED.key_terms, content_cards = EXCLUDED.content_cards;
INSERT INTO public.chunks (id, chapter_id, lesson_id, chunk_index, chunk_title, en_chunk_title, type, icon_emoji, xp_reward, stars_reward, summary, audio_narration_text, en_audio_narration_text, ai_tutor_prompt, simplified_explanation, key_terms, content_cards)
VALUES ('ch3-l3-c2', 3, '3-3', 2, 'HTML الدلالية، التصميم المتجاوب، وأطر العمل الحديثة', 'Semantic HTML, Responsive Design & Modern Web Frameworks', 'chunk', '📱', 35, 1, 'الوسوم الدلالية (header, nav, main, footer) لإمكانية الوصول والـ SEO، ومبادئ التصميم المتجاوب (Responsive) لتكييف الشاشات، وأطر العمل الحديثة (React, Next.js).', 'في تطوير الويب الاحترافي، نستخدم وسوماً دلالية Semantic HTML مثل header للترويسة، و nav لروابط التنقل، و main للمحتوى الجوهري، و footer للتذييل؛ بدلاً من استخدام صناديق div المبهمة. لماذا؟ لأنها تساعد قارئات الشاشة للمكفوفين على فهم محتوى الصفحة بكفاءة (إمكانية الوصول Accessibility)، وتساعد محركات البحث Google على فهرسة الأقسام بدقة. كما نطبق التصميم المتجاوب Responsive Web Design لجعل تخطيط الموقع يتكيف تلقائياً مع أحجام الشاشات المختلفة؛ فتعرض شاشة الكمبيوتر 4 أعمدة للمنتجات وتتحول تلقائياً لعمود واحد مريح على شاشة الهاتف. ولتطوير المواقع بكفاءة عالية، نستخدم أطر العمل مثل React لبناء المكونات، و Next.js لتوفير العرض من جهة الخادم.', 'Professional web development emphasizes Semantic HTML: using descriptive tags like <header>, <nav>, <article>, and <footer> instead of generic <div> tags, which dramatically enhances accessibility (for screen readers) and Search Engine Optimization (SEO). Furthermore, Responsive Web Design uses CSS Media Queries and fluid layouts (Flexbox/Grid) to ensure pages adapt seamlessly whether viewed on a 4-inch smartphone or a 32-inch 4K monitor.', 'ممتاز يا بطل! عرفت لماذا نحرص على HTML الدلالية والتصميم المتجاوب على الهواتف؟ جاهز للتحدي؟', 'HTML الدلالية مثل وضع لوحات إرشادية على الأبواب: ''باب خروج'' و''صالة طعام''، فيعرف الضيف الأعمى مكانه فوراً. والتصميم المتجاوب مثل الماء يأخذ شكل الإناء: يتسع على الكمبيوتر وينكمش على الهاتف بأناقة!', '[{"term":"HTML الدلالية","en":"Semantic HTML","definition":"استخدام وسوم تصف معنى ودور العنصر بوضوح (مثل <header> و <nav> و <main> و <footer>) بدلاً من الصناديق العامة غير ذات الدلالة.","example":"قارئ الشاشة يخبر الكفيف: ''قائمة تنقل'' عند قراءة وسوم <nav> فيستطيع تخطيها للمحتوى الأساسي.","examTip":"سؤال وزاري: العناصر الدلالية تصف معنى المحتوى صراحة لقارئات الشاشة ومحركات البحث (ص 64)."},{"term":"التصميم المتجاوب","en":"Responsive Web Design","definition":"تصميم موقع الويب وتخطيطه بحيث يتكيف تلقائياً مع أحجام الشاشات المختلفة (حواسيب، أجهزة لوحية، هواتف ذكية) لتفادي التمرير الأفقي وتشوه النصوص.","example":"تحول القائمة الأفقية العريضة في الحاسوب إلى قائمة هامبرغر منسدلة أنيقة في الهاتف.","examTip":"سؤال اختر: الغرض الرئيسي للتصميم المتجاوب تكييف التخطيط تلقائياً مع أحجام الشاشات (ص 64)."},{"term":"إمكانية الوصول للويب","en":"Web Accessibility","definition":"تصميم وتطوير المواقع بحيث يتمكن جميع الأشخاص، بما في ذلك ذوو الإعاقة وكبار السن، من فهم وتصفح والتفاعل مع الموقع بكفاءة متساوية.","example":"دعم قارئات الشاشة، والتباين العالي للألوان لضعاف البصر.","examTip":"سؤال وزاري مباشر: ما المقصود بإمكانية الوصول للويب؟ (كتاب ص 64)."}]'::jsonb, '[{"type":"concept","title":"الوسوم الدلالية المنهجية ووظائفها (كتاب ص 64):","points":["🔝 <header>: ترويسة أعلى الصفحة أو المقال وتضم الشعار والعنوان.","🧭 <nav>: قسم مخصص لروابط وقوائم التنقل الرئيسية.","📄 <main>: المحتوى الجوهري والأساسي لصفحة الويب دون تكرار.","🔚 <footer>: تذييل الصفحة ومعلومات الاتصال وحقوق الملكية."]},{"type":"concept","title":"أطر العمل والمكتبات الحديثة (كتاب ص 65):","points":["⚛️ React: مكتبة لبناء واجهات المستخدم من مكونات برمجية قابلة لإعادة الاستخدام.","🚀 Next.js: إطار متكامل مبني على React يوفر التوجيه المباشر والعرض من جانب الخادم."]}]'::jsonb)
ON CONFLICT (id) DO UPDATE SET chunk_title = EXCLUDED.chunk_title, summary = EXCLUDED.summary, key_terms = EXCLUDED.key_terms, content_cards = EXCLUDED.content_cards;
INSERT INTO public.chunks (id, chapter_id, lesson_id, chunk_index, chunk_title, en_chunk_title, type, icon_emoji, xp_reward, stars_reward, summary, audio_narration_text, en_audio_narration_text, ai_tutor_prompt, simplified_explanation, key_terms, content_cards)
VALUES ('ch3-l3-exam', 3, '3-3', 3, '🏆 التحدي الختامي: اختبار إتقان الدرس (3-3) الشامل', '🏆 Final Challenge: Lesson (3-3) Mastery Exam', 'lesson_exam', '⏳', 100, 3, 'اختبار امتحاني وزاري شامل مجمع يغطي ثلاثية الواجهة (HTML, CSS, JS)، والوسوم الدلالية، والتصميم المتجاوب وإمكانية الوصول وأطر العمل.', 'وصلت لاختبار إتقان الدرس الثالث وختام الفصل الثالث كاملاً! أجب عن الأسئلة الامتحانية بنجاح لتنال كأس التميز الذهبي للفصل الثالث!', 'Welcome to the Lesson 3-3 Mastery Challenge! Conclude Chapter 3 by demonstrating your mastery of HTML structure, CSS styling, and JavaScript interactivity to claim your gold trophy!', '', '', '[]'::jsonb, '[]'::jsonb)
ON CONFLICT (id) DO UPDATE SET chunk_title = EXCLUDED.chunk_title, summary = EXCLUDED.summary, key_terms = EXCLUDED.key_terms, content_cards = EXCLUDED.content_cards;
INSERT INTO public.chunks (id, chapter_id, lesson_id, chunk_index, chunk_title, en_chunk_title, type, icon_emoji, xp_reward, stars_reward, summary, audio_narration_text, en_audio_narration_text, ai_tutor_prompt, simplified_explanation, key_terms, content_cards)
VALUES ('ch4-l1-c1', 4, '4-1', 1, 'مقارنة خصائص الوسائط وأنماط الاتصال أحادي وثنائي الاتجاه', 'Media Characteristics: One-Way vs Two-Way Communication', 'chunk', '📺', 35, 1, 'مقارنة الوسائط الإعلامية والرقمية (نصوص، صور، صوت، فيديو)، وأنماط الاتصال: اتجاه واحد (One-way) والتفاعلي ثنائي الاتجاه (Two-way).', 'مرحباً بك في الفصل الرابع: تصميم الويب والوسائط! في هذا الدرس نتعلم كيف نختار الوسيلة الإعلامية المناسبة لنشر أي فكرة: قديماً كانت وسائل الإعلام كالتلفزيون والراديو والجريدة تعمل في اتجاه واحد من المرسل للمستقبل دون تفاعل فوري. أما في عصر الويب والشبكات، أصبح الاتصال ثنائي الاتجاه وتفاعلياً؛ حيث يستطيع المستخدم التعليق، والمشاركة، وإبداء الرأي فورياً. كما نقارن بين نقاط قوة النص والصورة والفيديو لاختيار الأنسب لجمهورنا.', 'Welcome to Chapter 4 on Web Design and Media! Digital communication uses distinct media types: Text is lightweight and precise for official documentation. Images convey immediate emotional impact. Audio conveys tone without visual distraction. And Video is the richest and most engaging medium, combining imagery, motion, and sound. Unlike traditional One-Way broadcast media (like TV and print newspapers), modern web platforms deliver interactive Two-Way communication where visitors provide real-time feedback.', 'عاش يا بطل! عرفت الفارق بين الاتصال أحادي الاتجاه وثنائي الاتجاه، ومتى تفضل الفيديو على النص؟', 'لو أستاذ يشرح من وراء شاشة تلفزيون مغلقة ولا يسمعك، فهذا اتجاه واحد. لو يتحدث معك وترفع يدك وتناقشه وتجيب، فهذا ثنائي الاتجاه تفاعلي!', '[{"term":"الاتصال أحادي الاتجاه","en":"One-way Communication","definition":"نمط اتصالي ينقل فيه المصدر المعلومات إلى الجمهور في اتجاه واحد فقط دون تفاعل فوري أو رد مباشر من المتلقي.","example":"البث التلفزيوني التقليدي، الراديو، والمجلات المطبوعة.","examTip":"سؤال متكرر: ما الفرق بين التلفزيون ومواقع الويب؟ التلفزيون أحادي الاتجاه غالباً، والموقع تفاعلي ثنائي الاتجاه."},{"term":"الاتصال ثنائي الاتجاه","en":"Two-way Communication","definition":"نمط اتصالي تفاعلي يتبادل فيه المرسل والمستقبل الرسائل والتغذية الراجعة فورياً.","example":"مواقع التواصل الاجتماعي، محادثات الفيديو، والمنتديات التفاعلية.","examTip":"هو النمط الحاكم لشبكة الويب الحديثة وتطبيقات الجيل الثاني والثالث."}]'::jsonb, '[{"type":"concept","title":"مقارنة خصائص الوسائط الرقمية:","points":["📄 النص: دقيق، موثق، قليل الحجم، ومثالي للمعلومات الرسمية والتعليمات.","🖼️ الصورة: سريعة التأثير والفهم البصري (الصورة بألف كلمة)، تجذب الانتباه فوراً.","🎙️ الصوت: مناسب أثناء القيادة والعمل، ينقل المشاعر ونبرة الصوت دون تشتيت النظر.","🎬 الفيديو: الوسيط الأكثر ثراءً وجذباً وتأثيراً لأنه يجمع (الصورة + الحركة + الصوت)."]}]'::jsonb)
ON CONFLICT (id) DO UPDATE SET chunk_title = EXCLUDED.chunk_title, summary = EXCLUDED.summary, key_terms = EXCLUDED.key_terms, content_cards = EXCLUDED.content_cards;
INSERT INTO public.chunks (id, chapter_id, lesson_id, chunk_index, chunk_title, en_chunk_title, type, icon_emoji, xp_reward, stars_reward, summary, audio_narration_text, en_audio_narration_text, ai_tutor_prompt, simplified_explanation, key_terms, content_cards)
VALUES ('ch4-l1-c2', 4, '4-1', 2, 'الرسوم المتجهة (Vector) مقابل النقطية (Bitmap) وتقنيات ضغط البيانات', 'Vector vs Bitmap Graphics & Data Compression Techniques', 'chunk', '📐', 35, 1, 'الصور المتجهة (SVG) القائمة على المعادلات الرياضية التي لا تبكسل عند التكبير مقابل الصور النقطية (JPG/PNG)، وضغط البيانات مع فقدان (Lossy) وبدون فقدان (Lossless).', 'في هذا المحور من الدرس الأول بالفصل الرابع، نتعلم كيف نتعامل مع الصور في صفحات الويب باحترافية: لدينا نوعان رئيسيان من الصور؛ النوع الأول هو الصور المتجهة Vector مثل صيغة SVG، وهي مبنية على معادلات رياضية هندسية، وميزتها الخارقة أنها لا تفقد جودتها ولا تبكسل أبداً مهما قمت بتكبيرها، لذلك فهي مثالية للشعارات والأيقونات والخطوط. أما النوع الثاني فهو الصور النقطية Bitmap مثل JPG و PNG، وهي مصفوفة من البكسلات الملونة، تفقد حدتها وتبكسل عند التكبير المفرط، لكنها مثالية للصور الفوتوغرافية والطبيعية. ولكي نحمل الصور بسرعة عبر الإنترنت، نستخدم تقنيات ضغط البيانات: الضغط بدون فقدان Lossless مثل PNG يحتفظ بكل البيانات ويستخدم للرسوم ذات الشفافية، بينما الضغط مع الفقدان Lossy مثل JPEG يزيل التفاصيل غير المحسوسة لتقليص حجم الملف وتسريع الموقع!', 'Web graphics fall into two fundamental categories: Bitmap (Raster) images, composed of a fixed grid of colored pixels—such as JPEG for photographs and PNG for transparent graphics. Scaling bitmaps causes pixelation. In contrast, Vector graphics (like SVG) use mathematical equations (points, curves, and vectors) to draw shapes, allowing infinite scaling without ever losing sharpness. To accelerate web page loading, developers use Lossless compression (like PNG/ZIP) to preserve every byte, or Lossy compression (like JPEG/MP3) to discard imperceptible data for massive file size reductions.', 'عاش يا بطل! متى تختار صورة Vector بصيغة SVG ومتى تختار صورة JPEG مضغوطة؟ جاهز للأسئلة؟', 'الـ Vector مثل أمر كمبيوتر يرسم دائرة بفرجار: مهما كبرت الدائرة تظل ناعمة وملساء تماماً. والـ Bitmap مثل لوحة مرسومة بنقط ملونة: لو قربت منها بعدسة مكبرة سترى المربعات والبكسلات بوضوح!', '[{"term":"الصور المتجهة","en":"Vector Graphics (SVG)","definition":"صور تُنشأ باستخدام معادلات رياضية للأشكال والخطوط والمنحنيات؛ لا تفقد دقتها أو تبكسل عند تكبيرها، ومثالية للشعارات والأيقونات.","example":"شعار الموقع بصيغة SVG يظهر حاداً وواضحاً على كل الشاشات.","examTip":"سؤال وزاري مكرر: أي نوع صور لا يبكسل عند التكبير؟ الصور المتجهة Vector (كتاب ص 70)."},{"term":"الصور النقطية","en":"Bitmap / Raster (JPG/PNG)","definition":"صور تتكون من شبكة من النقاط الملونة (Pixels)؛ تفقد حدتها وتبكسل عند التكبير المفرط، ومثالية للصور الفوتوغرافية الغنية بالألوان.","example":"الصور الملتقطة بكاميرا الهاتف المحمول.","examTip":"تفقد حدتها وتبكسل إذا تم تكبيرها أكبر من حجمها الأصلي (ص 70)."},{"term":"ضغط البيانات","en":"Data Compression (Lossless vs Lossy)","definition":"تقنيات تقليص حجم الملفات؛ غير المفقود (Lossless) يستعيد البيانات 100% دون نقص، ومع الفقدان (Lossy) يحذف تفاصيل غير محسوسة لتسريع الويب.","example":"صيغة PNG تستخدم Lossless | صيغة JPEG تستخدم Lossy لتقليل الحجم.","examTip":"سؤال وزاري: صيغة JPEG تستخدم ضغطاً مع الفقدان Lossy لتقليل حجم صور الويب (ص 70)."}]'::jsonb, '[{"type":"concept","title":"مقارنة المتجهة والنقطية وتقنيات الضغط (كتاب ص 70):","points":["📐 الصور المتجهة (Vector/SVG): معادلات رياضية، دقة لانهائية، لا تبكسل، مثالية للشعارات.","🖼️ الصور النقطية (Bitmap/JPG): شبكة بكسلات، تبكسل عند التكبير، مثالية للصور الحقيقية.","📦 الضغط بدون فقدان (Lossless/PNG): استعادة كاملة 100% ودعم الشفافية للرسوم.","⚡ الضغط مع الفقدان (Lossy/JPEG): تقليص هائل للحجم لتسريع تحميل المواقع."]}]'::jsonb)
ON CONFLICT (id) DO UPDATE SET chunk_title = EXCLUDED.chunk_title, summary = EXCLUDED.summary, key_terms = EXCLUDED.key_terms, content_cards = EXCLUDED.content_cards;
INSERT INTO public.chunks (id, chapter_id, lesson_id, chunk_index, chunk_title, en_chunk_title, type, icon_emoji, xp_reward, stars_reward, summary, audio_narration_text, en_audio_narration_text, ai_tutor_prompt, simplified_explanation, key_terms, content_cards)
VALUES ('ch4-l1-exam', 4, '4-1', 2, '🏆 التحدي الختامي: اختبار إتقان الدرس (4-1) الشامل', '🏆 Final Challenge: Lesson (4-1) Mastery Exam', 'lesson_exam', '⏳', 100, 3, 'اختبار امتحاني شامل يغطي أنواع الوسائط ونقاط القوة لكل منها، وأنماط الاتصال أحادي وثنائي الاتجاه واختيار الوسيط المناسب.', 'وصلت لاختبار إتقان الدرس الأول من الفصل الرابع! أجب عن الأسئلة الامتحانية بنجاح لتنال كأس التميز وتفتح الدرس التالي!', 'Welcome to the Lesson 4-1 Mastery Challenge! Test your knowledge of media affordances, vector mathematics, and audio-video compression codecs to earn your gold trophy!', '', '', '[]'::jsonb, '[]'::jsonb)
ON CONFLICT (id) DO UPDATE SET chunk_title = EXCLUDED.chunk_title, summary = EXCLUDED.summary, key_terms = EXCLUDED.key_terms, content_cards = EXCLUDED.content_cards;
INSERT INTO public.chunks (id, chapter_id, lesson_id, chunk_index, chunk_title, en_chunk_title, type, icon_emoji, xp_reward, stars_reward, summary, audio_narration_text, en_audio_narration_text, ai_tutor_prompt, simplified_explanation, key_terms, content_cards)
VALUES ('ch4-l2-c1', 4, '4-2', 1, 'شخصية المستخدم (Persona) وهندسة المعلومات ومبادئ CRAP', 'User Persona, Information Architecture & CRAP Principles', 'chunk', '👤', 35, 1, 'كيف نفكر كمصمم واجهات محترف: بناء شخصية المستخدم (Persona)، تنظيم وهيكلة المعلومات، ومبادئ التصميم المرئي الأربعة المشهورة CRAP.', 'قبل أن نرسم خطاً واحداً في تصميم الموقع، يجب أن نسأل: من هو المستخدم الحقيقي؟ هنا يأتي دور الـ Persona؛ وهي شخصية خيالية تمثل نمطاً حقيقياً من المستخدمين واحتياجاتهم مبنية على أبحاث ودراسات. ثم تأتي هندسة المعلومات لتنظيم المحتوى في خريطة موقع بديهية. وأخيراً نطبق مبادئ التصميم الأربعة الشهيرة CRAP: التباين (Contrast) لإبراز الأهم، التكرار (Repetition) للاتساق، المحاذاة (Alignment) للتنظيم، والتقارب (Proximity) لتجميع العناصر المترابطة.', 'Great web design begins with empathy: Designers construct a User Persona—a research-backed semi-fictional archetype representing the target audience''s demographics, professional motivations, and technical pain points. Next, designers organize Information Architecture: structuring navigation menus and hierarchical content so users locate answers effortlessly. Visual layout is governed by the four CRAP principles: Contrast, Repetition, Alignment, and Proximity.', 'ممتاز يا بطل! استوعبت مبادئ CRAP الأربعة ولماذا نبني شخصية المستخدم Persona قبل التصميم؟', 'تصميم موقع بدون Persona مثل طبخ وجبة وأنت لا تعرف هل الضيوف يحبون السكر أم الملح! ومبادئ CRAP مثل ترتيب غرفتك: ملابسك معاً (تقارب)، على استقامة واحدة (محاذاة)، ألوان دولابك متناسقة (تكرار)، وإضاءة بارزة على مكتبك (تباين)!', '[{"term":"شخصية المستخدم (Persona)","en":"User Persona","definition":"شخصية خيالية مبنية على بيانات واقعية تمثل نموذجاً للمستخدمين المستهدفين بالموقع وسلوكياتهم وأهدافهم.","example":"تصميم شخصية ''أحمد الطالب المستعجل'' لتسهيل الوصول المباشر للدروس دون خطوات زائدة.","examTip":"سؤال متكرر: الـ Persona تبنى على أبحاث واستبيانات حقيقية وليست تخمينات عشوائية من المصمم."},{"term":"مبادئ التصميم الأربعة (CRAP)","en":"CRAP Principles","definition":"المبادئ العالمية الأربعة لتصميم واجهات مريحة: التباين Contrast، التكرار Repetition، المحاذاة Alignment، والتقارب Proximity.","example":"جعل زر ''الشراء الآن'' بلون برتقالي مميز عن الخلفية البيضاء يطبق مبدأ التباين.","examTip":"احفظ حروف CRAP وما يمثله كل حرف باللغة العربية والإنجليزية."}]'::jsonb, '[{"type":"concept","title":"مبادئ التصميم الأربعة CRAP بالترتيب:","points":["🎨 C - التباين (Contrast): جعل العناصر المهمة مختلفة وبارزة بوضوح عن الخلفية لجذب العين.","🔁 R - التكرار (Repetition): استخدام نفس الألوان والخطوط والأزرار في كل الصفحات لتحقيق الاتساق.","📐 A - المحاذاة (Alignment): وضع العناصر على خطوط بصرية مستقيمة لإعطاء شعور بالتنظيم والراحة.","🧲 P - التقارب (Proximity): وضع العناصر المترابطة معاً في مجموعة واحدة، وفصل غير المترابطة بمساحات بيضاء."]}]'::jsonb)
ON CONFLICT (id) DO UPDATE SET chunk_title = EXCLUDED.chunk_title, summary = EXCLUDED.summary, key_terms = EXCLUDED.key_terms, content_cards = EXCLUDED.content_cards;
INSERT INTO public.chunks (id, chapter_id, lesson_id, chunk_index, chunk_title, en_chunk_title, type, icon_emoji, xp_reward, stars_reward, summary, audio_narration_text, en_audio_narration_text, ai_tutor_prompt, simplified_explanation, key_terms, content_cards)
VALUES ('ch4-l2-c2', 4, '4-2', 2, 'مبادئ تصميم PARC البصرية والتصميم المتمحور حول المستخدم (UCD)', 'PARC Visual Principles & User-Centered Design (UCD)', 'chunk', '🎨', 35, 1, 'المبادئ الأربعة المعتمدة للتصميم البصري (التباين Contrast، التكرار Repetition، المحاذاة Alignment، التقارب Proximity)، وفلسفة التصميم المتمحور حول المستخدم (UCD).', 'بعد الانتهاء من المخطط الهيكلي وتحديد أماكن العناصر، ننتقل للمبادئ الهندسية البصرية الأربعة الشهيرة مبادئ PARC في كتاب الوزارة: المبدأ الأول هو التباين Contrast؛ تكبير العناوين وإبراز الأزرار الهامة بألوان واضحة لجذب عين الزائر فورياً. المبدأ الثاني هو التكرار Repetition؛ توحيد نوع الخط والألوان وشكل الأزرار في كل الصفحات لتحقيق الاتساق والراحة. المبدأ الثالث هو المحاذاة Alignment؛ رص النصوص والعناصر على خطوط شبكية موحدة لتبدو الصفحة منظمة كالمبنى المعماري. والمبدأ الرابع هو التقارب Proximity؛ تجميع العناصر المترابطة معاً في بطاقة واحدة مثل صورة المنتج واسمه وسعره وزر شرائه! وكل هذا يخدم الفلسفة الكبرى: التصميم المتمحور حول المستخدم UCD الذي يجعل حاجة المستخدم وسياقه أساساً لكل قرار تصميمي!', 'Visual clarity is achieved by mastering the four PARC / CRAP principles: Proximity groups related elements together to indicate relationships. Alignment ensures every visual element shares a clean invisible baseline with other elements on the canvas. Repetition establishes consistency through cohesive color palettes, button styles, and fonts. Contrast creates dynamic visual hierarchy by highlighting primary calls to action. These principles operationalize User-Centered Design (UCD), an iterative cycle of Research, Design, Prototyping, and Usability Testing.', 'عاش يا بطل! عرفت كيف تفرق بين التباين والتكرار والمحاذاة والتقارب في مبادئ PARC؟ جاهز للتحدي؟', 'لو عندك جريدة: العنوان العريض الأسود تباين، نفس شكل الخط في كل صفحة تكرار، ترتيب الأعمدة بمسطرة مستقيمة محاذاة، ووضع صورة الخبر ملتصقة بنص الخبر تقارب!', '[{"term":"مبادئ PARC البصرية","en":"PARC Principles","definition":"المبادئ الأربعة المعتمدة بكتاب الوزارة لتنظيم الشكل البصري: التباين (Contrast)، التكرار (Repetition)، المحاذاة (Alignment)، والتقارب (Proximity).","example":"التباين يبرز، التكرار يوحّد، المحاذاة تنظم، والتقارب يجمع.","examTip":"سؤال وزاري طابق: العناوين الغامقة = تباين | توحيد الخط = تكرار | النص من اليمين = محاذاة | بطاقة المنتج = تقارب (ص 77)."},{"term":"التصميم المتمحور حول المستخدم","en":"User-Centered Design (UCD)","definition":"نهج تصميمي يجعل فهم المستخدمين واحتياجاتهم وسياق استخدامهم ومهامهم أساساً لجميع قرارات التصميم والتطوير.","example":"تصميم صفحة استعلام نتائج تضع حقل رقم الجلوس وزر البحث في أعلى الشاشة بوضوح لراحة ولي الأمر المشغول.","examTip":"سؤال اختر: المفهوم الأنسب لـ UCD هو بدء التصميم انطلاقاً مما يحتاجه المستخدم وسياقه (ص 79)."}]'::jsonb, '[{"type":"concept","title":"جدول مبادئ PARC البصرية الأربعة (كتاب الوزارة ص 76):","points":["🌟 1. التباين (Contrast): جعل أولوية المعلومات واضحة وإبراز أهم العناصر (تكبير العناوين وألوان الأزرار).","🔄 2. التكرار (Repetition): تكرار خصائص محددة لتحقيق الاتساق البصري وتفادي التشتت (توحيد الخطوط والقوائم).","📏 3. المحاذاة (Alignment): محاذاة العناصر إلى خط أساس مشترك وفق شبكة التصميم لإضفاء النظام والتماسك.","🧲 4. التقارب (Proximity): وضع المعلومات المرتبطة قريبة من بعضها لتُدرك كمجموعة واحدة مع مسافات بيضاء تفصل المجموعات."]}]'::jsonb)
ON CONFLICT (id) DO UPDATE SET chunk_title = EXCLUDED.chunk_title, summary = EXCLUDED.summary, key_terms = EXCLUDED.key_terms, content_cards = EXCLUDED.content_cards;
INSERT INTO public.chunks (id, chapter_id, lesson_id, chunk_index, chunk_title, en_chunk_title, type, icon_emoji, xp_reward, stars_reward, summary, audio_narration_text, en_audio_narration_text, ai_tutor_prompt, simplified_explanation, key_terms, content_cards)
VALUES ('ch4-l2-exam', 4, '4-2', 2, '🏆 التحدي الختامي: اختبار إتقان الدرس (4-2) الشامل', '🏆 Final Challenge: Lesson (4-2) Mastery Exam', 'lesson_exam', '⏳', 100, 3, 'اختبار امتحاني شامل يغطي شخصية المستخدم Persona، هندسة وتصميم المعلومات، ومبادئ CRAP الأربعة وتجربة المستخدم UX.', 'وصلت لاختبار إتقان الدرس الثاني من الفصل الرابع! أجب عن الأسئلة الامتحانية لتثبت احترافك في تصميم تجربة المستخدم وتنال النجوم الثلاثة!', 'Welcome to the Lesson 4-2 Mastery Challenge! Test your deep understanding of User Personas, Information Architecture, and the CRAP visual principles to claim your gold trophy!', '', '', '[]'::jsonb, '[]'::jsonb)
ON CONFLICT (id) DO UPDATE SET chunk_title = EXCLUDED.chunk_title, summary = EXCLUDED.summary, key_terms = EXCLUDED.key_terms, content_cards = EXCLUDED.content_cards;
INSERT INTO public.chunks (id, chapter_id, lesson_id, chunk_index, chunk_title, en_chunk_title, type, icon_emoji, xp_reward, stars_reward, summary, audio_narration_text, en_audio_narration_text, ai_tutor_prompt, simplified_explanation, key_terms, content_cards)
VALUES ('ch4-l3-c1', 4, '4-3', 1, 'التقييم النوعي والتقييم الكمي واختبار أ/ب (A/B Testing)', 'Qualitative vs Quantitative Website Evaluation & A/B Testing', 'chunk', '📊', 35, 1, 'كيف نختبر نجاح الموقع: التقييم النوعي (اختبار قابلية الاستخدام Usability Testing والمقابلات) والتقييم الكمي (معدل الارتداد ووقت البقاء)، والخرائط الحرارية واختبار A/B.', 'كيف نعرف هل موقعنا ناجح ومريح للمستخدمين أم معقد ويحتاج تعديلاً؟ نستخدم أداتين تكامليتين: الأولى هي التقييم النوعي (Qualitative) بمراقبة مستخدمين حقيقيين أثناء تجربة الموقع وسؤالهم عن الصعوبات التي واجهوها لمعرفة السبب ''لماذا تعثر المستخدم؟''. والثانية هي التقييم الكمي (Quantitative) بالأرقام والمؤشرات الرقمية مثل معدل الارتداد، والخرائط الحرارية للنقرات، واختبار أ/ب لمقارنة نسختين من الصفحة ورؤية أيتهما تحقق مبيعات وتسجيلات أعلى.', 'How do we know if a website''s design is truly successful? Web professionals combine two evaluation approaches: Qualitative Evaluation uncovers the ''Why'' behind user behavior through recorded usability testing sessions, interviews, and cognitive walkthroughs. Quantitative Evaluation measures the ''What'' and ''How many'' through analytics metrics like bounce rates, time on page, and A/B Testing—where two versions of a webpage (Version A vs Version B) are compared to measure which achieves higher conversion rates.', 'عاش يا بطل! عرفت الفارق بين أن تسأل المستخدم عن رأيه (نوعي) وأن تقيس أرقام الزيارات (كمي)؟ تحب نبدأ التحدي؟', 'لو عندك مطعم: التقييم النوعي أن تسأل الزبون: ''كيف كان طعم الشوربة؟'' فيخبرك أنها باردة. التقييم الكمي أن تعد كم زبوناً أكل كل الطبق وكم شخصاً تركه دون لمسه! كلاهما مهم لتفهم الحقيقة!', '[{"term":"التقييم النوعي والكمي","en":"Qualitative vs Quantitative","definition":"النوعي يركز على المشاعر والملاحظات والأسباب المعمقة (لماذا؟)؛ بينما الكمي يركز على الأرقام والإحصائيات والنسب المئوية (كم؟).","example":"النوعي: مقابلة 5 مستخدمين؛ الكمي: قياس نسبة نقرات 100 ألف زائر.","examTip":"سؤال امتحان: التقييم الأفضل يجمع بين الطريقتين معاً (الأرقام والملاحظات المباشرة)."},{"term":"اختبار أ/ب","en":"A/B Testing","definition":"تجربة علمية يتم فيها إطلاق نسختين مختلفتين من الصفحة (نسخة أ ونسخة ب) على عينة من الزوار لمعرفة أيتهما تحقق أداءً وتفاعلاً أفضل.","example":"اختبار هل الزر الأخضر يجلب اشتراكات أكثر أم الزر الأزرق؟","examTip":"يقلل التخمينات الشخصية ويبني القرارات على سلوك المستخدمين الفعلي."}]'::jsonb, '[{"type":"concept","title":"أدوات تقييم المواقع الإلكترونية المعتمدة بالمنهج:","points":["👁️ اختبار قابلية الاستخدام (Usability Testing): مراقبة المستخدم وتدوين أخطائه وصعوباته.","📊 تحليلات الويب (Analytics): قياس معدل الارتداد (Bounce Rate) ومتوسط زمن الزيارة.","🔥 الخرائط الحرارية (Heatmaps): تمثيل بصري بالألوان لمواضع نقرات وحركة فأرة الزوار.","⚖️ اختبار أ/ب (A/B Testing): المقارنة الإحصائية بين نسختين من التصميم لاتخاذ القرار الأفضل."]}]'::jsonb)
ON CONFLICT (id) DO UPDATE SET chunk_title = EXCLUDED.chunk_title, summary = EXCLUDED.summary, key_terms = EXCLUDED.key_terms, content_cards = EXCLUDED.content_cards;
INSERT INTO public.chunks (id, chapter_id, lesson_id, chunk_index, chunk_title, en_chunk_title, type, icon_emoji, xp_reward, stars_reward, summary, audio_narration_text, en_audio_narration_text, ai_tutor_prompt, simplified_explanation, key_terms, content_cards)
VALUES ('ch4-l3-c2', 4, '4-3', 2, 'التقييم الإرشادي (Heuristic Evaluation) وتكامل الأدلة لتقييم المواقع', 'Heuristic Evaluation & Triangulation of Evidence', 'chunk', '🔍', 35, 1, 'مراجعة الخبراء لواجهة المستخدم استناداً للقواعد الإرشادية (الاتساق، منع الأخطاء، وضوح حالة النظام)، وتكامل الأدلة النوعية (لماذا؟) مع الأرقام الكمية (كم؟).', 'بجانب اختبارات المستخدمين والتحليلات الرقمية، لدينا أسلوب نوعي فائق الأهمية يُسمى التقييم الإرشادي Heuristic Evaluation؛ وهو مراجعة متخصصة يجريها خبراء لواجهة المستخدم استناداً لقواعد ومبادئ إرشادية عملية قبل إطلاق الموقع. وأبرز هذه القواعد ثلاث: أولاً الاتساق Consistency بتوحيد الأزرار والرموز في كل الصفحات، ثانياً منع الأخطاء Error Prevention بجعل ارتكاب الخطأ صعباً مثل رسائل تأكيد الحذف وتوضيح الحقول الإلزامية، وثالثاً وضوح حالة النظام System Status بإظهار مؤشرات التحميل ورسائل تأكيد الإرسال فورياً! وتذكر دائماً الحقيقة المنهجية الكبرى من كتاب الوزارة: الأرقام الكمية تكشف ماذا يحدث، لكن الخبراء والمستخدمين بالطرق النوعية يفسرون لماذا يتصرف المستخدمون هكذا؛ والجمع بينهما هو سر النجاح!', 'Beyond testing with users, design teams employ Heuristic Evaluation: usability experts review an interface against Jakob Nielsen''s 10 recognized Usability Heuristics—such as Visibility of System Status (giving immediate feedback), Match between System and Real World, User Control & Freedom (providing an Undo button), and Consistency. To avoid bias, organizations practice Triangulation of Evidence: combining heuristic audits, usability testing, and web analytics to validate improvements with certainty.', 'عظيم يا بطل! استوعبت دور التقييم الإرشادي والقواعد الثلاث (الاتساق، منع الأخطاء، حالة النظام)؟ جاهز للتحدي؟', 'التقييم الإرشادي مثل استدعاء مهندس فحص مبانٍ خبير: يفحص بنفسه الأبواب والأسلاك والمخارج ويتأكد أنها مطابقة للمواصفات القياسية قبل أن يسكن الناس فيها!', '[{"term":"التقييم الإرشادي","en":"Heuristic Evaluation","definition":"شكل من أشكال التقييم النوعي يتمثل في مراجعة يقوم بها خبراء لواجهة المستخدم (UI) استناداً إلى قواعد ومبادئ إرشادية عملية لبحث المشكلات وعلاجها.","example":"فحص خبير للموقع للتأكد من وجود رسائل خطأ واضحة ومؤشرات تحميل عند الدفع.","examTip":"سؤال وزاري مباشر: ما هو التقييم الإرشادي وما القواعد الثلاث المعتمدة له؟ (كتاب ص 83)."},{"term":"قواعد التقييم الإرشادي الثلاث","en":"Heuristic Rules","definition":"المعايير الثلاثة المعتمدة بالمنهج: 1. الاتساق (Consistency) • 2. منع الأخطاء (Error Prevention) • 3. وضوح حالة النظام (System Status).","example":"تأكيد الحذف (منع خطأ)، شريط التحميل (حالة النظام)، وأزرار موحدة (اتساق).","examTip":"سؤال اختر: من القواعد الإرشادية المعتمدة: الاتساق، منع الأخطاء، ووضوح حالة النظام (ص 85)."}]'::jsonb, '[{"type":"concept","title":"القواعد الإرشادية الثلاث المعتمدة في التقييم الإرشادي (كتاب ص 83):","points":["🔄 1. الاتساق (Consistency): توحيد التصميم ومسميات الأزرار والعمليات لتفادي التشتت.","🛡️ 2. منع الأخطاء (Error Prevention): جعل ارتكاب الخطأ صعباً (تأكيد الحذف، وإبراز الحقول الإلزامية).","⏱️ 3. وضوح حالة النظام (System Status): إخبار المستخدم بما يفعله النظام لحظياً (أشرطة التحميل ونجاح الإرسال)."]}]'::jsonb)
ON CONFLICT (id) DO UPDATE SET chunk_title = EXCLUDED.chunk_title, summary = EXCLUDED.summary, key_terms = EXCLUDED.key_terms, content_cards = EXCLUDED.content_cards;
INSERT INTO public.chunks (id, chapter_id, lesson_id, chunk_index, chunk_title, en_chunk_title, type, icon_emoji, xp_reward, stars_reward, summary, audio_narration_text, en_audio_narration_text, ai_tutor_prompt, simplified_explanation, key_terms, content_cards)
VALUES ('ch4-l3-exam', 4, '4-3', 2, '🏆 التحدي الختامي: اختبار إتقان الدرس (4-3) الشامل', '🏆 Final Challenge: Lesson (4-3) Mastery Exam', 'lesson_exam', '⏳', 100, 3, 'اختبار امتحاني شامل يغطي طرق التقييم النوعي والكمي، والخرائط الحرارية واختبار A/B ومؤشرات أداء المواقع الإلكترونية.', 'وصلت لاختبار إتقان الدرس الثالث من الفصل الرابع! أجب عن الأسئلة الامتحانية بدقة لتنال كأس التميز وتفتح الدرس الأخير!', 'Welcome to the Lesson 4-3 Mastery Challenge! Demonstrate your mastery of usability testing, statistical A/B experimentation, and heuristic auditing to earn your gold trophy!', '', '', '[]'::jsonb, '[]'::jsonb)
