INSERT INTO public.chunks (id, chapter_id, lesson_id, chunk_index, chunk_title, en_chunk_title, type, icon_emoji, xp_reward, stars_reward, summary, audio_narration_text, en_audio_narration_text, ai_tutor_prompt, simplified_explanation, key_terms, content_cards)
VALUES ('ch4-l4-c1', 4, '4-4', 1, 'دورة حلقة التحسين المستمر PDCA وحلقات التغذية الراجعة', 'The PDCA Continuous Improvement Cycle & Feedback Loops', 'chunk', '🔁', 35, 1, 'الموقع عملية مستمرة لا تنتهي: نموذج PDCA العالمي (خطط Plan - نفّذ Do - تحقق Check - طوّر Act)، وحلقات التغذية الراجعة وصيانة الويب.', 'الموقع الإلكتروني لا ينتهي بمجرد برمجته وإطلاقه أول مرة؛ بل هو كائن رقمي حي يحتاج إلى تحسين مستمر! هنا نتعلم النموذج العالمي لإدارة الجودة والتحسين التكراري PDCA المكون من 4 خطوات دائرية لا تنتهي: خطط (Plan) بتحديد أهداف التطوير، نفّذ (Do) بتطبيق التعديلات البرمجية، تحقق (Check) بقياس أثر التعديل على الزوار، وطوّر (Act) باعتماد التعديل الناجح وبدء دورة جديدة. مع الاستماع المستمر لآراء وشكاوى المستخدمين عبر حلقات التغذية الراجعة.', 'A website is never ''finished'' upon launch; it is a living system requiring continuous refinement through the PDCA Cycle (Plan-Do-Check-Act): In the Plan phase, teams identify performance gaps and formulate testable improvement hypotheses. In the Do phase, developers execute the change (such as launching an A/B test). In the Check phase, analytics measure whether key metrics improved. In the Act phase, successful changes are standardized across the site, and the cycle begins anew.', 'عظيم يا بطل! عرفت خطوات دورة PDCA الأربعة ولماذا تطوير المواقع عملية دائرية لا تتوقف؟', 'الموقع الناجح مثل السيارة في رحلة طويلة: تخطط للمسار (Plan)، تقود للأمام (Do)، تفحص مؤشر البنزين والحرارة (Check)، وتصلح أي خلل وتواصل الرحلة (Act)!', '[{"term":"دورة PDCA","en":"PDCA Cycle","definition":"نموذج إدارة الجودة الرباعي للتحسين المستمر المكون من: Plan (خطط)، Do (نفّذ)، Check (تحقق)، Act (طوّر/تصرّف).","example":"التخطيط لتغيير صفحة الدفع ← برمجتها وتجربتها ← قياس زيادة المبيعات ← تثبيتها والانتقال لصفحة أخرى.","examTip":"سؤال متكرر: ما هي خطوات دورة PDCA بالترتيب؟ خطط، نفّذ، تحقق، طوّر."},{"term":"حلقة التغذية الراجعة","en":"Feedback Loop","definition":"آلية مستمرة لجمع تعليقات وشكاوى واقتراحات المستخدمين وتحليلها وتحويلها إلى خطط تطوير للموقع.","example":"نموذج تقييم الخدمة أو زر ''أبلغ عن خطأ في الصفحة''.","examTip":"المحرك الأساسي لنجاح دورة التحسين التكراري."}]'::jsonb, '[{"type":"concept","title":"خطوات دورة PDCA الأربعة بالتفصيل:","points":["📋 1. خطط (Plan): دراسة المشاكل الحالية، ووضع أهداف واضحة وخطة للتحسين.","🛠️ 2. نفّذ (Do): تطبيق التعديلات عملياً على نطاق تجريبي محدد.","📊 3. تحقق (Check): قياس نتائج التعديل بالأرقام ومقارنتها بالأهداف السابقة.","🚀 4. طوّر وتصرّف (Act): اعتماد التحسين الناجح رسمياً، وتحديد نقطة التحسين التالية."]}]'::jsonb)
ON CONFLICT (id) DO UPDATE SET chunk_title = EXCLUDED.chunk_title, summary = EXCLUDED.summary, key_terms = EXCLUDED.key_terms, content_cards = EXCLUDED.content_cards;
INSERT INTO public.chunks (id, chapter_id, lesson_id, chunk_index, chunk_title, en_chunk_title, type, icon_emoji, xp_reward, stars_reward, summary, audio_narration_text, en_audio_narration_text, ai_tutor_prompt, simplified_explanation, key_terms, content_cards)
VALUES ('ch4-l4-c2', 4, '4-4', 2, 'اختبار A/B وقواعد عزل المتغير الواحد وثقافة التحسين المستمر', 'A/B Testing Single Variable Rules & Improvement Culture', 'chunk', '🧪', 35, 1, 'المقارنة المنهجية ببيانات فعلية عبر اختبار A/B (النسخة A الأصلية vs النسخة B المعدلة)، وأهمية عزل المتغير الواحد لتفادي مصيدة الحزمة المتعددة.', 'كيف تحسم فرق التطوير المحترفة الخلافات حول شكل الزر أو موضع العرض؟ عبر اختبار A/B المنهجي! اختبار A/B هو تجربة علمية منظمة تقارن بين نسختين: النسخة A الأصلية، والنسخة B التي تحوي تعديلاً مقصوداً، ويتم توزيع الزوار بينهما عشوائياً بنسب متساوية لقياس أي النسختين تحقق معدل تحويل ونقرات أعلى. والقاعدة الذهبية في كتاب الوزارة هي: عزل المتغير الواحد! إذا أردت معرفة أثر تغيير لون الزر، فلا تغير النص واللون والصور ومكان الزر دفعة واحدة؛ لأن تغيير حزمة عناصر يقيس أثر الحزمة الإجمالي فقط ويعجز عن معرفة أي عنصر كان مفيداً وأي عنصر كان ضاراً! فالمواقع الناجحة لا تولد مثالية دفعة واحدة، بل تتطور وتتحسن تكرارياً خطوة بخطوة!', 'To execute the PDCA cycle with scientific rigor, organizations enforce the Single-Variable Rule in A/B Testing: when testing a page, only one specific element (such as button color, headline copy, or form length) is varied between Version A and Version B. If multiple elements are altered simultaneously, it becomes impossible to determine which specific change caused the performance variance. Embracing an iterative culture ensures web applications continuously evolve based on empirical data rather than personal opinions.', 'ممتاز يا بطل! عرفت لماذا نغير عنصراً واحداً فقط في اختبار A/B وما هي مخاطر تغيير كل شيء معاً؟', 'لو طبيب أعطى مريضاً 5 أدوية مختلفة معاً فتحسن المريض؛ الطبيب لن يعرف أي دواء هو الذي شفاه وأي دواء سبب له ألماً في المعدة! لذلك يجب اختبار كل دواء على حدة، وهذا هو عزل المتغير في اختبار A/B!', '[{"term":"اختبار A/B","en":"A/B Testing","definition":"تجربة منظمة تقارن نسختين (A الأصلية و B المعدلة) وفق مقياس محدد مسبقاً عبر توزيع الزوار عشوائياً لحسم القرارات بالأدلة الرقمية.","example":"مقارنة زر شراء أحمر بالنسخة A بزر أزرق بالنسخة B لمعرفة أيهما يحصل على نقرات ومشتريات أعلى.","examTip":"سؤال مصطلح علمي: تجربة منظمة يُعد فيها نمطان A وB ويُقارنان بالبيانات لمعرفة الأفضل (كتاب ص 90)."},{"term":"عزل المتغير الواحد","en":"Single Variable Isolation","definition":"مبدأ علمي يقضي بتعديل عنصر واحد محدد في النسخة B (كاللون أو النص) وتثبيت باقي العناصر، لعزل أثر هذا التغيير بدقة وتفادي ''أثر الحزمة المضلل''.","example":"تغيير لون الزر فقط دون تغيير نصه أو مكانه أو صور الصفحة.","examTip":"سؤال لغز وزاري: لماذا يُعد تعديل عدة عناصر معاً في النسخة B عيباً منهجياً؟ لأنه يقيس أثر الحزمة ولا يعزل أثر كل عنصر (ص 91)."}]'::jsonb, '[{"type":"concept","title":"القواعد الأساسية لإجراء اختبار A/B السليم (كتاب ص 91):","points":["🎯 1. عزل المتغير الواحد: تغيير عنصر واحد فقط لمعرفة أثره المباشر والمحدد.","📊 2. تحديد المقياس مسبقاً: الاتفاق على معيار النجاح (معدل النقرات أو إتمام الشراء) قبل بدء التجربة.","👥 3. حجم العينة الكافي: جمع بيانات كافية إحصائياً وتوزيع الزوار عشوائياً قبل إصدار الحكم النهائي."]}]'::jsonb)
ON CONFLICT (id) DO UPDATE SET chunk_title = EXCLUDED.chunk_title, summary = EXCLUDED.summary, key_terms = EXCLUDED.key_terms, content_cards = EXCLUDED.content_cards;
INSERT INTO public.chunks (id, chapter_id, lesson_id, chunk_index, chunk_title, en_chunk_title, type, icon_emoji, xp_reward, stars_reward, summary, audio_narration_text, en_audio_narration_text, ai_tutor_prompt, simplified_explanation, key_terms, content_cards)
VALUES ('ch4-l4-exam', 4, '4-4', 2, '🏆 التحدي الختامي: اختبار إتقان الدرس (4-4) الشامل وختام الترم الأول', '🏆 Final Challenge: Lesson (4-4) Mastery Exam & First Term Grand Finale', 'lesson_exam', '⏳', 150, 5, 'اختبار ختامي وزاري يجمع دورة التحسين التكراري PDCA وتتويج إتقان منهج البرمجة والذكاء الاصطناعي كاملاً!', 'مبروك يا بطل وصولك للقمة! هذا هو التحدي الختامي للفصل الرابع والترم الأول كاملاً! اجتيازك لهذا الاختبار يمنحك وسام التميز الأكبر وكأس تفوق المنهج كاملاً من إعداد وإشراف م/ محمد راشد!', 'Welcome to the Grand Finale Challenge of Lesson 4-4 and the entire First Term curriculum! Demonstrate your comprehensive mastery of continuous improvement, PDCA cycles, and empirical web optimization to earn your crowning gold trophy!', '', '', '[]'::jsonb, '[]'::jsonb)
