VALUES ('ch1-l1-c1_q2_alt', 'ch1-l1-c1', '1-1', 1, 4, 'true_false', 'ظهرت الحوسبة السحابية والبيانات الضخمة في سبعينيات القرن العشرين.', '[]'::jsonb, NULL, FALSE, NULL, NULL, '[]'::jsonb, 'خطأ؛ الحوسبة السحابية والبيانات الضخمة انتشرت من العقد الثاني من الألفية فصاعداً.')
