INSERT INTO public.questions (id, chunk_id, lesson_id, chapter_id, question_index, level, question, options, correct_index, is_true, correct_term, english_term, acceptable_answers, explanation)
VALUES ('ch1-l1-c1_q_best', 'ch1-l1-c1', '1-1', 1, 5, 'best_choice', 'جميع العبارات التالية صحيحة عن الحوسبة السحابية (المحطة الخامسة)، ولكن ما هو التوصيف الأصح والأشمل لمفهومها كنموذج حديث؟', '["وسيلة مريحة لحفظ النسخ الاحتياطية من الصور والملفات الشخصية أونلاين.","تقنية تتيح للمستخدمين تشغيل البرامج وتصفح الإنترنت من أي جهاز محمول.","نموذج لتوفير كافة موارد تكنولوجيا المعلومات (معالجة، تخزين، شبكات، برمجيات) كخدمات مدارة عند الطلب عبر الإنترنت مع الدفع الفعلي حسب الاستهلاك.","نظام لتوصيل خوادم الشركات الكبرى ببعضها عبر كابلات الألياف الضوئية."]'::jsonb, 2, NULL, NULL, NULL, '[]'::jsonb, 'جميع الخيارات تمثل جوانب وفوائد حقيقية للسحابة، لكن الخيار (ج) هو التعريف العلمي الأصح والأشمل المعتمد أكاديمياً كنموذج متكامل (IT as a Service).')
