INSERT INTO public.questions (id, chunk_id, lesson_id, chapter_id, question_index, level, question, options, correct_index, is_true, correct_term, english_term, acceptable_answers, explanation)
VALUES ('ch1-l1-c1_q_reinforce', 'ch1-l1-c1', '1-1', 1, 7, 'mcq', 'ما هو السبب الجوهري الذي جعل حاسوب ENIAC يقتصر استخدامه على الأغراض العسكرية والعلمية الكبرى دون المنازل؟', '["عدم وجود شاشات ملونة في ذلك الوقت","اعتماده على آلاف الصمامات المفرغة الضخمة واستهلاكه الهائل للطاقة واحتياجه لمساحات غرف كاملة وصيانة معقدة","رفض الحكومات بيعه للأفراد لأسباب أمنية فقط","عدم اختراع لوحة المفاتيح والماوس"]'::jsonb, 1, NULL, NULL, NULL, '[]'::jsonb, 'حاسوب ENIAC كان يشغل غرفة كاملة بوزن 30 طناً ويعتمد على الصمامات المفرغة ويستهلك كهرباء قرية كاملة، مما جعله مستحيلاً للاستخدام الشخصي.')
