INSERT INTO public.questions (id, chunk_id, lesson_id, chapter_id, question_index, level, question, options, correct_index, is_true, correct_term, english_term, acceptable_answers, explanation)
VALUES ('ch1-l1-c2_q_best', 'ch1-l1-c2', '1-1', 1, 5, 'best_choice', 'جميع البدائل التالية تمثل حقائق علمية حول رقائق المعالجات، ولكن أي منها يمثل التفسير الأصح والأشمل لعدم إمكانية الاستمرار في تصغير الترانزستور إلى ما لا نهاية؟', '["ارتفاع تكلفة شراء معدات تصنيع السيليكون المجهرية للشركات المصنعة.","صعوبة تبريد المعالج بالمراوح التقليدية داخل أجهزة الحواسيب المحمولة.","الوصول إلى أبعاد ذرية دقيقة تؤدي لظاهرة النفق الكمومي وتيار التسريب وتوليد حرارة هائلة تعطل البنية الفيزيائية.","عدم استيعاب اللوحة الأم لمزيد من الوصلات النحاسية الدقيقة."]'::jsonb, 2, NULL, NULL, NULL, '[]'::jsonb, 'جميع البدائل تصف صعوبات واقعية، لكن الخيار (ج) هو التفسير العلمي الأصح والأشمل الذي يشكل الحد الفيزيائي الحتمي لقانون مور عند المستوى الذري.')
ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, chunk_id, lesson_id, chapter_id, question_index, level, question, options, correct_index, is_true, correct_term, english_term, acceptable_answers, explanation)
VALUES ('ch1-l1-c2_q3', 'ch1-l1-c2', '1-1', 1, 6, 'timed_fill', NULL, '["الكمومي","الضوئي","الميكانيكي","الكهرومغناطيسي"]'::jsonb, NULL, NULL, NULL, NULL, '[]'::jsonb, 'النفق الكمومي (Quantum Tunneling) يسبب أخطاء تشغيلية عند تصغير الترانزستور لأقل من 1 نانومتر.')
