INSERT INTO public.questions (id, chunk_id, lesson_id, chapter_id, question_index, level, question, options, correct_index, is_true, correct_term, english_term, acceptable_answers, explanation)
VALUES ('ch1-l1-c2_q_reinforce', 'ch1-l1-c2', '1-1', 1, 7, 'mcq', 'ما الحل الهندسي والمعماري الرئيسي المعتمد حالياً لتجاوز حدود تصغير الترانزستور الفردي ومواصلة زيادة الأداء الحاسوبي؟', '["زيادة التردد الكهربائي للمعالج إلى ما لا نهاية","الاعتماد على المعالجات متعددة الأنوية (Multi-Core) والمعالجة المتوازية (Parallel Computing)","تقليل سعة ذاكرة الوصول العشوائي RAM","استخدام الأقراص الممغنطة القديمة HDD"]'::jsonb, 1, NULL, NULL, NULL, '[]'::jsonb, 'بدلاً من زيادة تردد النواة الواحدة وتوليد حرارة هائلة، توجهت هندسة الحواسيب نحو المعالجات متعددة الأنوية لتوزيع المهام بالتوازي.')
