INSERT INTO public.questions (id, chunk_id, lesson_id, chapter_id, question_index, level, question, options, correct_index, is_true, correct_term, english_term, acceptable_answers, explanation)
VALUES ('ch1-l1-c3_q1_alt', 'ch1-l1-c3', '1-1', 1, 2, 'mcq', 'ما هو أبرز مصدر قلق مجتمعي عند التحول الكامل لمجتمع خالٍ من النقد الورقي (Cashless)؟', '["زيادة وزن النقود الورقية","استبعاد الفئات التي لا تمتلك هواتف أو حسابات بنكية ومخاطر انقطاع الشبكة","صعوبة الشراء عبر الإنترنت","سرعة إتمام المدفوعات"]'::jsonb, 1, NULL, NULL, NULL, '[]'::jsonb, 'استبعاد غير القادرين تقنياً ومخاطر انقطاع الطاقة والشبكات هي أكبر تحديات الدفع غير النقدي.')
