VALUES ('ch1-l2-c1_q2', 'ch1-l2-c1', '1-2', 1, 3, 'true_false', 'كل نموذج تعلم عميق (Deep Learning) هو بالضرورة نموذج تعلم آلة (Machine Learning).', '[]'::jsonb, NULL, TRUE, NULL, NULL, '[]'::jsonb, 'صحيح؛ لأن التعلم العميق هو فرع متخصص من تعلم الآلة.')
