INSERT INTO public.questions (id, chunk_id, lesson_id, chapter_id, question_index, level, question, options, correct_index, is_true, correct_term, english_term, acceptable_answers, explanation)
VALUES ('ch1-l2-c1_q2_alt', 'ch1-l2-c1', '1-2', 1, 4, 'true_false', 'تعلم الآلة يتطلب كتابة كود برمجي صارم لكل حالة وقرار يواجهه النظام.', '[]'::jsonb, NULL, FALSE, NULL, NULL, '[]'::jsonb, 'خطأ؛ جوهر تعلم الآلة هو التعلم من البيانات واكتشاف الأنماط دون برمجة صريحة لكل خطوة.')
