INSERT INTO public.questions (id, chunk_id, lesson_id, chapter_id, question_index, level, question, options, correct_index, is_true, correct_term, english_term, acceptable_answers, explanation)
VALUES ('ch1-l2-c1_q_best', 'ch1-l2-c1', '1-2', 1, 5, 'best_choice', 'جميع العبارات التالية صحيحة حول علاقة الذكاء الاصطناعي وتعلم الآلة والتعلم العميق، ولكن أي منها يصف الهيكلية الهرمية الأصح والأشمل؟', '["الذكاء الاصطناعي هو برنامج مستقل تماماً ولا يرتبط بتعلم الآلة إلا في تصنيف الصور.","التعلم العميق هو الأصل الأوسع الذي تفرع منه الذكاء الاصطناعي وتعلم الآلة لاحقاً.","الذكاء الاصطناعي هو المظلة الشاملة لمحاكاة الذكاء البشري، وتعلم الآلة حقل فرعي منه يتعلم من البيانات، والتعلم العميق حقل فرعي من تعلم الآلة يعتمد على شبكات عصبية متعددة الطبقات.","تعلم الآلة يختص بالبيانات الرقمية فقط بينما الذكاء الاصطناعي يختص بالنصوص."]'::jsonb, 2, NULL, NULL, NULL, '[]'::jsonb, 'الخيار (ج) هو التوصيف الهرمي الأصح والمعتمد: AI (المظلة الكبرى) ← ML (المجموعة الفرعية) ← DL (التعلم العميق داخل ML) ← GenAI.')
