VALUES ('ch1-l2-c2_q1', 'ch1-l2-c2', '1-2', 1, 1, 'mcq', 'أي نمط من أنماط تعلم الآلة يعتمد على التجربة والخطأ ونظام المكافآت والعقوبات؟', '["التعلم الخاضع للإشراف (Supervised)","التعلم التعزيزي (Reinforcement Learning)","التعلم غير الموجه (Unsupervised)","الحوسبة الطرفية"]'::jsonb, 1, NULL, NULL, NULL, '[]'::jsonb, 'التعلم التعزيزي يتعلم فيه الوكيل تعظيم المكافأة وتقليل العقوبة.')
