INSERT INTO public.questions (id, chunk_id, lesson_id, chapter_id, question_index, level, question, options, correct_index, is_true, correct_term, english_term, acceptable_answers, explanation)
VALUES ('ch1-l2-c2_q1_alt', 'ch1-l2-c2', '1-2', 1, 2, 'mcq', 'تدريب خوارزمية على التعرف على البريد المزعج (Spam) باستخدام آلاف الرسائل المصنفة مسبقاً هو مثال على:', '["التعلم الخاضع للإشراف (Supervised Learning)","التعلم غير الخاضع للإشراف","التعلم العشوائي","الكمومي"]'::jsonb, 0, NULL, NULL, NULL, '[]'::jsonb, 'طالما توجد تسميات مسبقة (Labeled) فهذا تعلم خاضع للإشراف.')
