INSERT INTO public.questions (id, chunk_id, lesson_id, chapter_id, question_index, level, question, options, correct_index, is_true, correct_term, english_term, acceptable_answers, explanation)
VALUES ('ch1-l2-c2_q2', 'ch1-l2-c2', '1-2', 1, 3, 'true_false', 'التعلم غير الخاضع للإشراف (Unsupervised) يحتاج بالضرورة إلى بيانات موسومة ومصنفة مسبقاً بواسطة خبير بشري.', '[]'::jsonb, NULL, FALSE, NULL, NULL, '[]'::jsonb, 'خطأ؛ ميزة التعلم غير الخاضع للإشراف أنه يكتشف الأنماط في البيانات غير الموسومة بدون إشراف بشري.')
