VALUES ('ch1-l2-c2_q2_alt', 'ch1-l2-c2', '1-2', 1, 4, 'true_false', 'خوارزميات التجميع (Clustering) تُعد من أشهر تطبيقات التعلم غير الخاضع للإشراف.', '[]'::jsonb, NULL, TRUE, NULL, NULL, '[]'::jsonb, 'صحيح؛ تجميع العملاء المتشابهين في قطاعات هو تطبيق أصيل لـ Unsupervised Learning.')
