INSERT INTO public.questions (id, chunk_id, lesson_id, chapter_id, question_index, level, question, options, correct_index, is_true, correct_term, english_term, acceptable_answers, explanation)
VALUES ('ch1-l2-c2_q_best', 'ch1-l2-c2', '1-2', 1, 5, 'best_choice', 'جميع العبارات التالية صحيحة عن طبقات الشبكة العصبية، ولكن ما هو التوصيف الأصح والأشمل للدور الوظيفي للطبقات المخفية (Hidden Layers) في التعلم العميق؟', '["استقبال الصورة الرقمية الخام وتمريرها مباشرة إلى شاشة العرض دون أي تعديل.","تخزين بيانات التدريب في ملف نصي على القرص الصلب لحمايتها من الضياع.","استخلاص الميزات والأنماط التجريدية المعقدة تدريجياً عبر تعديل الأوزان الرياضية ودوال التنشيط لتمكين التنبؤ الدقيق بالمخرجات.","عرض النتائج النهائية بالألوان على واجهة التطبيق أمام المستخدم النهائي."]'::jsonb, 2, NULL, NULL, NULL, '[]'::jsonb, 'الطبقات المخفية تمثل قلب التعلم العميق؛ حيث تستخرج الخصائص من البسيطة إلى المعقدة تدريجياً عبر الأوزان ودوال التنشيط.')
