INSERT INTO public.questions (id, chunk_id, lesson_id, chapter_id, question_index, level, question, options, correct_index, is_true, correct_term, english_term, acceptable_answers, explanation)
VALUES ('ch1-l2-c2_q_reinforce', 'ch1-l2-c2', '1-2', 1, 7, 'mcq', 'ما هي الوظيفة الحسابية الأساسية لدوال التنشيط (Activation Functions) داخل العقد العصبية؟', '["إيقاف تشغيل الخادم عند ارتفاع درجة الحرارة","إدخال خاصية اللاخطية (Non-Linearity) لتمكين الشبكة من تعلم العلاقات والأنماط المعقدة غير الخطية","مسح البيانات المكررة من الذاكرة العشوائية RAM","تحويل الحروف الإنجليزية إلى أرقام صحيحة فقط"]'::jsonb, 1, NULL, NULL, NULL, '[]'::jsonb, 'بدون دوال التنشيط اللاخطية، تظل الشبكة العصبية مجرد معادلة انحدار خطي بسيطة عاجزة عن تمييز الصور أو النصوص المعقدة.')
