INSERT INTO public.questions (id, chunk_id, lesson_id, chapter_id, question_index, level, question, options, correct_index, is_true, correct_term, english_term, acceptable_answers, explanation)
VALUES ('ch1-l2-c3_q1', 'ch1-l2-c3', '1-2', 1, 1, 'mcq', 'ما هي الطبقات المسؤولة عن معالجة البيانات واستخراج الملامح المعقدة داخل الشبكة العصبية؟', '["طبقة المدخلات","الطبقات المخفية (Hidden Layers)","شاشة العرض","لوحة المفاتيح"]'::jsonb, 1, NULL, NULL, NULL, '[]'::jsonb, 'الطبقات المخفية هي قلب الشبكة العصبية التي تحلل البيانات وتستخرج الأنماط.')
