INSERT INTO public.questions (id, chunk_id, lesson_id, chapter_id, question_index, level, question, options, correct_index, is_true, correct_term, english_term, acceptable_answers, explanation)
VALUES ('ch1-l2-c3_q1_alt', 'ch1-l2-c3', '1-2', 1, 2, 'mcq', 'الخوارزمية المسؤولة عن حساب نسبة الخطأ والرجوع للوراء لتعديل أوزان الشبكة تُعرف بـ:', '["الانتشار الخلفي (Backpropagation)","الحوسبة الطرفية","قانون مور","التشفير المتماثل"]'::jsonb, 0, NULL, NULL, NULL, '[]'::jsonb, 'الانتشار الخلفي Backpropagation هو الأساس الرياضي لتعلم وتدريب الشبكات العصبية.')
ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, chunk_id, lesson_id, chapter_id, question_index, level, question, options, correct_index, is_true, correct_term, english_term, acceptable_answers, explanation)
VALUES ('ch1-l2-c3_q2', 'ch1-l2-c3', '1-2', 1, 3, 'true_false', 'تتكون كل شبكة عصبية اصطناعية من طبقة واحدة فقط تقوم بجميع المهام معاً دون طبقات مخفية.', '[]'::jsonb, NULL, FALSE, NULL, NULL, '[]'::jsonb, 'خطأ؛ الشبكات العصبية تتكون من طبقة مدخلات وطبقات مخفية وطبقة مخرجات.')
