INSERT INTO public.questions (id, chunk_id, lesson_id, chapter_id, question_index, level, question, options, correct_index, is_true, correct_term, english_term, acceptable_answers, explanation)
VALUES ('ch1-l2-c3_q2_alt', 'ch1-l2-c3', '1-2', 1, 4, 'true_false', 'تُحاكي الشبكات العصبية الاصطناعية طريقة ترابط الخلايا العصبية البيولوجية في الدماغ البشري.', '[]'::jsonb, NULL, TRUE, NULL, NULL, '[]'::jsonb, 'صحيح؛ هذا هو الإلهام العلمي والتاريخي لبناء الشبكات العصبية الاصطناعية.')
