INSERT INTO public.questions (id, chunk_id, lesson_id, chapter_id, question_index, level, question, options, correct_index, is_true, correct_term, english_term, acceptable_answers, explanation)
VALUES ('ch1-l2-c3_q_best', 'ch1-l2-c3', '1-2', 1, 5, 'best_choice', 'جميع الخيارات تصف مظاهر تفاعل المستخدم مع الذكاء الاصطناعي التوليدي، ولكن أي عبارة تمثل التفسير العلمي الأصح والأشمل لظاهرة ''هلوسة الذكاء الاصطناعي'' (AI Hallucination)؟', '["رغبة النموذج الذكي في تضليل وخداع المستخدم عمداً لاختبار قدراته النقدية.","بطء استجابة الخادم بسبب انقطاع اتصال الإنترنت أثناء مرحلة توليد النص.","قيام النماذج اللغوية بتوليد معلومات خاطئة أو مختلقة بثقة تامة نظراً لاعتمادها على التنبؤ الإحصائي بالكلمة التالية دون إدراك حقيقي لمعنى الحقيقة والواقع.","وجود فيروس إلكتروني في قاعدة بيانات النموذج البرمجي يعطل حساباته."]'::jsonb, 2, NULL, NULL, NULL, '[]'::jsonb, 'الهلوسة ناتجة عن الطبيعة الاحتمالية للنماذج اللغوية (توقع الكلمة الأكثر احتمالاً إحصائياً) وليس عن وعي أو خداع متعمد.')
