VALUES ('ch1-l2-c3_q3', 'ch1-l2-c3', '1-2', 1, 6, 'timed_fill', NULL, '["مخرجات","مدخلات","عوازل","أسلاك"]'::jsonb, NULL, NULL, NULL, NULL, '[]'::jsonb, 'طبقة المخرجات تعرض النتيجة النهائية للتوقع أو التصنيف.')
ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, chunk_id, lesson_id, chapter_id, question_index, level, question, options, correct_index, is_true, correct_term, english_term, acceptable_answers, explanation)
VALUES ('ch1-l2-c3_q_reinforce', 'ch1-l2-c3', '1-2', 1, 7, 'mcq', 'ما الإجراء الوقائي الإلزامي الذي يوصي به منهج الوزارة دائماً عند استخدام إجابات الذكاء الاصطناعي التوليدي؟', '["قبول الإجابات فوراً دون قراءة لأن الذكاء الاصطناعي لا يخطئ أبداً","التحقق البشري الصارم والرجوع للمصادر العلمية المعتمدة للتأكد من دقة الحقائق والأرقام","إعادة تشغيل الحاسوب قبل نسخ ولصق النص المولد","ترجمة النص إلى لغة أخرى ثم إعادته للغة الأصلية"]'::jsonb, 1, NULL, NULL, NULL, '[]'::jsonb, 'المنهج يؤكد على ضرورة التحقق البشري الدائم (Human-in-the-loop) ومراجعة المصادر العلمية الموثوقة.')
