INSERT INTO public.questions (id, chunk_id, lesson_id, chapter_id, question_index, level, question, options, correct_index, is_true, correct_term, english_term, acceptable_answers, explanation)
VALUES ('ch1-l3-c1_q1', 'ch1-l3-c1', '1-3', 1, 1, 'mcq', 'الأنظمة التعليمية التي تعدل مستوى صعوبة التمارين ومسار الشرح بناءً على مستوى كل طالب تُسمى أنظمة:', '["التعلم الثابت","التعلم التكيفي (Adaptive Learning)","التعلم البطيء","التعليم الورقي"]'::jsonb, 1, NULL, NULL, NULL, '[]'::jsonb, 'التعلم التكيفي يخصص المسار وفق سرعة واستيعاب كل طالب.')
