VALUES ('ch1-l3-c1_q2_alt', 'ch1-l3-c1', '1-3', 1, 4, 'true_false', 'يساعد الذكاء الاصطناعي شركات الأدوية في تسريع اكتشاف وتصميم المركبات الكيميائية الجديدة.', '[]'::jsonb, NULL, TRUE, NULL, NULL, '[]'::jsonb, 'صحيح؛ يختصر سنوات طويلة من التجارب المعملية بالمحاكاة الذكية.')
