INSERT INTO public.questions (id, chunk_id, lesson_id, chapter_id, question_index, level, question, options, correct_index, is_true, correct_term, english_term, acceptable_answers, explanation)
VALUES ('ch1-l3-c1_q_best', 'ch1-l3-c1', '1-3', 1, 5, 'best_choice', 'جميع العبارات التالية تصف خصائص البيانات الضخمة (5Vs)، ولكن ما هو التوصيف الأصح والأشمل لقيمة البيانات الضخمة (Value) كأهم هذه الخصائص؟', '["سعر بيع أجهزة الخوادم الضخمة في أسواق التكنولوجيا العالمية.","عدد وحدات الجيجابايت التي يمكن تخزينها على وحدات التخزين السحابية.","القدرة على استخلاص رؤى استراتيجية ومعارف ذات جدوى تدعم اتخاذ قرارات دقيقة وتحسن الخدمات وتحل مشكلات معقدة للمؤسسات والمجتمع.","سرعة إرسال الرسائل عبر تطبيقات التراسل الفوري بين مستخدمي الهواتف."]'::jsonb, 2, NULL, NULL, NULL, '[]'::jsonb, 'الهدف الأسمى والنهائي لجمع مليارات البيانات بخصائصها (الحجم، السرعة، التنوع، المصداقية) هو استخراج القيمة (Value) المعرفية والعملية.')
