VALUES ('ch1-l3-c2_q1', 'ch1-l3-c2', '1-3', 1, 1, 'mcq', 'التقنية التي تراقب مؤشرات الماكينات وتتوقع الأعطال قبل وقوعها لتفادي توقف الإنتاج تُسمى:', '["الصيانة التنبؤية (Predictive Maintenance)","الصيانة الطارئة","البرمجة الخطية","التشفير المتماثل"]'::jsonb, 0, NULL, NULL, NULL, '[]'::jsonb, 'الصيانة التنبؤية تتوقع العطل وتصلحه في الوقت المثالي.')
