INSERT INTO public.questions (id, chunk_id, lesson_id, chapter_id, question_index, level, question, options, correct_index, is_true, correct_term, english_term, acceptable_answers, explanation)
VALUES ('ch1-l3-c2_q1_alt', 'ch1-l3-c2', '1-3', 1, 2, 'mcq', 'كيف تسهم نظم الذكاء الاصطناعي في تقليل الاختناقات المرورية في المدن الذكية؟', '["بضبط توقيت إشارات المرور آلياً بناءً على كثافة السيارات الحية","بإلغاء السيارات تماماً","بإطفاء إشارات المرور ليلاً","بإغلاق الطرق السريعة"]'::jsonb, 0, NULL, NULL, NULL, '[]'::jsonb, 'تحليل الكاميرات يضبط زمن الإشارة الخضراء حسب ضغط حركة السير.')
