VALUES ('ch1-l3-c2_q2', 'ch1-l3-c2', '1-3', 1, 3, 'true_false', 'تعتمد المدن الذكية على إنترنت الأشياء والذكاء الاصطناعي لترشيد استهلاك الطاقة والمياه وإدارة النفايات.', '[]'::jsonb, NULL, TRUE, NULL, NULL, '[]'::jsonb, 'صحيح؛ هذه هي المقومات الأساسية للبنية التحتية للمدن الذكية.')
