VALUES ('ch1-l3-c2_q2_alt', 'ch1-l3-c2', '1-3', 1, 4, 'true_false', 'الصيانة التنبؤية تزيد من تكاليف تعطل المصانع وتسبب خسائر مادية ضخمة.', '[]'::jsonb, NULL, FALSE, NULL, NULL, '[]'::jsonb, 'خطأ؛ على العكس، الصيانة التنبؤية توفر مليارات وتمنع التوقف المفاجئ للإنتاج.')
