INSERT INTO public.questions (id, chunk_id, lesson_id, chapter_id, question_index, level, question, options, correct_index, is_true, correct_term, english_term, acceptable_answers, explanation)
VALUES ('ch1-l3-c2_q_best', 'ch1-l3-c2', '1-3', 1, 5, 'best_choice', 'جميع البدائل التالية تعبر عن اعتبارات أخلاقية، ولكن أي منها يمثل التعريف الأصح والأشمل لـ ''الانحياز الخوارزمي'' (Algorithmic Bias)؟', '["تفضيل المبرمج استخدام لغة بايثون على لغة جافا عند بناء النماذج.","بطء استجابة الخوارزمية في معالجة العمليات الحسابية الكبيرة والمعقدة.","انعكاس الأحكام المسبقة والتحيزات البشرية غير العادلة في مخرجات النظام نتيجة تدريبه على بيانات غير متوازنة تاريخياً أو مجتمعياً.","اختيار الخوارزمية لأقصر مسار للوصول إلى الوجهة في تطبيقات الخرائط."]'::jsonb, 2, NULL, NULL, NULL, '[]'::jsonb, 'الانحياز الخوارزمي ينشأ عندما تعيد الخوارزمية إنتاج الظلم المجتمعي أو التحيز البشري الموجود في بيانات التدريب.')
ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
