INSERT INTO public.questions (id, chunk_id, lesson_id, chapter_id, question_index, level, question, options, correct_index, is_true, correct_term, english_term, acceptable_answers, explanation)
VALUES ('ch1-l3-c2_q_reinforce', 'ch1-l3-c2', '1-3', 1, 7, 'mcq', 'ما الركيزة الأساسية لـ ''حوكمة الذكاء الاصطناعي'' وفق الأطر التنظيمية المعاصرة المعتمدة في المنهج؟', '["منع استخدام برمجيات الذكاء الاصطناعي في التعليم والطب تماماً","وضع سياسات ومعايير قانونية وأخلاقية تضمن الشفافية والمساءلة والعدالة وحماية حقوق الأفراد والخصوصية","جعل جميع البرمجيات مفتوحة المصدر دون أي حقوق ملكية فكرية","فرض رسوم مالية على كل استعلام يجريه المستخدم للذكاء الاصطناعي"]'::jsonb, 1, NULL, NULL, NULL, '[]'::jsonb, 'حوكمة الذكاء الاصطناعي تضع الأطر التشريعية والأخلاقية (الشفافية، المساءلة، الأمان) لضمان توظيف التقنية لمصلحة الإنسان.')
