INSERT INTO public.questions (id, chunk_id, lesson_id, chapter_id, question_index, level, question, options, correct_index, is_true, correct_term, english_term, acceptable_answers, explanation)
VALUES ('ch1-l4-c1_q1', 'ch1-l4-c1', '1-4', 1, 1, 'mcq', 'ما هو السبب الجذري لحدوث التحيز الخوارزمي (Algorithmic Bias) في أنظمة الذكاء الاصطناعي؟', '["وجود تحيز ونقص تمثيل في بيانات التدريب التاريخية","سرعة الإنترنت العالية","ارتفاع درجة حرارة المعالج","استخدام لغات برمجة حديثة"]'::jsonb, 0, NULL, NULL, NULL, '[]'::jsonb, 'الخوارزمية تتعلم الأنماط من البيانات، فإذا كانت البيانات متحيزة كان القرار متحيزاً.')
