VALUES ('ch1-l4-c1_q2', 'ch1-l4-c1', '1-4', 1, 3, 'true_false', 'الذكاء الاصطناعي بطبيعته محايد وعادل 100% دائماً حتى لو كانت بيانات التدريب غير متوازنة.', '[]'::jsonb, NULL, FALSE, NULL, NULL, '[]'::jsonb, 'خطأ؛ الذكاء الاصطناعي يعكس تحيزات ونقائص بيانات التدريب.')
