INSERT INTO public.questions (id, chunk_id, lesson_id, chapter_id, question_index, level, question, options, correct_index, is_true, correct_term, english_term, acceptable_answers, explanation)
VALUES ('ch1-l4-c1_q_best', 'ch1-l4-c1', '1-4', 1, 5, 'best_choice', 'جميع الإجراءات التالية تسهم في خفض استهلاك الطاقة، ولكن ما هو المفهوم الأصح والأشمل لمصطلح ''الحوسبة الخضراء'' (Green Computing)؟', '["طلاء حواسيب وخزائن مراكز البيانات باللون الأخضر الصديق للبيئة.","إغلاق شاشة الحاسوب الشخصي في فترات الاستراحة القصيرة أثناء الدوام.","التصميم والتصنيع والاستخدام والتخلص المستدام من الأجهزة والأنظمة الحاسوبية ومراكز البيانات بأعلى كفاءة طاقة وأقل بصمة كربونية ممكنة على مدار دورة حياتها.","استبدال كابلات الإنترنت السلكية بشبكات الواي فاي اللاسلكية فقط."]'::jsonb, 2, NULL, NULL, NULL, '[]'::jsonb, 'الحوسبة الخضراء تشمل دورة حياة التقنية كاملة: التصميم المستدام، كفاءة الطاقة، واستخدام الطاقة المتجددة، والتدوير المسؤول.')
