ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, chunk_id, lesson_id, chapter_id, question_index, level, question, options, correct_index, is_true, correct_term, english_term, acceptable_answers, explanation)
VALUES ('ch1-l4-c1_q_reinforce', 'ch1-l4-c1', '1-4', 1, 7, 'mcq', 'في مراكز البيانات الحديثة، كلما اقتربت قيمة مؤشر كفاءة استخدام الطاقة (PUE) من الرقم ____، دل ذلك على كفاءة بيئية فائقة وتوجيه معظم الطاقة للحوسبة الفعلية:', '["1.0","5.0","10.0","0.0"]'::jsonb, 0, NULL, NULL, NULL, '[]'::jsonb, 'قيمة PUE المثالية نظرياً هي 1.0، حيث تذهب كل الطاقة الكهربائية مباشرة لتشغيل خوادم الحوسبة دون أي هدر في التبريد أو الإنارة.')
ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
