VALUES ('ch1-l4-c2_q1', 'ch1-l4-c2', '1-4', 1, 1, 'mcq', 'المصطلح الذي يصف صعوبة فهم وتفسير كيفية وصول النموذج العصبي لقرار معين يُعرف بـ:', '["معضلة الصندوق الأسود (Black Box Problem)","قانون مور","الحوسبة الطرفية","التشفير المتماثل"]'::jsonb, 0, NULL, NULL, NULL, '[]'::jsonb, 'الصندوق الأسود يعني غموض الخطوات الداخلية التي أدت للقرار النهائي.')
