INSERT INTO public.questions (id, chunk_id, lesson_id, chapter_id, question_index, level, question, options, correct_index, is_true, correct_term, english_term, acceptable_answers, explanation)
VALUES ('ch1-l4-c2_q1_alt', 'ch1-l4-c2', '1-4', 1, 2, 'mcq', 'عند وقوع خطأ قانوني أو ضرر بسبب نظام ذكاء اصطناعي، تقع المسؤولية القانونية وفق القوانين الحديثة على:', '["الشركات والمطورين البشريين المسؤولين عن إطلاق النظام","جهاز الكمبيوتر نفسه ويتم حبسه","الإنترنت","لا أحد يُسأل إطلاقاً"]'::jsonb, 0, NULL, NULL, NULL, '[]'::jsonb, 'المسؤولية القانونية تقع على عاتق الكيانات البشرية والمؤسسية المطورة.')
