INSERT INTO public.questions (id, chunk_id, lesson_id, chapter_id, question_index, level, question, options, correct_index, is_true, correct_term, english_term, acceptable_answers, explanation)
VALUES ('ch1-l4-c2_q2', 'ch1-l4-c2', '1-4', 1, 3, 'true_false', 'الذكاء الاصطناعي القابل للتفسير (Explainable AI) يهدف لجعل قرارات النماذج واضحة ومفهومة للأطباء والمستخدمين.', '[]'::jsonb, NULL, TRUE, NULL, NULL, '[]'::jsonb, 'صحيح؛ لحل معضلة الصندوق الأسود وبناء الثقة في التكنولوجيا.')
