INSERT INTO public.questions (id, chunk_id, lesson_id, chapter_id, question_index, level, question, options, correct_index, is_true, correct_term, english_term, acceptable_answers, explanation)
VALUES ('ch1-l4-c2_q2_alt', 'ch1-l4-c2', '1-4', 1, 4, 'true_false', 'يُسمح للأنظمة الذكية بجمع البيانات الطبية والشخصية للأفراد واستخدامها دون علمهم أو موافقتهم.', '[]'::jsonb, NULL, FALSE, NULL, NULL, '[]'::jsonb, 'خطأ؛ حماية الخصوصية والموافقة الصريحة شرط أخلاقي وقانوني دولي.')
ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, chunk_id, lesson_id, chapter_id, question_index, level, question, options, correct_index, is_true, correct_term, english_term, acceptable_answers, explanation)
VALUES ('ch1-l4-c2_q_best', 'ch1-l4-c2', '1-4', 1, 5, 'best_choice', 'جميع العبارات التالية صحيحة حول الأجهزة القديمة، ولكن ما هو المبدأ الأصح والأشمل لـ ''الاقتصاد الدائري'' في إدارة الأجهزة الإلكترونية مقارنة بالاقتصاد الخطي؟', '["تخزين الأجهزة الإلكترونية القديمة في مستودعات المدارس لسنوات طويلة.","إهداء الحواسب القديمة للأقارب والأصدقاء فقط دون فحص فني.","التحول من نموذج (اصنع، استهلك، ارمِ) إلى نموذج مستدام يعيد تدوير المكونات والمواد النادرة ويعيد تجديد الأجهزة لتقليل الهدر واستنزاف الموارد الطبيعية وحماية البيئة.","تصدير النفايات الإلكترونية إلى مكبات النفايات العامة خارج المدن الكبرى."]'::jsonb, 2, NULL, NULL, NULL, '[]'::jsonb, 'الاقتصاد الدائري يغلق دائرة الإنتاج والاستهلاك بإعادة التدوير واستخلاص المعادن الثمينة وتجديد الأجهزة بدلاً من طمرها.')
