INSERT INTO public.questions (id, chunk_id, lesson_id, chapter_id, question_index, level, question, options, correct_index, is_true, correct_term, english_term, acceptable_answers, explanation)
VALUES ('ch2-l1-c1_q1', 'ch2-l1-c1', '2-1', 2, 1, 'mcq', 'أي من ركائز مثلث CIA يضمن أن البيانات لم تتعرض للتعديل أو التلاعب غير المصرح به أثناء نقلها؟', '["السرية (Confidentiality)","السلامة والنزاهة (Integrity)","التوافر (Availability)","التخزين"]'::jsonb, 1, NULL, NULL, NULL, '[]'::jsonb, 'السلامة Integrity تضمن دقة وصحة البيانات وعدم العبث بها.')
ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, chunk_id, lesson_id, chapter_id, question_index, level, question, options, correct_index, is_true, correct_term, english_term, acceptable_answers, explanation)
VALUES ('ch2-l1-c1_q1_alt', 'ch2-l1-c1', '2-1', 2, 2, 'mcq', 'ضمان بقاء موقع البنك الإلكتروني يعمل دون توقف عند حاجة العملاء يعبر عن ركن:', '["التوافر (Availability)","السرية","التشفير","التخمين"]'::jsonb, 0, NULL, NULL, NULL, '[]'::jsonb, 'التوافر Availability يضمن جاهزية النظام والخدمات عند الطلب.')
