INSERT INTO public.questions (id, chunk_id, lesson_id, chapter_id, question_index, level, question, options, correct_index, is_true, correct_term, english_term, acceptable_answers, explanation)
VALUES ('ch2-l1-c1_q2', 'ch2-l1-c1', '2-1', 2, 3, 'true_false', 'السرية (Confidentiality) في الأمن السيبراني تعني إتاحة البيانات لجميع زوار الإنترنت دون قيود.', '[]'::jsonb, NULL, FALSE, NULL, NULL, '[]'::jsonb, 'خطأ؛ السرية تعني حصر الوصول فقط للأشخاص والجهات المصرح لها.')
