INSERT INTO public.questions (id, chunk_id, lesson_id, chapter_id, question_index, level, question, options, correct_index, is_true, correct_term, english_term, acceptable_answers, explanation)
VALUES ('ch2-l1-c1_q2_alt', 'ch2-l1-c1', '2-1', 2, 4, 'true_false', 'مثلث CIA يمثل الإطار المعياري الأساسي لتصميم وتقييم السياسات الأمنية للأنظمة الرقمية.', '[]'::jsonb, NULL, TRUE, NULL, NULL, '[]'::jsonb, 'صحيح؛ وهو المرجع الأول لكل خبراء الأمن السيبراني.')
ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, chunk_id, lesson_id, chapter_id, question_index, level, question, options, correct_index, is_true, correct_term, english_term, acceptable_answers, explanation)
VALUES ('ch2-l1-c1_q_best', 'ch2-l1-c1', '2-1', 2, 5, 'best_choice', 'جميع العبارات التالية صحيحة عن التشفير، ولكن أي منها يمثل المقارنة الأصح والأشمل بين التشفير المتماثل والتشفير غير المتماثل؟', '["التشفير المتماثل يستخدم للحروف فقط بينما غير المتماثل يستخدم للأرقام في البطاقات الائتمانية.","التشفير غير المتماثل لا يحتاج لأي مفاتيح رياضية سرية أثناء تبادل البيانات.","المتماثل يستخدم مفتاحاً سرياً واحداً مشتركاً للتشفير وفك التشفير ويمتاز بالسرعة الفائقة، بينما غير المتماثل يستخدم زوج مفاتيح (عام للتشفير وخاص لفك التشفير) ويحل معضلة تبادل المفاتيح بأمان عبر الشبكات المفتوحة.","التشفير المتماثل أكثر أماناً في كافة الظروف ولا يمكن اختراقه أبداً مقارنة بغير المتماثل."]'::jsonb, 2, NULL, NULL, NULL, '[]'::jsonb, 'الخيار (ج) هو المقارنة الأكاديمية الشاملة: يوضح طبيعة المفاتيح في كل نوع، الفارق في السرعة، وميزة غير المتماثل الحاسمة في حل معضلة توزيع المفاتيح بأمان.')
