INSERT INTO public.questions (id, chunk_id, lesson_id, chapter_id, question_index, level, question, options, correct_index, is_true, correct_term, english_term, acceptable_answers, explanation)
VALUES ('ch2-l1-c1_q_reinforce', 'ch2-l1-c1', '2-1', 2, 7, 'mcq', 'في نموذج أمن المعلومات الأساسي (CIA Triad)، يرمز حرف ''I'' إلى مبدأ:', '["الهوية (Identity)","النزاهة وسلامة البيانات (Integrity) من التعديل غير المصرح به","التفتيش والمراقبة (Inspection)","التفاعل والتواصل (Interaction)"]'::jsonb, 1, NULL, NULL, NULL, '[]'::jsonb, 'نموذج CIA يتألف من: السرية (Confidentiality)، النزاهة وسلامة البيانات (Integrity)، والتوافر (Availability).')
