INSERT INTO public.questions (id, chunk_id, lesson_id, chapter_id, question_index, level, question, options, correct_index, is_true, correct_term, english_term, acceptable_answers, explanation)
VALUES ('ch2-l1-c2_q1', 'ch2-l1-c2', '2-1', 2, 1, 'mcq', 'في نظام التشفير غير المتماثل (Asymmetric)، ما هو المفتاح المستخدم لفك تشفير الرسالة الواردة؟', '["المفتاح العام (Public Key)","المفتاح الخاص (Private Key)","كلمة المرور المشتركة","مفتاح التجزئة"]'::jsonb, 1, NULL, NULL, NULL, '[]'::jsonb, 'المفتاح الخاص السري يحتفظ به المستلم وحده لفك التشفير.')
ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, chunk_id, lesson_id, chapter_id, question_index, level, question, options, correct_index, is_true, correct_term, english_term, acceptable_answers, explanation)
VALUES ('ch2-l1-c2_q1_alt', 'ch2-l1-c2', '2-1', 2, 2, 'mcq', 'الميزة الأساسية للتشفير المتماثل (Symmetric) مقارنة بغير المتماثل هي:', '["السرعة العالية في معالجة كميات البيانات الكبيرة","استخدام ألف مفتاح","عدم الحاجة لأي مفتاح","العمل بدون كهرباء"]'::jsonb, 0, NULL, NULL, NULL, '[]'::jsonb, 'التشفير المتماثل سريع جداً حسابياً ومثالي للبيانات الكبيرة.')
ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, chunk_id, lesson_id, chapter_id, question_index, level, question, options, correct_index, is_true, correct_term, english_term, acceptable_answers, explanation)
VALUES ('ch2-l1-c2_q2', 'ch2-l1-c2', '2-1', 2, 3, 'true_false', 'في التشفير غير المتماثل، يجب الحفاظ على سرية المفتاح العام ومنع أي شخص من رؤيته.', '[]'::jsonb, NULL, FALSE, NULL, NULL, '[]'::jsonb, 'خطأ؛ المفتاح العام ينشر للجميع بحرية، بينما المفتاح الخاص هو الذي يجب حفظه سراً.')
