VALUES ('ch2-l1-c2_q2_alt', 'ch2-l1-c2', '2-1', 2, 4, 'true_false', 'بروتوكول HTTPS في المواقع الآمنة يعتمد على التشفير غير المتماثل للتحقق من هوية الموقع وتبادل المفاتيح بأمان.', '[]'::jsonb, NULL, TRUE, NULL, NULL, '[]'::jsonb, 'صحيح؛ هذا هو أساس الأمان في متصفحات الويب.')
ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, chunk_id, lesson_id, chapter_id, question_index, level, question, options, correct_index, is_true, correct_term, english_term, acceptable_answers, explanation)
VALUES ('ch2-l1-c2_q_best', 'ch2-l1-c2', '2-1', 2, 5, 'best_choice', 'جميع العبارات التالية تصف استخدامات المفاتيح، ولكن ما هو التوصيف الأصح والأشمل لكيفية عمل ''التوقيع الرقمي'' وتحقيقه لخاصية عدم الإنكار (Non-Repudiation)؟', '["قيام المرسل بكتابة اسمه بخط يده ومسحه ضوئياً ثم إرفاقه كصورة في نهاية الملف.","تشفير الرسالة بالكامل باستخدام كلمة مرور مشتركة يعرفها الطرفان فقط.","قيام المرسل بتوليد بصمة تجزئة (Hash) للرسالة وتشفيرها بمفتاحه الخاص، ليتسنى للمستقبل فكها بمفتاح المرسل العام وإثبات مصدرها وصحتها وسلامتها من أي تلاعب دون إمكانية إنكارها.","إرسال إشعار استلام رسمي من خلال مزود خدمة البريد الإلكتروني."]'::jsonb, 2, NULL, NULL, NULL, '[]'::jsonb, 'التوقيع الرقمي يعتمد على تجزئة الرسالة (Hashing) ثم تشفير البصمة بالمفتاح الخاص للمرسل، مما يثبت الهوية والنزاهة وعدم الإنكار قطيعاً.')
ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
