INSERT INTO public.questions (id, chunk_id, lesson_id, chapter_id, question_index, level, question, options, correct_index, is_true, correct_term, english_term, acceptable_answers, explanation)
VALUES ('ch2-l2-c1_q1', 'ch2-l2-c1', '2-2', 2, 1, 'mcq', 'نظام أو برنامج يراقب حركة مرور الشبكة ويسمح بها أو يمنعها استناداً لقواعد محددة مسبقاً هو:', '["جدار الحماية (Firewall)","محرك البحث Google","كابل الألياف الضوئية","المعالج المركزي CPU"]'::jsonb, 0, NULL, NULL, NULL, '[]'::jsonb, 'جدار الحماية هو خط الدفاع الأول الذي يطبق القواعد الأمنية.')
ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, chunk_id, lesson_id, chapter_id, question_index, level, question, options, correct_index, is_true, correct_term, english_term, acceptable_answers, explanation)
VALUES ('ch2-l2-c1_q1_alt', 'ch2-l2-c1', '2-2', 2, 2, 'mcq', 'السبب الأنسب لوضع خوادم الويب العامة في المنطقة المعزولة (DMZ) بدلاً من الشبكة الداخلية هو:', '["لمنع وصول الضرر للشبكة الداخلية وقواعد البيانات حتى لو تعرض خادم الويب لاختراق","لجعل موقع الويب بطيئاً جداً","لإلغاء الحاجة للإنترنت","لتوفير مساحة على القرص الصلب"]'::jsonb, 0, NULL, NULL, NULL, '[]'::jsonb, 'الـ DMZ تحاصر المهاجم وتمنعه من التسلل للشبكة الداخلية الحساسة.')
ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, chunk_id, lesson_id, chapter_id, question_index, level, question, options, correct_index, is_true, correct_term, english_term, acceptable_answers, explanation)
VALUES ('ch2-l2-c1_q2', 'ch2-l2-c1', '2-2', 2, 3, 'true_false', 'يُستخدم اتصال VPN لتشفير الاتصال وتقليل مخاطر التنصت وسرقة البيانات عبر شبكات Wi-Fi العامة.', '[]'::jsonb, NULL, TRUE, NULL, NULL, '[]'::jsonb, 'صحيح؛ VPN ينشئ نفقاً مشفراً يحمي كافة البيانات المنقولة.')
ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, chunk_id, lesson_id, chapter_id, question_index, level, question, options, correct_index, is_true, correct_term, english_term, acceptable_answers, explanation)
VALUES ('ch2-l2-c1_q2_alt', 'ch2-l2-c1', '2-2', 2, 4, 'true_false', 'توضع جميع خوادم المؤسسة الداخلية وقواعد بيانات الرواتب في المنطقة المعزولة DMZ المفتوحة للجمهور.', '[]'::jsonb, NULL, FALSE, NULL, NULL, '[]'::jsonb, 'خطأ؛ الـ DMZ مخصصة فقط للخوادم العامة المواجهة للإنترنت مثل خوادم الويب.')
ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, chunk_id, lesson_id, chapter_id, question_index, level, question, options, correct_index, is_true, correct_term, english_term, acceptable_answers, explanation)
VALUES ('ch2-l2-c1_q_best', 'ch2-l2-c1', '2-2', 2, 5, 'best_choice', 'جميع الخيارات التالية تمثل أدواراً أمنية، ولكن ما هو الغرض الأصح والأشمل لعزل الخوادم العامة (مثل خادم الويب) داخل المنطقة منزوعة السلاح (DMZ)؟', '["زيادة سرعة استجابة خادم الويب للزوار القادمين من الشبكة الخارجية.","منع موظفي الشركة من تصفح منصات الفيديو والتواصل الاجتماعي أثناء ساعات الدوام.","وضع الخوادم المتاحة للجمهور في شبكة فرعية وسيطة معزولة بحيث إذا تعرضت للاختراق من الإنترنت لا يتمكن المهاجم من النفاذ المباشر إلى الشبكة الداخلية الحساسة وقواعد بيانات الشركة.","تقليل استهلاك الطاقة الكهربائية لأجهزة الراوتر والجدران النارية."]'::jsonb, 2, NULL, NULL, NULL, '[]'::jsonb, 'الهدف الاستراتيجي للـ DMZ هو توفير حاجز أمني وسيط يعزل الخوادم المعرضة للإنترنت عن الشبكة الداخلية الحساسة (Internal Intranet).')
ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, chunk_id, lesson_id, chapter_id, question_index, level, question, options, correct_index, is_true, correct_term, english_term, acceptable_answers, explanation)
VALUES ('ch2-l2-c1_q3', 'ch2-l2-c1', '2-2', 2, 6, 'timed_fill', NULL, '["DMZ","CPU","RAM","URL"]'::jsonb, NULL, NULL, NULL, NULL, '[]'::jsonb, 'المنطقة المعزولة DMZ تحمي البنية التحتية الداخلية.')
ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, chunk_id, lesson_id, chapter_id, question_index, level, question, options, correct_index, is_true, correct_term, english_term, acceptable_answers, explanation)
VALUES ('ch2-l2-c1_q_reinforce', 'ch2-l2-c1', '2-2', 2, 7, 'mcq', 'يفحص جدار الحماية ذو الحالة (Stateful Inspection Firewall) حزم البيانات من خلال:', '["فحص حجم الملفات المرفقة فقط","تتبع حالة الاتصال النشطة وسياق جلسة العمل ومقارنتها بقواعد الحماية المحددة بدلاً من فحص الحزمة منفردة","قراءة محتوى النصوص والبريد الإلكتروني كلمة بكلمة يدوياً","إغلاق كافة المنافذ في عطلات نهاية الأسبوع تلقائياً"]'::jsonb, 1, NULL, NULL, NULL, '[]'::jsonb, 'جدار الحماية ذو الحالة يحتفظ بجدول حالة الاتصالات النشطة، مما يمنع الحزم الخبيثة الموجهة عشوائياً بدون طلب مسبق.')
ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, chunk_id, lesson_id, chapter_id, question_index, level, question, options, correct_index, is_true, correct_term, english_term, acceptable_answers, explanation)
VALUES ('ch2-l2-c1_q3_alt', 'ch2-l2-c1', '2-2', 2, 8, 'timed_fill', NULL, '["افتراضية","عشوائية","بطيئة","مكشوفة"]'::jsonb, NULL, NULL, NULL, NULL, '[]'::jsonb, 'الشبكة الافتراضية الخاصة VPN تؤمن الاتصال البعيد.')
ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, chunk_id, lesson_id, chapter_id, question_index, level, question, options, correct_index, is_true, correct_term, english_term, acceptable_answers, explanation)
VALUES ('ch2-l2-c2_q1', 'ch2-l2-c2', '2-2', 2, 1, 'mcq', 'الاستراتيجية الأمنية التي تطبق طبقات حماية متتالية لضمان أنه إذا فشلت طبقة تصد الطبقات التالية المهاجم تُسمى:', '["الدفاع في العمق (Defense in Depth)","القرصنة الأخلاقية","قانون مور","الاتصال أحادي الاتجاه"]'::jsonb, 0, NULL, NULL, NULL, '[]'::jsonb, 'الدفاع في العمق يمنع سقوط النظام بالكامل عند اختراق طبقة واحدة.')
ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, chunk_id, lesson_id, chapter_id, question_index, level, question, options, correct_index, is_true, correct_term, english_term, acceptable_answers, explanation)
VALUES ('ch2-l2-c2_q1_alt', 'ch2-l2-c2', '2-2', 2, 2, 'mcq', 'ما هو المبدأ الأساسي الذي يرتكز عليه نهج انعدام الثقة (Zero Trust)؟', '["عدم منح الثقة تلقائياً لأي مستخدم أو جهاز والتحقق المستمر من كل عملية وصول","الثقة المطلقة في كل موظف داخل مقر المؤسسة","إلغاء كلمات المرور تماماً","إيقاف جميع خوادم المؤسسة"]'::jsonb, 0, NULL, NULL, NULL, '[]'::jsonb, 'Zero Trust تعني: Never Trust, Always Verify.')
ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, chunk_id, lesson_id, chapter_id, question_index, level, question, options, correct_index, is_true, correct_term, english_term, acceptable_answers, explanation)
VALUES ('ch2-l2-c2_q2', 'ch2-l2-c2', '2-2', 2, 3, 'true_false', 'الاعتماد على جدار حماية واحد فقط يُعد كافياً تماماً لحماية كافة موارد المؤسسة من الاختراق.', '[]'::jsonb, NULL, FALSE, NULL, NULL, '[]'::jsonb, 'خطأ؛ كتاب ص 41: لا تكفي وسيلة حماية واحدة أبداً ويجب تطبيق الدفاع في العمق.')
ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, chunk_id, lesson_id, chapter_id, question_index, level, question, options, correct_index, is_true, correct_term, english_term, acceptable_answers, explanation)
VALUES ('ch2-l2-c2_q2_alt', 'ch2-l2-c2', '2-2', 2, 4, 'true_false', 'أدى انتشار الحوسبة السحابية والعمل عن بُعد إلى جعل حماية المحيط الأمني التقليدي وحده غير كافية.', '[]'::jsonb, NULL, TRUE, NULL, NULL, '[]'::jsonb, 'صحيح؛ ولذلك ظهر نهج انعدام الثقة Zero Trust للتحقق من هوية كل جهاز ومستخدم.')
ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, chunk_id, lesson_id, chapter_id, question_index, level, question, options, correct_index, is_true, correct_term, english_term, acceptable_answers, explanation)
VALUES ('ch2-l2-c2_q_best', 'ch2-l2-c2', '2-2', 2, 5, 'best_choice', 'جميع العبارات التالية صحيحة حول أدوات حماية الشبكات، ولكن ما هو الفارق الجوهري الأصح والأشمل بين نظام IDS ونظام IPS في الدفاع السيبراني؟', '["نظام IDS يعمل على الحواسيب المحمولة بينما نظام IPS يعمل على الهواتف الذكية فقط.","نظام IDS برنامج مجاني مفتوح المصدر بينما نظام IPS يتطلب اشتراكاً شهرياً دائماً.","نظام IDS يكتفي برصد حركة المرور وتحليلها وإرسال تنبيهات للمسؤول عند اكتشاف هجوم دون إيقافه (Passive Monitoring)، بينما نظام IPS يتصل مباشرة في مسار الشبكة (In-line) ويتدخل فورياً لحجب وحظر حركة المرور الخبيثة وإيقاف الهجوم (Active Prevention).","نظام IDS مخصص لرسائل البريد الإلكتروني بينما IPS مخصص للمواقع الحكومية فقط."]'::jsonb, 2, NULL, NULL, NULL, '[]'::jsonb, 'الفارق الجوهري هو أن IDS نظام مراقبة سلبي ينبه فقط (Detection)، بينما IPS نظام حماية نشط مدمج يتدخل لمنع الهجوم وإغلاق المنفذ (Prevention).')
ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, chunk_id, lesson_id, chapter_id, question_index, level, question, options, correct_index, is_true, correct_term, english_term, acceptable_answers, explanation)
VALUES ('ch2-l2-c2_q3', 'ch2-l2-c2', '2-2', 2, 6, 'timed_fill', NULL, '["عمق","سطح","فراغ","هواء"]'::jsonb, NULL, NULL, NULL, NULL, '[]'::jsonb, 'الدفاع في العمق يوفر حماية متكاملة ومستويات أمان متعددة.')
ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, chunk_id, lesson_id, chapter_id, question_index, level, question, options, correct_index, is_true, correct_term, english_term, acceptable_answers, explanation)
VALUES ('ch2-l2-c2_q_reinforce', 'ch2-l2-c2', '2-2', 2, 7, 'mcq', 'في تقنيات اكتشاف الهجمات، يتميز الكشف المعتمد على الشذوذ (Anomaly-based Detection) بقدرته الفريدة على:', '["مطابقة التواقيع القديمة المحفوظة في ملف التحديثات فقط","اكتشاف الهجمات والتهديدات الجديدة غير المعروفة مسبقاً (Zero-day) عبر رصد أي انحراف عن السلوك الطبيعي المعتاد للشبكة","تسريع اتصال الإنترنت في أوقات الذروة","فحص كلمات المرور المكتوبة بخط اليد"]'::jsonb, 1, NULL, NULL, NULL, '[]'::jsonb, 'الكشف المعتمد على الشذوذ يبني نموذجاً للسلوك الطبيعي للشبكة، مما يجعله قادراً على كشف ثغرات اليوم الصفري (Zero-day) التي ليس لها توقيع سابق.')
ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, chunk_id, lesson_id, chapter_id, question_index, level, question, options, correct_index, is_true, correct_term, english_term, acceptable_answers, explanation)
VALUES ('ch2-l2-c2_q3_alt', 'ch2-l2-c2', '2-2', 2, 8, 'timed_fill', NULL, '["انعدام","زيادة","تأكيد","توسيع"]'::jsonb, NULL, NULL, NULL, NULL, '[]'::jsonb, 'نهج انعدام الثقة Zero Trust هو المعيار الأمني العالمي الحديث.')
ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, chunk_id, lesson_id, chapter_id, question_index, level, question, options, correct_index, is_true, correct_term, english_term, acceptable_answers, explanation)
VALUES ('ch2-l3-c1_q1', 'ch2-l3-c1', '2-3', 2, 1, 'mcq', 'الحدث الذي يؤثر في سرية المعلومات أو سلامتها أو توافرها أو يخالف سياسة أمنية يُسمى:', '["الحادث الأمني (Security Incident)","قانون مور","التصميم المتجاوب","الاستعلام الخطي"]'::jsonb, 0, NULL, NULL, NULL, '[]'::jsonb, 'الحادث الأمني هو أي انتهاك لأحد أركان ثالوث أمن المعلومات.')
ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, chunk_id, lesson_id, chapter_id, question_index, level, question, options, correct_index, is_true, correct_term, english_term, acceptable_answers, explanation)
VALUES ('ch2-l3-c1_q1_alt', 'ch2-l3-c1', '2-3', 2, 2, 'mcq', 'ما هي المرحلة المنهجية التي تستهدف عزل الجزء المتأثر (كفصل الجهاز عن الشبكة) للحد من انتشار الضرر؟', '["الاحتواء (Containment)","الاستئصال (Eradication)","التحضير","تشفير كلمات المرور"]'::jsonb, 0, NULL, NULL, NULL, '[]'::jsonb, 'الاحتواء يعني حصر وعزل الإصابة فوراً لمنع انتقالها.')
ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, chunk_id, lesson_id, chapter_id, question_index, level, question, options, correct_index, is_true, correct_term, english_term, acceptable_answers, explanation)
VALUES ('ch2-l3-c1_q2', 'ch2-l3-c1', '2-3', 2, 3, 'true_false', 'يجب أن تأتي مرحلة الاستعادة والتشغيل قبل مرحلة استئصال التهديد وإزالة البرمجيات الخبيثة.', '[]'::jsonb, NULL, FALSE, NULL, NULL, '[]'::jsonb, 'خطأ؛ كتاب ص 47: البدء بالاستعادة قبل الاستئصال يجعل البرمجية تصيب الأنظمة والنسخ المستعادة فوراً.')
ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, chunk_id, lesson_id, chapter_id, question_index, level, question, options, correct_index, is_true, correct_term, english_term, acceptable_answers, explanation)
VALUES ('ch2-l3-c1_q2_alt', 'ch2-l3-c1', '2-3', 2, 4, 'true_false', 'مرحلة الدروس المستفادة تساعد على تحسين الضوابط الأمنية وسد الثغرات لمنع تكرار الحوادث المشابهة.', '[]'::jsonb, NULL, TRUE, NULL, NULL, '[]'::jsonb, 'صحيح؛ التوثيق والمراجعة هما أساس التحسين المستمر لأمن المؤسسة.')
ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, chunk_id, lesson_id, chapter_id, question_index, level, question, options, correct_index, is_true, correct_term, english_term, acceptable_answers, explanation)
VALUES ('ch2-l3-c1_q_best', 'ch2-l3-c1', '2-3', 2, 5, 'best_choice', 'جميع الإجراءات التالية جزء من التعامل مع الهجمات السيبرانية، ولكن ما هو التوصيف والترتيب الأصح والأشمل للمراحل الست المعتمدة عالمياً في دورة الاستجابة للحوادث السيبرانية؟', '["الإيقاف، الإبلاغ، فرمتة الأجهزة، شراء حواسيب جديدة، الإعلان في الصحف، المراقبة.","التحقيق الجنائي، رفع الدعاوى القضائية، استبدال كلمات المرور، إعادة التشغيل، المراقبة.","الاستعداد والتأهب (Preparation)، ثم الاكتشاف والتحليل (Detection & Analysis)، ثم الاحتواء (Containment)، ثم الاستئصال وإزالة التهديد (Eradication)، ثم التعافي واستعادة العمليات (Recovery)، وأخيراً استخلاص الدروس المستفادة (Lessons Learned).","فصل كابل الإنترنت والكهرباء والانتظار حتى انتهاء الهجوم تلقائياً."]'::jsonb, 2, NULL, NULL, NULL, '[]'::jsonb, 'الخيار (ج) يمثل الإطار الأكاديمي القياسي (NIST / SANS) لإدارة الحوادث السيبرانية المعتمد في كتاب الوزارة.')
ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, chunk_id, lesson_id, chapter_id, question_index, level, question, options, correct_index, is_true, correct_term, english_term, acceptable_answers, explanation)
VALUES ('ch2-l3-c1_q3', 'ch2-l3-c1', '2-3', 2, 6, 'timed_fill', NULL, '["احتواء","استئصال","استعادة","إهمال"]'::jsonb, NULL, NULL, NULL, NULL, '[]'::jsonb, 'الاحتواء يمنع تمدد الكارثة السيبرانية.')
ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, chunk_id, lesson_id, chapter_id, question_index, level, question, options, correct_index, is_true, correct_term, english_term, acceptable_answers, explanation)
VALUES ('ch2-l3-c1_q_reinforce', 'ch2-l3-c1', '2-3', 2, 7, 'timed_fill', NULL, '["الاحتواء","التعافي","الاستعداد","الاستئصال"]'::jsonb, NULL, NULL, NULL, NULL, '[]'::jsonb, 'الاحتواء (Containment) هو الإجراء العاجل لمنع تفاقم الضرر وانتشار البرمجية الخبيثة.')
ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
