VALUES ('ch2-l3-c1_q3_alt', 'ch2-l3-c1', '2-3', 2, 8, 'timed_fill', NULL, '["استئصال","احتواء","تحضير","تكرار"]'::jsonb, NULL, NULL, NULL, NULL, '[]'::jsonb, 'الاستئصال هو التطهير الجذري لمسببات الاختراق.')
