INSERT INTO public.questions (id, chunk_id, lesson_id, chapter_id, question_index, level, question, options, correct_index, is_true, correct_term, english_term, acceptable_answers, explanation)
VALUES ('ch2-l3-c2_q1', 'ch2-l3-c2', '2-3', 2, 1, 'mcq', 'المعادلة المنهجية لحساب درجة الخطر في إدارة المخاطر السيبرانية هي:', '["درجة الخطر = حجم التأثير × احتمالية الحدوث","درجة الخطر = عدد الحواسيب + سرعة الإنترنت","درجة الخطر = سعر جدار الحماية ÷ 2","درجة الخطر = مساحة القرص الصلب"]'::jsonb, 0, NULL, NULL, NULL, '[]'::jsonb, 'درجة الخطر Risk Score = Impact × Likelihood.')
ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, chunk_id, lesson_id, chapter_id, question_index, level, question, options, correct_index, is_true, correct_term, english_term, acceptable_answers, explanation)
VALUES ('ch2-l3-c2_q1_alt', 'ch2-l3-c2', '2-3', 2, 2, 'mcq', 'إذا كان التهديد (أ) تأثيره مرتفع (3) واحتماليته متوسطة (2)، والتهديد (ب) تأثيره منخفض (1) واحتماليته مرتفعة (3)، فأي التهديدين يعالج أولاً؟', '["التهديد (أ) لأن درجة خطره 6 وهي أعلى من التهديد (ب) الذي درجته 3","التهديد (ب) دائماً","إهمال الاثنين","الانتظار حتى تحدث المشكلة"]'::jsonb, 0, NULL, NULL, NULL, '[]'::jsonb, 'التهديد A ناتجه 3×2=6 وهو أولوية حرجة مقارنة بـ B ناتجه 1×3=3.')
ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, chunk_id, lesson_id, chapter_id, question_index, level, question, options, correct_index, is_true, correct_term, english_term, acceptable_answers, explanation)
VALUES ('ch2-l3-c2_q2', 'ch2-l3-c2', '2-3', 2, 3, 'true_false', 'عند التعرض لهجوم برمجية الفدية Ransomware، فإن الإجراء المنهجي الصحيح هو دفع الفدية المالية فوراً للمهاجمين.', '[]'::jsonb, NULL, FALSE, NULL, NULL, '[]'::jsonb, 'خطأ؛ كتاب ص 47: لا تُدفع الفدية، بل تُعزل الأنظمة وتستعاد البيانات من النسخ الاحتياطية السليمة.')
ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, chunk_id, lesson_id, chapter_id, question_index, level, question, options, correct_index, is_true, correct_term, english_term, acceptable_answers, explanation)
VALUES ('ch2-l3-c2_q2_alt', 'ch2-l3-c2', '2-3', 2, 4, 'true_false', 'تقتصر مرحلة التعافي على مجرد إعادة تشغيل الأجهزة المصابة دون الحاجة لفحص النسخ الاحتياطية.', '[]'::jsonb, NULL, FALSE, NULL, NULL, '[]'::jsonb, 'خطأ؛ تشمل استعادة البيانات من النسخ النظيفة واختبار استقرار وأمان النظام قبل إعادته للعمل.')
ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, chunk_id, lesson_id, chapter_id, question_index, level, question, options, correct_index, is_true, correct_term, english_term, acceptable_answers, explanation)
VALUES ('ch2-l3-c2_q_best', 'ch2-l3-c2', '2-3', 2, 5, 'best_choice', 'جميع العبارات التالية تصف مفاهيم أمنية، ولكن أي منها يمثل العلاقة الأصح والأشمل رياضياً ومفاهيمياً بين الخطر (Risk) والتهديد (Threat) والثغرة (Vulnerability)؟', '["الخطر والتهديد والثغرة هي مسميات مترادفة تماماً لشيء واحد في الأمن السيبراني.","الثغرة تحدث بسبب الموظفين فقط بينما التهديد يأتي من البرمجيات الخارجية دائماً.","الخطر هو نتاج احتمالية استغلال تهديد خارجي (Threat) لثغرة أمنية داخلية قائمة (Vulnerability)، مضروباً في حجم الأثر السلبي أو الضرر المتوقع على أصول المنشأة (Risk = Threat × Vulnerability × Impact).","التهديد هو التكلفة المالية للبرامج المضادة بينما الخطر هو وقت تعطل الشبكة."]'::jsonb, 2, NULL, NULL, NULL, '[]'::jsonb, 'الخيار (ج) هو المعادلة العلمية الأصح: لا يوجد خطر حقيقي بدون وجود ثغرة قابلة للاستغلال من قِبل تهديد ملموس مقترناً بحجم الأثر الناتج.')
ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, chunk_id, lesson_id, chapter_id, question_index, level, question, options, correct_index, is_true, correct_term, english_term, acceptable_answers, explanation)
VALUES ('ch2-l3-c2_q3', 'ch2-l3-c2', '2-3', 2, 6, 'timed_fill', NULL, '["فدية","حماية","تشغيل","تسريع"]'::jsonb, NULL, NULL, NULL, NULL, '[]'::jsonb, 'برمجية الفدية Ransomware تشفر الملفات لاحتجازها.')
ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, chunk_id, lesson_id, chapter_id, question_index, level, question, options, correct_index, is_true, correct_term, english_term, acceptable_answers, explanation)
VALUES ('ch2-l3-c2_q_reinforce', 'ch2-l3-c2', '2-3', 2, 7, 'mcq', 'يسمى النشاط الأمني المصرح به رسمياً والذي يقوم فيه خبراء بمحاكاة هجمات حقيقية لاكتشاف الثغرات وتصحيحها قبل استغلالها من المهاجمين بـ:', '["الهندسة الاجتماعية الضارة","اختبار الاختراق الأخلاقي (Ethical Penetration Testing)","تشفير قواعد البيانات العشوائي","التثبيت التلقائي للبرمجيات"]'::jsonb, 1, NULL, NULL, NULL, '[]'::jsonb, 'اختبار الاختراق الأخلاقي يهدف لاكتشاف نقاط الضعف العملية عبر هجوم محاكى ومصرح به لحماية الأنظمة استباقياً.')
