INSERT INTO public.questions (id, chunk_id, lesson_id, chapter_id, question_index, level, question, options, correct_index, is_true, correct_term, english_term, acceptable_answers, explanation)
VALUES ('ch3-l1-c1_q1', 'ch3-l1-c1', '3-1', 3, 1, 'mcq', 'أي من طبقات الويب الثلاث مسؤولة عن تخزين واسترجاع معلومات المستخدمين والمنتجات بشكل دائم؟', '["طبقة العرض (Presentation)","طبقة منطق العمل (Logic Tier)","طبقة البيانات (Data Tier)","لوحة المفاتيح"]'::jsonb, 2, NULL, NULL, NULL, '[]'::jsonb, 'طبقة البيانات Data Tier تحتوي على خوادم قواعد البيانات المسؤولة عن التخزين والاسترجاع.')
ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, chunk_id, lesson_id, chapter_id, question_index, level, question, options, correct_index, is_true, correct_term, english_term, acceptable_answers, explanation)
VALUES ('ch3-l1-c1_q1_alt', 'ch3-l1-c1', '3-1', 3, 2, 'mcq', 'الطبقة التي تتفاعل مباشرة مع المستخدم وتعمل داخل متصفح الإنترنت هي:', '["طبقة العرض (Presentation Tier)","طبقة البيانات","القرص الصلب","كابل الفايبر"]'::jsonb, 0, NULL, NULL, NULL, '[]'::jsonb, 'طبقة العرض هي الواجهة الرسومية التي يراها ويتفاعل معها العميل.')
ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, chunk_id, lesson_id, chapter_id, question_index, level, question, options, correct_index, is_true, correct_term, english_term, acceptable_answers, explanation)
VALUES ('ch3-l1-c1_q2', 'ch3-l1-c1', '3-1', 3, 3, 'true_false', 'بنية الطبقات الثلاث تفصل منطق الأعمال والواجهة وقواعد البيانات لتسهيل صيانتها وأمانها.', '[]'::jsonb, NULL, TRUE, NULL, NULL, '[]'::jsonb, 'صحيح؛ هذا الفصل يمنع وصول المتصفح لقاعدة البيانات مباشرة لحمايتها.')
ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, chunk_id, lesson_id, chapter_id, question_index, level, question, options, correct_index, is_true, correct_term, english_term, acceptable_answers, explanation)
VALUES ('ch3-l1-c1_q2_alt', 'ch3-l1-c1', '3-1', 3, 4, 'true_false', 'في نموذج العميل والخادم، يكون العميل هو المسؤول عن تخزين كل قواعد البيانات المركزية للموقع.', '[]'::jsonb, NULL, FALSE, NULL, NULL, '[]'::jsonb, 'خطأ؛ الخادم Server وقواعد البيانات هي التي تخزن البيانات المركزية.')
ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, chunk_id, lesson_id, chapter_id, question_index, level, question, options, correct_index, is_true, correct_term, english_term, acceptable_answers, explanation)
VALUES ('ch3-l1-c1_q_best', 'ch3-l1-c1', '3-1', 3, 5, 'best_choice', 'جميع العبارات التالية صحيحة عن مكونات مواقع الويب، ولكن ما هو التوصيف الأصح والأشمل للبنية ثلاثية الطبقات (3-Tier Architecture) ومسؤولية كل طبقة؟', '["طبقة للماوس، وطبقة للشاشة، وطبقة للوحة المفاتيح.","طبقة للألوان والتصميم، وطبقة للخطوط، وطبقة لملفات الصور التوضيحية.","طبقة العرض Presentation (واجهة العميل بالمتصفح)، وطبقة منطق التطبيق Application Logic (معالجة الأوامر وقواعد العمل بالخادم)، وطبقة البيانات Data Tier (تخزين واسترجاع قواعد البيانات وتأمينها).","طبقة لأجهزة أندرويد، وطبقة لأجهزة أبل، وطبقة للحواسيب الشخصية."]'::jsonb, 2, NULL, NULL, NULL, '[]'::jsonb, 'البنية ثلاثية الطبقات هي المعيار الصناعي: فصل العرض (Frontend) عن المنطق والمعالجة (Backend) عن إدارة قواعد البيانات (Database).')
ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, chunk_id, lesson_id, chapter_id, question_index, level, question, options, correct_index, is_true, correct_term, english_term, acceptable_answers, explanation)
VALUES ('ch3-l1-c1_q3', 'ch3-l1-c1', '3-1', 3, 6, 'timed_fill', NULL, '["ثلاث","أربع","عشر","مزدوجة"]'::jsonb, NULL, NULL, NULL, NULL, '[]'::jsonb, 'بنية الطبقات الثلاث هي المعيار العالمي لهندسة مواقع الويب.')
ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, chunk_id, lesson_id, chapter_id, question_index, level, question, options, correct_index, is_true, correct_term, english_term, acceptable_answers, explanation)
VALUES ('ch3-l1-c1_q_reinforce', 'ch3-l1-c1', '3-1', 3, 7, 'mcq', 'ما الفائدة المعمارية الأهم لفصل طبقة منطق التطبيق عن طبقة قاعدة البيانات في بنية 3-Tier؟', '["تقليل حجم ملفات HTML فقط","تحسين الأمان وقابلية التوسع (Scalability) وتيسير صيانة وتحديث كل طبقة دون التأثير على الطبقات الأخرى","جعل الموقع يعمل بالكامل بدون اتصال بالإنترنت","الاستغناء عن كتابة كود التنسيق CSS نهائياً"]'::jsonb, 1, NULL, NULL, NULL, '[]'::jsonb, 'الفصل بين الطبقات يمنح مرونة عالية في الترقية وسرعة الصيانة وعزل بيانات العملاء الحساسة عن الوصول المباشر.')
ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, chunk_id, lesson_id, chapter_id, question_index, level, question, options, correct_index, is_true, correct_term, english_term, acceptable_answers, explanation)
VALUES ('ch3-l1-c1_q3_alt', 'ch3-l1-c1', '3-1', 3, 8, 'timed_fill', NULL, '["عميل","خادم","موزع","جدار"]'::jsonb, NULL, NULL, NULL, NULL, '[]'::jsonb, 'العميل Client هو الطالب، والخادم Server هو المستجيب.')
