INSERT INTO public.questions (id, chunk_id, lesson_id, chapter_id, question_index, level, question, options, correct_index, is_true, correct_term, english_term, acceptable_answers, explanation)
VALUES ('ch3-l1-c2_q1', 'ch3-l1-c2', '3-1', 3, 1, 'mcq', 'عند البحث عن منتج في متجر إلكتروني، أي جهة تكون مسؤولة فعلياً عن البحث في السجلات واسترجاع المنتجات المطابقة؟', '["قاعدة البيانات (Database)","شاشة المتصفح","لوحة المفاتيح","الماوس"]'::jsonb, 0, NULL, NULL, NULL, '[]'::jsonb, 'قاعدة البيانات هي المسؤولة عن البحث في سجلات البيانات واسترجاع المطابق.')
ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, chunk_id, lesson_id, chapter_id, question_index, level, question, options, correct_index, is_true, correct_term, english_term, acceptable_answers, explanation)
VALUES ('ch3-l1-c2_q1_alt', 'ch3-l1-c2', '3-1', 3, 2, 'mcq', 'لماذا لا تستطيع الواجهة الأمامية حفظ سجلات المستخدمين الدائمة أو معالجة المدفوعات البنكية بمفردها؟', '["لأنها تعمل على جهاز المستخدم ولا تملك تخزيناً مشتركاً ولا صلاحيات سرية مصرفية","لأن شاشة الحاسوب صغيرة جداً","لأن الإنترنت مجاني","لأن المتصفح لا يحتوي على ألوان"]'::jsonb, 0, NULL, NULL, NULL, '[]'::jsonb, 'الأمامية تعمل محلياً على جهاز العميل، ولا تملك صلاحيات حفظ مركزية أو أسرار مصرفية.')
ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, chunk_id, lesson_id, chapter_id, question_index, level, question, options, correct_index, is_true, correct_term, english_term, acceptable_answers, explanation)
VALUES ('ch3-l1-c2_q2', 'ch3-l1-c2', '3-1', 3, 3, 'true_false', 'إذا انقطع الاتصال بقاعدة البيانات مؤقتاً، يستمر خادم الويب في تسجيل الطلاب وحفظ كلمات المرور دون أي خلل.', '[]'::jsonb, NULL, FALSE, NULL, NULL, '[]'::jsonb, 'خطأ؛ كتاب ص 54: يعجز الخادم عن مطابقة أو حفظ البيانات ويعيد رمز خطأ للمستخدم.')
ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, chunk_id, lesson_id, chapter_id, question_index, level, question, options, correct_index, is_true, correct_term, english_term, acceptable_answers, explanation)
VALUES ('ch3-l1-c2_q2_alt', 'ch3-l1-c2', '3-1', 3, 4, 'true_false', 'في سيناريو حجز مقعد قطار، تتولى الواجهة الخلفية فحص توفر المقعد وصلاحية بطاقة الدفع قبل التسجيل النهائي.', '[]'::jsonb, NULL, TRUE, NULL, NULL, '[]'::jsonb, 'صحيح؛ منطق الفحص والمعالجة مسؤولية الواجهة الخلفية.')
ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, chunk_id, lesson_id, chapter_id, question_index, level, question, options, correct_index, is_true, correct_term, english_term, acceptable_answers, explanation)
VALUES ('ch3-l1-c2_q_best', 'ch3-l1-c2', '3-1', 3, 5, 'best_choice', 'جميع العبارات التالية تصف تصفح المواقع، ولكن ما هو الفارق الأصح والأشمل بين بروتوكول HTTP وبروتوكول HTTPS في نقل بيانات الويب؟', '["بروتوكول HTTPS مخصص لعرض مقاطع الفيديو عالية الدقة فقط بينما HTTP للنصوص البسيطة.","بروتوكول HTTP يعمل على شبكات الجوال بينما HTTPS يعمل على شبكات الألياف الضوئية فقط.","بروتوكول HTTP ينقل البيانات كنصوص صريحة قابلة للتنصت والاعتراض، بينما HTTPS يدمج بروتوكول التشفير الآمن (TLS/SSL) لضمان سرية البيانات وسلامتها والتحقق من هوية الموقع الرقمية.","بروتوكول HTTPS يجعل سرعة تحميل صفحات الإنترنت أضعاف بروتوكول HTTP دائماً."]'::jsonb, 2, NULL, NULL, NULL, '[]'::jsonb, 'الخيار (ج) هو الفارق الأمني الجوهري: إضافة التشفير عبر TLS/SSL في HTTPS يمنع هجمات الوسيط (Man-in-the-Middle) ويحمي كلمات المرور والبيانات.')
ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
