VALUES ('ch3-l2-c1_q1', 'ch3-l2-c1', '3-2', 3, 1, 'mcq', 'أسلوب طلب HTTP المناسب لإرسال بيانات استمارة تسجيل طالب جديد أو كلمة المرور بأمان هو:', '["POST","GET","PRINT","DELETE"]'::jsonb, 0, NULL, NULL, NULL, '[]'::jsonb, 'POST يرسل البيانات محمية في جسم الطلب لمعالجتها.')
