INSERT INTO public.questions (id, chunk_id, lesson_id, chapter_id, question_index, level, question, options, correct_index, is_true, correct_term, english_term, acceptable_answers, explanation)
VALUES ('ch3-l2-c1_q1_alt', 'ch3-l2-c1', '3-2', 3, 2, 'mcq', 'البروتوكول الذي يشفر اتصالات الويب بنفق TLS ويحمي كلمات المرور وبيانات البطاقات من التنصت هو:', '["HTTPS","HTTP العادي","FTP","DNS"]'::jsonb, 0, NULL, NULL, NULL, '[]'::jsonb, 'HTTPS هو بروتوكول الويب الآمن المشفر.')
