INSERT INTO public.questions (id, chunk_id, lesson_id, chapter_id, question_index, level, question, options, correct_index, is_true, correct_term, english_term, acceptable_answers, explanation)
VALUES ('ch3-l2-c1_q2', 'ch3-l2-c1', '3-2', 3, 3, 'true_false', 'أسلوب GET مخصص لإرسال ومعالجة البيانات الجديدة وتعديل قاعدة البيانات على الخادم.', '[]'::jsonb, NULL, FALSE, NULL, NULL, '[]'::jsonb, 'خطأ؛ كتاب ص 58: GET لجلب وقراءة الموارد فقط دون تعديل، بينما POST هو المخصص للإرسال.')
