INSERT INTO public.questions (id, chunk_id, lesson_id, chapter_id, question_index, level, question, options, correct_index, is_true, correct_term, english_term, acceptable_answers, explanation)
VALUES ('ch3-l2-c1_q2_alt', 'ch3-l2-c1', '3-2', 3, 4, 'true_false', 'بروتوكول HTTP ينقل البيانات كنص صريح دون تشفير، مما يجعله غير آمن لنقل كلمات المرور والبيانات الحساسة.', '[]'::jsonb, NULL, TRUE, NULL, NULL, '[]'::jsonb, 'صحيح؛ ولذلك يجب استبداله بـ HTTPS في المواقع الحديثة.')
