INSERT INTO public.questions (id, chunk_id, lesson_id, chapter_id, question_index, level, question, options, correct_index, is_true, correct_term, english_term, acceptable_answers, explanation)
VALUES ('ch3-l2-c1_q_best', 'ch3-l2-c1', '3-2', 3, 5, 'best_choice', 'جميع البدائل التالية تصف وسوم لغة HTML، ولكن ما هو المبرر البرمجي الأصح والأشمل لاستخدام وسوم HTML5 الدلالية (مثل `<header>`, `<nav>`, `<article>`, `<main>`) بدلاً من مجرد استخدام `<div>` لكل شيء؟', '["وسوم HTML5 الدلالية تضيف تلقائياً ألواناً وظلالاً وتأثيرات حركية جميلة دون الحاجة لكود CSS.","وسوم `<div>` أصبحت ملغاة قانونياً ولا تعمل في المتصفحات الحديثة إطلاقاً.","تعزيز دلالة المعنى لبنية الصفحة مما يدعم فهرسة محركات البحث (SEO)، ويحسن وصول برمجيات ذوي الاحتياجات الخاصة (Accessibility)، ويسهل صيانة وفهم الشيفرة البرمجية للمطورين.","تقليل استهلاك الذاكرة العشوائية للحاسوب بمقدار النصف عند تصفح الصفحة."]'::jsonb, 2, NULL, NULL, NULL, '[]'::jsonb, 'الوسوم الدلالية (Semantic Tags) لا تمنح تنسيقاً مرئياً تلقائياً، ولكنها توضح للمتصفح ومحركات البحث وقارئات الشاشة المعنى الحقيقي لكل جزء من الصفحة.')
ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
