INSERT INTO public.questions (id, chunk_id, lesson_id, chapter_id, question_index, level, question, options, correct_index, is_true, correct_term, english_term, acceptable_answers, explanation)
VALUES ('ch3-l2-c1_q_reinforce', 'ch3-l2-c1', '3-2', 3, 7, 'mcq', 'الوسم المناسب دلالياً في لغة HTML5 لاحتواء روابط التنقل الرئيسية بين صفحات الموقع هو وسم:', '["`<aside>`","`<nav>`","`<section>`","`<footer>`"]'::jsonb, 1, NULL, NULL, NULL, '[]'::jsonb, 'وسم `<nav>` مخصص دلالياً لحاويات روابط التنقل الرئيسية (Navigation).')
