INSERT INTO public.questions (id, chunk_id, lesson_id, chapter_id, question_index, level, question, options, correct_index, is_true, correct_term, english_term, acceptable_answers, explanation)
VALUES ('ch3-l2-c2_q1', 'ch3-l2-c2', '3-2', 3, 1, 'mcq', 'رمز استجابة HTTP الذي يدل على أن الصفحة أو المورد المطلوب غير موجود على الخادم ويُعد خطأ من جانب العميل هو:', '["404 (Not Found)","200 (OK)","500 (Server Error)","100"]'::jsonb, 0, NULL, NULL, NULL, '[]'::jsonb, '404 يعني أن الرابط المطلوب غير موجود بالخادم.')
