INSERT INTO public.questions (id, chunk_id, lesson_id, chapter_id, question_index, level, question, options, correct_index, is_true, correct_term, english_term, acceptable_answers, explanation)
VALUES ('ch3-l2-c2_q1_alt', 'ch3-l2-c2', '3-2', 3, 2, 'mcq', 'صيغة البيانات النصية الخفيفة المعتمدة عالمياً لتبادل البيانات بين واجهات API والتطبيقات هي:', '["صيغة JSON","شريط الفيديو MP4","القرص المرن Floppy","الرسم النقطي BMP"]'::jsonb, 0, NULL, NULL, NULL, '[]'::jsonb, 'JSON هي الصيغة القياسية الخفيفة لتبادل البيانات.')
