VALUES ('ch3-l2-c2_q2', 'ch3-l2-c2', '3-2', 3, 3, 'true_false', 'رمز الحالة 200 يشير إلى حدوث خطأ داخلي فادح في خادم الويب أثناء المعالجة.', '[]'::jsonb, NULL, FALSE, NULL, NULL, '[]'::jsonb, 'خطأ؛ رمز 200 يعني نجاح معالجة الطلب تماماً (200 OK).')
