INSERT INTO public.questions (id, chunk_id, lesson_id, chapter_id, question_index, level, question, options, correct_index, is_true, correct_term, english_term, acceptable_answers, explanation)
VALUES ('ch3-l2-c2_q2_alt', 'ch3-l2-c2', '3-2', 3, 4, 'true_false', 'واجهات API تتيح لتطبيقات مختلفة تبادل البيانات والخدمات دون الحاجة لإعادة كتابة البرمجيات من الصفر.', '[]'::jsonb, NULL, TRUE, NULL, NULL, '[]'::jsonb, 'صحيح؛ هذا هو جوهر عمل واجهات برمجة التطبيقات.')
ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, chunk_id, lesson_id, chapter_id, question_index, level, question, options, correct_index, is_true, correct_term, english_term, acceptable_answers, explanation)
VALUES ('ch3-l2-c2_q_best', 'ch3-l2-c2', '3-2', 3, 5, 'best_choice', 'جميع الخيارات التالية تمثل أدوات تنسيق في CSS، ولكن ما هو المبدأ الأصح والأشمل لـ ''التصميم المتجاوب'' (Responsive Web Design)؟', '["تكبير الخطوط تلقائياً فقط عند الضغط على زر التكبير في لوحة المفاتيح.","إنشاء موقعين منفصلين تماماً بروابط مختلفة واحد مخصص للجوال وآخر مخصص للحاسوب المكتبي.","بناء صفحة ويب مرنة واحدة تتكيف أحجام عناصرها وتخطيطها بسلاسة مع كافة أبعاد الشاشات والأجهزة المختلفة باستخدام استعلامات الوسائط (Media Queries) والشبكات والتخطيطات المرنة.","منع فتح الموقع على أي شاشة يقل عرضها عن 1000 بكسل لحماية التنسيق."]'::jsonb, 2, NULL, NULL, NULL, '[]'::jsonb, 'التصميم المتجاوب يعني كود واحد وموقع واحد يتأقلم تلقائياً مع شاشة الهاتف والتابلت والحاسوب عبر Media Queries وشبكات CSS المرنة.')
