INSERT INTO public.questions (id, chunk_id, lesson_id, chapter_id, question_index, level, question, options, correct_index, is_true, correct_term, english_term, acceptable_answers, explanation)
VALUES ('ch3-l3-c1_q1', 'ch3-l3-c1', '3-3', 3, 1, 'mcq', 'اللغة المسؤولة عن بناء الهيكل الأساسي والعناصر لصفحة الويب (مثل العناوين وحقول الاستمارة) هي:', '["لغة HTML","لغة CSS","لغة SQL","بروتوكول HTTP"]'::jsonb, 0, NULL, NULL, NULL, '[]'::jsonb, 'HTML هي لغة بناء هيكل صفحات الويب.')
