INSERT INTO public.questions (id, chunk_id, lesson_id, chapter_id, question_index, level, question, options, correct_index, is_true, correct_term, english_term, acceptable_answers, explanation)
VALUES ('ch3-l3-c1_q1_alt', 'ch3-l3-c1', '3-3', 3, 2, 'mcq', 'اللغة المسؤولة عن إضافة السلوك التفاعلي والحركة وفحص صحة البيانات فورياً في المتصفح هي:', '["JavaScript","HTML","CSS","Photoshop"]'::jsonb, 0, NULL, NULL, NULL, '[]'::jsonb, 'JavaScript توفر المنطق والتفاعل في الواجهة الأمامية.')
