VALUES ('ch3-l3-c1_q2', 'ch3-l3-c1', '3-3', 3, 3, 'true_false', 'تتولى لغة CSS تحديد مظهر صفحة الويب وتخطيطها وألوانها وخطوطها.', '[]'::jsonb, NULL, TRUE, NULL, NULL, '[]'::jsonb, 'صحيح؛ هذا هو الدور المنهجي المعتمد لـ CSS ص 66.')
