INSERT INTO public.questions (id, chunk_id, lesson_id, chapter_id, question_index, level, question, options, correct_index, is_true, correct_term, english_term, acceptable_answers, explanation)
VALUES ('ch3-l3-c1_q2_alt', 'ch3-l3-c1', '3-3', 3, 4, 'true_false', 'لغة HTML هي المسؤولة عن إضافة التفاعلية المتقدمة والتحقق البرمجي التلقائي من المدخلات.', '[]'::jsonb, NULL, FALSE, NULL, NULL, '[]'::jsonb, 'خطأ؛ JavaScript هي المسؤولة عن السلوك التفاعلي والتحقق البرمجي.')
ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, chunk_id, lesson_id, chapter_id, question_index, level, question, options, correct_index, is_true, correct_term, english_term, acceptable_answers, explanation)
VALUES ('ch3-l3-c1_q_best', 'ch3-l3-c1', '3-3', 3, 5, 'best_choice', 'جميع العبارات التالية صحيحة عن شجرة عناصر DOM في المتصفح، ولكن ما هو التوصيف الأصح والأشمل لعلاقة JavaScript بـ DOM؟', '["تقوم JavaScript بحفظ نسخة من شجرة DOM في قاعدة بيانات MySQL على الخادم كل دقيقة.","لغة JavaScript تحل محل لغة HTML في بناء البنية الهيكلية الأولية من نقطة الصفر دائماً.","تمثل DOM واجهة برمجية تمثل صفحة الويب كشجرة كائنات تفاعلية في ذاكرة المتصفح، مما يمكن JavaScript من قراءة عناصر الصفحة وتعديل نصوصها وتنسيقاتها والاستجابة لنقرات وأحداث المستخدم ديناميكياً.","شجرة DOM وظيفتها حماية أكواد الجافاسكريبت من السرقة والتشفير."]'::jsonb, 2, NULL, NULL, NULL, '[]'::jsonb, 'شجرة DOM هي الجسر الذي يربط بين هيكل الصفحة وكود JavaScript؛ فتحول وسوم HTML إلى كائنات برمجية قابلة للتعديل اللحظي عند وقوع الأحداث (Events).')
ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, chunk_id, lesson_id, chapter_id, question_index, level, question, options, correct_index, is_true, correct_term, english_term, acceptable_answers, explanation)
