ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, chunk_id, lesson_id, chapter_id, question_index, level, question, options, correct_index, is_true, correct_term, english_term, acceptable_answers, explanation)
VALUES ('ch3-l3-c1_q_reinforce', 'ch3-l3-c1', '3-3', 3, 7, 'mcq', 'الدالة الأكثر شيوعاً في JavaScript للوصول المباشر لعنصر محدد في الصفحة عبر قيمة معرّفه الفريد (ID) هي:', '["`console.log()`","`document.getElementById()`","`window.alert()`","`localStorage.setItem()`"]'::jsonb, 1, NULL, NULL, NULL, '[]'::jsonb, '`document.getElementById(''id'')` تُرجع مرجعاً برمجياً مباشراً للعنصر ذي المعرف المحدد للتعديل عليه.')
