INSERT INTO public.questions (id, chunk_id, lesson_id, chapter_id, question_index, level, question, options, correct_index, is_true, correct_term, english_term, acceptable_answers, explanation)
VALUES ('ch3-l3-c2_q1_alt', 'ch3-l3-c2', '3-3', 3, 2, 'mcq', 'الغرض الرئيسي من تطبيق ''التصميم المتجاوب'' (Responsive Web Design) في المواقع هو:', '["تكييف تخطيط وعناصر الموقع تلقائياً لتناسب شاشات الهواتف والحواسيب المختلفة","تشفير ملفات قاعدة البيانات","إلغاء لغة HTML من الموقع","تقليل سرعة تصفح الإنترنت"]'::jsonb, 0, NULL, NULL, NULL, '[]'::jsonb, 'التصميم المتجاوب يضمن عرضاً مثالياً على كل أحجام الشاشات.')
