INSERT INTO public.questions (id, chunk_id, lesson_id, chapter_id, question_index, level, question, options, correct_index, is_true, correct_term, english_term, acceptable_answers, explanation)
VALUES ('ch3-l3-c2_q2', 'ch3-l3-c2', '3-3', 3, 3, 'true_false', 'إمكانية الوصول للويب (Web Accessibility) تعني تصميم الموقع ليتمكن جميع الأفراد بما فيهم ذوو الإعاقة وكبار السن من استخدامه بكفاءة.', '[]'::jsonb, NULL, TRUE, NULL, NULL, '[]'::jsonb, 'صحيح؛ هذا هو التعريف المنهجي المعتمد في كتاب الوزارة ص 64.')
ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, chunk_id, lesson_id, chapter_id, question_index, level, question, options, correct_index, is_true, correct_term, english_term, acceptable_answers, explanation)
VALUES ('ch3-l3-c2_q2_alt', 'ch3-l3-c2', '3-3', 3, 4, 'true_false', 'توفر أطر العمل مثل React و Next.js مكونات برمجية جاهزة لتطوير المواقع بكفاءة وتجنب كتابة الكود من الصفر.', '[]'::jsonb, NULL, TRUE, NULL, NULL, '[]'::jsonb, 'صحيح؛ كتاب ص 65 يوضح ميزة إعادة استخدام المكونات البرمجية.')
ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, chunk_id, lesson_id, chapter_id, question_index, level, question, options, correct_index, is_true, correct_term, english_term, acceptable_answers, explanation)
VALUES ('ch3-l3-c2_q_best', 'ch3-l3-c2', '3-3', 3, 5, 'best_choice', 'جميع العبارات التالية تصف الاتصال بين المتصفح والخادم، ولكن ما هي الميزة الأصح والأشمل لاستخدام دالة `fetch()` والاتصال غير المتزامن (AJAX) في تطبيقات الويب الحديثة؟', '["إمكانية فتح صفحات الويب دون الحاجة لوجود اشتراك إنترنت منزلي.","إغلاق نافذة المتصفح تلقائياً فور انتهاء تحميل البيانات المالية الحساسة.","تبادل البيانات مع الخوادم السحابية في الخلفية وتحديث أجزاء محددة من الصفحة بمرونة دون الحاجة لإعادة تحميل (Reload/Refresh) الصفحة بالكامل، مما يوفر تجربة سريعة وسلسة للمستخدم.","تشغيل ملفات الفيديو بدقة فائقة دون الحاجة لبطاقة رسوميات."]'::jsonb, 2, NULL, NULL, NULL, '[]'::jsonb, 'جوهر الاتصال غير المتزامن (Asynchronous Fetch / AJAX) هو جلب البيانات وتحديث واجهة المستخدم في الخلفية دون إعادة تحميل الصفحة كاملاً.')
ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
