VALUES ('ch3-l3-c2_q3', 'ch3-l3-c2', '3-3', 3, 6, 'timed_fill', NULL, '["<main>","<nav>","<header>","<footer>"]'::jsonb, NULL, NULL, NULL, NULL, '[]'::jsonb, '<main> يحتوي على جوهر الصفحة الفريد.')
