VALUES ('ch3-l3-c2_q3_alt', 'ch3-l3-c2', '3-3', 3, 8, 'timed_fill', NULL, '["متجاوب","ثابت","قديم","بطيء"]'::jsonb, NULL, NULL, NULL, NULL, '[]'::jsonb, 'التصميم المتجاوب يمنع تشوه عناصر الموقع على الهواتف.')
