INSERT INTO public.questions (id, chunk_id, lesson_id, chapter_id, question_index, level, question, options, correct_index, is_true, correct_term, english_term, acceptable_answers, explanation)
VALUES ('ch4-l1-c1_q1', 'ch4-l1-c1', '4-1', 4, 1, 'mcq', 'أي من الوسائل التالية يُمثل نمط ''الاتصال أحادي الاتجاه'' (One-way Communication) التقليدي؟', '["منشور تفاعلي على فيسبوك","البث التلفزيوني الإخباري التقليدي","محادثة فيديو على زووم","موقع تسوق إلكتروني"]'::jsonb, 1, NULL, NULL, NULL, '[]'::jsonb, 'التلفزيون ينقل من القناة للمشاهد فقط دون تفاعل مباشر منه.')
ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, chunk_id, lesson_id, chapter_id, question_index, level, question, options, correct_index, is_true, correct_term, english_term, acceptable_answers, explanation)
VALUES ('ch4-l1-c1_q1_alt', 'ch4-l1-c1', '4-1', 4, 2, 'mcq', 'الوسيط الرقمي الأكثر جذباً وتأثيراً لقدرته على الجمع بين الحركة والصوت والصورة هو:', '["الفيديو الرقمي","النص المكتوب فقط","الرمز الصوتي المنفرد","الصورة الثابتة"]'::jsonb, 0, NULL, NULL, NULL, '[]'::jsonb, 'الفيديو يجمع قنوات حسية متعددة تجعله الأكثر ثراءً وجذباً.')
ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, chunk_id, lesson_id, chapter_id, question_index, level, question, options, correct_index, is_true, correct_term, english_term, acceptable_answers, explanation)
VALUES ('ch4-l1-c1_q2', 'ch4-l1-c1', '4-1', 4, 3, 'true_false', 'مواقع الويب وشبكات التواصل الاجتماعي تتميز بأنها اتصال تفاعلي ثنائي الاتجاه (Two-way).', '[]'::jsonb, NULL, TRUE, NULL, NULL, '[]'::jsonb, 'صحيح؛ المتلقي يستطيع الرد والمشاركة والتعليق في نفس اللحظة.')
ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, chunk_id, lesson_id, chapter_id, question_index, level, question, options, correct_index, is_true, correct_term, english_term, acceptable_answers, explanation)
VALUES ('ch4-l1-c1_q2_alt', 'ch4-l1-c1', '4-1', 4, 4, 'true_false', 'النصوص المكتوبة ليس لها أي فائدة في العصر الرقمي ويجب استبدالها بالكامل بالفيديو.', '[]'::jsonb, NULL, FALSE, NULL, NULL, '[]'::jsonb, 'خطأ؛ النصوص لا غنى عنها في التوثيق القانوني والبحث العلمي والتعليمات الدقيقة.')
ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, chunk_id, lesson_id, chapter_id, question_index, level, question, options, correct_index, is_true, correct_term, english_term, acceptable_answers, explanation)
VALUES ('ch4-l1-c1_q_best', 'ch4-l1-c1', '4-1', 4, 5, 'best_choice', 'جميع البدائل التالية تصف أنواع الصور الرقمية، ولكن ما هي المقارنة الأصح والأشمل علمياً بين الصور النقطية (Raster) والصور المتجهة (Vector) في تصميم الويب؟', '["الصور النقطية تظهر باللونين الأبيض والأسود فقط بينما الصور المتجهة ملونة دائماً.","الصور المتجهة مخصصة للطباعة الورقية فقط بينما الصور النقطية مخصصة للشاشات الرقمية.","الصور النقطية تتكون من شبكة بكسلات ثابتة وتفقد حدتها وتتشوه عند التكبير (مثل JPG و PNG)، بينما الصور المتجهة تعتمد على معادلات رياضية هندسية وتحافظ على وضوحها التام عند أي نسبة تكبير (مثل SVG).","الصور النقطية حجم ملفاتها يكون صفراً دائماً في ذاكرة التخزين."]'::jsonb, 2, NULL, NULL, NULL, '[]'::jsonb, 'الفارق العلمي الحاسم: النقطية شبكة بكسلات تتشوه بالتكبير، بينما المتجهة معادلات رياضية هندسية لا تفقد حدتها إطلاقاً.')
ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, chunk_id, lesson_id, chapter_id, question_index, level, question, options, correct_index, is_true, correct_term, english_term, acceptable_answers, explanation)
VALUES ('ch4-l1-c1_q3', 'ch4-l1-c1', '4-1', 4, 6, 'timed_fill', NULL, '["اتجاه","صوت","لون","شكل"]'::jsonb, NULL, NULL, NULL, NULL, '[]'::jsonb, 'الاتصال ثنائي الاتجاه هو الركيزة التفاعلية لعالم الويب.')
ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, chunk_id, lesson_id, chapter_id, question_index, level, question, options, correct_index, is_true, correct_term, english_term, acceptable_answers, explanation)
VALUES ('ch4-l1-c1_q_reinforce', 'ch4-l1-c1', '4-1', 4, 7, 'mcq', 'أي امتدادات الصور التالية يعتبر مثالاً على الصور المتجهة (Vector) المدعومة والمثالية للشعارات والأيقونات في الويب؟', '["JPG","PNG","SVG","BMP"]'::jsonb, 2, NULL, NULL, NULL, '[]'::jsonb, 'صيغة SVG (Scalable Vector Graphics) هي صيغة الصور المتجهة المعتمدة في الويب؛ حيث تحافظ على حدتها في جميع الشاشات وحجمها خفيف.')
ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, chunk_id, lesson_id, chapter_id, question_index, level, question, options, correct_index, is_true, correct_term, english_term, acceptable_answers, explanation)
VALUES ('ch4-l1-c1_q3_alt', 'ch4-l1-c1', '4-1', 4, 8, 'timed_fill', NULL, '["أحادي","ثنائي","دائم","عشوائي"]'::jsonb, NULL, NULL, NULL, NULL, '[]'::jsonb, 'الاتصال أحادي الاتجاه يتدفق من المصدر للمتلقي فقط.')
ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, chunk_id, lesson_id, chapter_id, question_index, level, question, options, correct_index, is_true, correct_term, english_term, acceptable_answers, explanation)
VALUES ('ch4-l1-c2_q1', 'ch4-l1-c2', '4-1', 4, 1, 'mcq', 'نوع الصور الذي يعتمد على معادلات رياضية ولا يفقد حدته أو يبكسل عند التكبير هو:', '["الصور المتجهة (Vector Graphics)","الصور النقطية (Bitmap)","ملفات الصوت MP3","أقراص DVD"]'::jsonb, 0, NULL, NULL, NULL, '[]'::jsonb, 'الصور المتجهة مثل SVG تعتمد على معادلات هندسية لا تبكسل أبداً.')
ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, chunk_id, lesson_id, chapter_id, question_index, level, question, options, correct_index, is_true, correct_term, english_term, acceptable_answers, explanation)
VALUES ('ch4-l1-c2_q1_alt', 'ch4-l1-c2', '4-1', 4, 2, 'mcq', 'تقنية ضغط البيانات التي تستعيد البيانات بالكامل بنسبة 100% دون فقدان للجودة وتُستخدم في صيغ مثل PNG تُسمى:', '["الضغط بدون فقدان (Lossless Compression)","الضغط مع الفقدان (Lossy)","المعالجة المتوازية","التشفير غير المتماثل"]'::jsonb, 0, NULL, NULL, NULL, '[]'::jsonb, 'Lossless يستعيد البيانات الأصلية كاملة بدون أي حذف.')
ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, chunk_id, lesson_id, chapter_id, question_index, level, question, options, correct_index, is_true, correct_term, english_term, acceptable_answers, explanation)
VALUES ('ch4-l1-c2_q2', 'ch4-l1-c2', '4-1', 4, 3, 'true_false', 'الصور النقطية (Bitmap) مثل صيغ JPG تفقد حدتها وتبكسل إذا تم تكبيرها أكبر من دقتها الأصلية.', '[]'::jsonb, NULL, TRUE, NULL, NULL, '[]'::jsonb, 'صحيح؛ لأنها تتكون من بكسلات محددة الحجم والعدد.')
ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, chunk_id, lesson_id, chapter_id, question_index, level, question, options, correct_index, is_true, correct_term, english_term, acceptable_answers, explanation)
VALUES ('ch4-l1-c2_q2_alt', 'ch4-l1-c2', '4-1', 4, 4, 'true_false', 'تُستخدم صيغة SVG المتجهة للصور الفوتوغرافية الحقيقية الملتقطة بالكاميرا لأنها الأنسب للتدرجات الواقعية المعقدة.', '[]'::jsonb, NULL, FALSE, NULL, NULL, '[]'::jsonb, 'خطأ؛ SVG مثالية للشعارات والرسوم الهندسية، بينما الصور الفوتوغرافية تناسبها الصور النقطية JPEG.')
ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, chunk_id, lesson_id, chapter_id, question_index, level, question, options, correct_index, is_true, correct_term, english_term, acceptable_answers, explanation)
VALUES ('ch4-l1-c2_q_best', 'ch4-l1-c2', '4-1', 4, 5, 'best_choice', 'جميع المبادئ التالية مهمة في تصميم المواقع، ولكن ما هي المبادئ الأربعة الأصح والأشمل التي بنيت عليها معايير إتاحة الويب العالمية لذوي الاحتياجات الخاصة (مبادئ WCAG - POUR)؟', '["البساطة، التكلفة المنخفضة، تقليل الإعلانات، وزيادة الأرباح التجارية.","السرعة، والتشفير الأمني، والتوافق مع الهواتف الذكية، والتحديث التلقائي.","سهولة الإدراك الحسي (Perceivable)، وقابلية التشغيل والتنقل (Operable)، وسهولة الفهم والاستيعاب (Understandable)، والمتانة والتوافق مع التقنيات المساعدة (Robust).","الألوان الفاقعة، والخطوط الكبيرة، والمؤثرات الصوتية، وكثرة الروابط التفاعلية."]'::jsonb, 2, NULL, NULL, NULL, '[]'::jsonb, 'مبادئ WCAG الأربعة العالمية تُختصر في كلمة POUR: قابل للإدراك، قابل للتشغيل، مفهوم، ومتين.')
ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, chunk_id, lesson_id, chapter_id, question_index, level, question, options, correct_index, is_true, correct_term, english_term, acceptable_answers, explanation)
VALUES ('ch4-l1-c2_q3', 'ch4-l1-c2', '4-1', 4, 6, 'timed_fill', NULL, '["متجهة","نقطية","فوتوغرافية","ممسوحة"]'::jsonb, NULL, NULL, NULL, NULL, '[]'::jsonb, 'الصور المتجهة Vector تحتفظ بحدة الحواف دائماً.')
ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
