VALUES ('ch4-l1-c2_q_reinforce', 'ch4-l1-c2', '4-1', 4, 7, 'timed_fill', NULL, '["الشاشة","الباركود","الأقراص","البصمة"]'::jsonb, NULL, NULL, NULL, NULL, '[]'::jsonb, 'قارئ الشاشة (Screen Reader) يقرأ خاصية `alt` لتمكين المكفوفين من فهم محتوى الصورة ورسالتها.')
