INSERT INTO public.questions (id, chunk_id, lesson_id, chapter_id, question_index, level, question, options, correct_index, is_true, correct_term, english_term, acceptable_answers, explanation)
VALUES ('ch4-l1-c2_q3_alt', 'ch4-l1-c2', '4-1', 4, 8, 'timed_fill', NULL, '["فقدان","تثبيت","تكرار","تكبير"]'::jsonb, NULL, NULL, NULL, NULL, '[]'::jsonb, 'الضغط مع الفقدان Lossy يقلص حجم صور الويب بسرعة فائقة.')
ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, chunk_id, lesson_id, chapter_id, question_index, level, question, options, correct_index, is_true, correct_term, english_term, acceptable_answers, explanation)
VALUES ('ch4-l2-c1_q1', 'ch4-l2-c1', '4-2', 4, 1, 'mcq', 'شخصية خيالية تمثل نمطاً حقيقياً من مستخدمي الموقع مبنية على أبحاث ودراسات واقعية تُسمى:', '["شخصية المستخدم (Persona)","الهاكر","الخادم الوكيل","الكيوبت"]'::jsonb, 0, NULL, NULL, NULL, '[]'::jsonb, 'الـ Persona هي النموذج الإرشادي الذي يوجه المصمم لتلبية رغبات المستخدمين.')
ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, chunk_id, lesson_id, chapter_id, question_index, level, question, options, correct_index, is_true, correct_term, english_term, acceptable_answers, explanation)
VALUES ('ch4-l2-c1_q1_alt', 'ch4-l2-c1', '4-2', 4, 2, 'mcq', 'وضع زر ''تأكيد الحجز'' بلون أحمر بارز جداً ومختلف عن بقية الصفحة يطبق مبدأ من مبادئ CRAP وهو:', '["التباين (Contrast)","التكرار","التقارب","الحوسبة السحابية"]'::jsonb, 0, NULL, NULL, NULL, '[]'::jsonb, 'التباين Contrast يبرز العنصر المهم عبر اختلاف لونه أو حجمه لجذب عين المستخدم.')
