INSERT INTO public.questions (id, chunk_id, lesson_id, chapter_id, question_index, level, question, options, correct_index, is_true, correct_term, english_term, acceptable_answers, explanation)
VALUES ('ch4-l2-c1_q2', 'ch4-l2-c1', '4-2', 4, 3, 'true_false', 'شخصية المستخدم (Persona) يجب أن تبنى على تخمينات وآراء شخصية للمصمم دون استطلاع رأي المستخدمين.', '[]'::jsonb, NULL, FALSE, NULL, NULL, '[]'::jsonb, 'خطأ؛ الـ Persona الناجحة تبنى حصراً على بحوث حقيقية واستبيانات مع المستخدمين.')
ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, chunk_id, lesson_id, chapter_id, question_index, level, question, options, correct_index, is_true, correct_term, english_term, acceptable_answers, explanation)
VALUES ('ch4-l2-c1_q2_alt', 'ch4-l2-c1', '4-2', 4, 4, 'true_false', 'مبدأ التقارب (Proximity) يعني تجميع العناصر المترابطة منطقياً في مكان واحد لتقليل التشتت.', '[]'::jsonb, NULL, TRUE, NULL, NULL, '[]'::jsonb, 'صحيح؛ العناصر ذات العلاقة توضع قريبة من بعضها لتسهيل القراءة.')
ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, chunk_id, lesson_id, chapter_id, question_index, level, question, options, correct_index, is_true, correct_term, english_term, acceptable_answers, explanation)
VALUES ('ch4-l2-c1_q_best', 'ch4-l2-c1', '4-2', 4, 5, 'best_choice', 'جميع العبارات التالية تصف مجالات تصميم الويب، ولكن ما هو الفارق الأصح والأشمل بين تجربة المستخدم (UX) وواجهة المستخدم (UI)؟', '["واجهة المستخدم تختص بكتابة كود الخادم بينما تجربة المستخدم تختص بمديري الشركات فقط.","تجربة المستخدم تطبق على الحواسيب المحمولة بينما واجهة المستخدم تطبق على الهواتف الذكية.","واجهة المستخدم (UI) تركز على المظهر البصري ونقاط الاتصال الجمالية (كالأزرار والخطوط والألوان والأيقونات)، بينما تجربة المستخدم (UX) تهتم برحلة المستخدم الكلية وشعوره وسهولة وصوله لهدفه برضا وكفاءة وانسيابية.","واجهة المستخدم تهتم بالأمن السيبراني بينما تجربة المستخدم تهتم بالتسويق الإلكتروني فقط."]'::jsonb, 2, NULL, NULL, NULL, '[]'::jsonb, 'UI هو ما يراه ويتفاعل معه المستخدم بصرياً (المظهر والجماليات)، بينما UX هو كيف يشعر المستخدم خلال رحلته كاملة (السهولة، الرضا، والكفاءة).')
