INSERT INTO public.questions (id, chunk_id, lesson_id, chapter_id, question_index, level, question, options, correct_index, is_true, correct_term, english_term, acceptable_answers, explanation)
VALUES ('ch4-l2-c1_q_reinforce', 'ch4-l2-c1', '4-2', 4, 7, 'mcq', 'تسمى الشخصية التخيلية المبنية على أبحاث واقعية للمستخدمين لتمثيل الشريحة المستهدفة واحتياجاتها وسلوكياتها أثناء عملية التصميم بـ:', '["روبوت المحادثة الآلي","شخصية المستخدم (User Persona)","المشرف الأكاديمي للموقع","ممثل الدعم الفني"]'::jsonb, 1, NULL, NULL, NULL, '[]'::jsonb, 'شخصية المستخدم (User Persona) هي تمثيل تركيبي للشريحة المستهدفة يساعد فريق التصميم على اتخاذ قرارات تلبي احتياجات الجمهور الحقيقي.')
ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, chunk_id, lesson_id, chapter_id, question_index, level, question, options, correct_index, is_true, correct_term, english_term, acceptable_answers, explanation)
VALUES ('ch4-l2-c1_q3_alt', 'ch4-l2-c1', '4-2', 4, 8, 'timed_fill', NULL, '["تكرار","تباين","عشوائية","تعقيد"]'::jsonb, NULL, NULL, NULL, NULL, '[]'::jsonb, 'التكرار Repetition يضمن الهوية البصرية المتسقة للموقع.')
ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, chunk_id, lesson_id, chapter_id, question_index, level, question, options, correct_index, is_true, correct_term, english_term, acceptable_answers, explanation)
VALUES ('ch4-l2-c2_q1', 'ch4-l2-c2', '4-2', 4, 1, 'mcq', 'النهج التصميمي الذي يجعل فهم المستخدمين واحتياجاتهم وسياق استخدامهم أساساً لكافة قرارات التصميم هو:', '["التصميم المتمحور حول المستخدم (User-Centered Design - UCD)","البرمجة الخطية","ضغط البيانات مع الفقدان","التشفير المتماثل"]'::jsonb, 0, NULL, NULL, NULL, '[]'::jsonb, 'UCD يركز 100% على راحة ومهام المستخدم البشري.')
ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, chunk_id, lesson_id, chapter_id, question_index, level, question, options, correct_index, is_true, correct_term, english_term, acceptable_answers, explanation)
VALUES ('ch4-l2-c2_q1_alt', 'ch4-l2-c2', '4-2', 4, 2, 'mcq', 'تجميع صورة المنتج واسمه وسعره وزر شرائه في بطاقة واحدة قريبة يطبق مبدأ من مبادئ PARC وهو:', '["التقارب (Proximity)","التكرار","التباين","المحاذاة"]'::jsonb, 0, NULL, NULL, NULL, '[]'::jsonb, 'التقارب Proximity يجمع العناصر المترابطة منطقياً في حزمة بصرية واحدة.')
ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, chunk_id, lesson_id, chapter_id, question_index, level, question, options, correct_index, is_true, correct_term, english_term, acceptable_answers, explanation)
VALUES ('ch4-l2-c2_q2', 'ch4-l2-c2', '4-2', 4, 3, 'true_false', 'الاعتماد على اللون وحده لإبراز الأزرار المهمة يُعد كافياً تماماً لمعايير إمكانية الوصول لذوي عمى الألوان.', '[]'::jsonb, NULL, FALSE, NULL, NULL, '[]'::jsonb, 'خطأ؛ كتاب ص 76: يجب تعزيز التباين بنص صريح وأيقونة وتباين سطوعي لدعم ذوي عمى الألوان.')
ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, chunk_id, lesson_id, chapter_id, question_index, level, question, options, correct_index, is_true, correct_term, english_term, acceptable_answers, explanation)
VALUES ('ch4-l2-c2_q2_alt', 'ch4-l2-c2', '4-2', 4, 4, 'true_false', 'توحيد نوع الخط ونظام الألوان وتصميم الأزرار في كافة صفحات الموقع يطبق مبدأ التكرار (Repetition).', '[]'::jsonb, NULL, TRUE, NULL, NULL, '[]'::jsonb, 'صحيح؛ التكرار يحقق الاتساق البصري والهوية الموحدة للموقع.')
ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, chunk_id, lesson_id, chapter_id, question_index, level, question, options, correct_index, is_true, correct_term, english_term, acceptable_answers, explanation)
VALUES ('ch4-l2-c2_q_best', 'ch4-l2-c2', '4-2', 4, 5, 'best_choice', 'جميع العبارات التالية تمثل إرشادات لتنسيق الصفحات، ولكن ما هي الحزمة الأصح والأشمل للمبادئ الأربعة الأساسية في نظرية التصميم البصري (مبادئ CRAP)؟', '["الألوان الفاتحة، والإطارات السميكة، والظلال الداكنة، والخطوط المنحنية المائلة.","الصور الكبيرة، والروابط السريعة، وتنوع الخطوط العشوائي، وكثرة الأزرار الملونة.","التباين (Contrast لإبراز الأهمية)، والتكرار (Repetition لتوحيد الهوية)، والمحاذاة (Alignment لترتيب وتوازن العناصر)، والتقارب (Proximity لربط العناصر المترابطة معاً).","البساطة المطلقة، وسرعة التحميل، والتجاوب مع الشاشات، وتأمين كلمات المرور."]'::jsonb, 2, NULL, NULL, NULL, '[]'::jsonb, 'مبادئ CRAP الأربعة الشهيرة لروبن ويليامز في التصميم هي: Contrast (التباين)، Repetition (التكرار)، Alignment (المحاذاة)، وProximity (التقارب).')
ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, chunk_id, lesson_id, chapter_id, question_index, level, question, options, correct_index, is_true, correct_term, english_term, acceptable_answers, explanation)
