VALUES ('ch4-l2-c2_q3_alt', 'ch4-l2-c2', '4-2', 4, 8, 'timed_fill', NULL, '["تباين","تكرار","إخفاء","تشويش"]'::jsonb, NULL, NULL, NULL, NULL, '[]'::jsonb, 'التباين Contrast يجعل أهم المعلومات واضحة فوراً.')
ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, chunk_id, lesson_id, chapter_id, question_index, level, question, options, correct_index, is_true, correct_term, english_term, acceptable_answers, explanation)
VALUES ('ch4-l3-c1_q1', 'ch4-l3-c1', '4-3', 4, 1, 'mcq', 'التقييم الذي يركز على استكشاف مشاعر المستخدمين وأسباب تصرفاتهم عبر المقابلات والملاحظة يُعرف بالتقييم:', '["النوعي (Qualitative)","الكمي (Quantitative)","الكمومي","الرقمي الإحصائي"]'::jsonb, 0, NULL, NULL, NULL, '[]'::jsonb, 'التقييم النوعي يفسر ''لماذا'' واجه المستخدم صعوبة.')
ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, chunk_id, lesson_id, chapter_id, question_index, level, question, options, correct_index, is_true, correct_term, english_term, acceptable_answers, explanation)
VALUES ('ch4-l3-c1_q1_alt', 'ch4-l3-c1', '4-3', 4, 2, 'mcq', 'مقارنة نسختين من الصفحة (أ و ب) لتحديد أيتهما تحقق أعلى نسبة تسجيل للمستخدمين يُسمى:', '["اختبار أ/ب (A/B Testing)","قانون مور","التشفير المتماثل","الصندوق الأسود"]'::jsonb, 0, NULL, NULL, NULL, '[]'::jsonb, 'اختبار A/B هو الأسلوب المعياري لتجربة التعديلات واختيار الأفضل بالأرقام.')
ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, chunk_id, lesson_id, chapter_id, question_index, level, question, options, correct_index, is_true, correct_term, english_term, acceptable_answers, explanation)
VALUES ('ch4-l3-c1_q2', 'ch4-l3-c1', '4-3', 4, 3, 'true_false', 'الخرائط الحرارية (Heatmaps) توضح بصرياً بالألوان الأماكن الأكثر نقراً وحركة للفأرة على صفحة الويب.', '[]'::jsonb, NULL, TRUE, NULL, NULL, '[]'::jsonb, 'صحيح؛ الألوان الدافئة تدل على تركيز ونقرات الزوار.')
ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, chunk_id, lesson_id, chapter_id, question_index, level, question, options, correct_index, is_true, correct_term, english_term, acceptable_answers, explanation)
VALUES ('ch4-l3-c1_q2_alt', 'ch4-l3-c1', '4-3', 4, 4, 'true_false', 'التقييم الكمي يكتفي بمقابلة شخص واحد ولا يهتم بأي إحصائيات أو أرقام زيارات.', '[]'::jsonb, NULL, FALSE, NULL, NULL, '[]'::jsonb, 'خطأ؛ التقييم الكمي يعتمد على الأرقام الكبيرة والنسب المئوية والتحليلات.')
ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, chunk_id, lesson_id, chapter_id, question_index, level, question, options, correct_index, is_true, correct_term, english_term, acceptable_answers, explanation)
VALUES ('ch4-l3-c1_q_best', 'ch4-l3-c1', '4-3', 4, 5, 'best_choice', 'جميع المقاييس التالية تستخدم في تقييم أداء المواقع، ولكن ما هو التوصيف الأصح والأشمل لـ ''معدل الارتداد'' (Bounce Rate) ودلالته في تجربة المستخدم؟', '["سرعة ارتداد نبضات الشبكة بين الراوتر والخادم بالمللي ثانية (Ping).","نسبة الزوار الذين ينقرون على زر الرجوع للخلف في المتصفح ثلاث مرات متتالية.","النسبة المئوية للزوار الذين يدخلون الموقع ثم يغادرونه بعد مشاهدة صفحة واحدة فقط دون التفاعل مع أي روابط، وارتفاعه غالباً ما يشير إلى عدم ملاءمة المحتوى أو بطء التحميل أو سوء تجربة المستخدم.","عدد السلع والمنتجات التي يرجعها المشترون في متجر إلكتروني بعد شرائها."]'::jsonb, 2, NULL, NULL, NULL, '[]'::jsonb, 'معدل الارتداد (Bounce Rate) يقيس مغادرة الزوار من أول صفحة دون تفاعل؛ مما يعطي مؤشراً تحليلياً قوياً على مشكلات الجذب أو التصميم.')
ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, chunk_id, lesson_id, chapter_id, question_index, level, question, options, correct_index, is_true, correct_term, english_term, acceptable_answers, explanation)
VALUES ('ch4-l3-c1_q3', 'ch4-l3-c1', '4-3', 4, 6, 'timed_fill', NULL, '["كمي","نوعي","شفوي","تاريخي"]'::jsonb, NULL, NULL, NULL, NULL, '[]'::jsonb, 'التقييم الكمي يقيس كمية الزيارات والتفاعلات بالأرقام.')
ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, chunk_id, lesson_id, chapter_id, question_index, level, question, options, correct_index, is_true, correct_term, english_term, acceptable_answers, explanation)
VALUES ('ch4-l3-c1_q_reinforce', 'ch4-l3-c1', '4-3', 4, 7, 'mcq', 'في اختبارات قابلية الاستخدام (Usability Testing)، يعتمد الباحثون في تقييم الموقع بشكل أساسي على:', '["توقعات الذكاء الاصطناعي دون أي مشاركة بشرية","ملاحظة وتسجيل سلوك مستخدمين حقيقيين أثناء قيامهم بمهام محددة على الموقع لرصد الصعوبات الواقعية التي تواجههم","سؤال المبرمج الذي أنشأ الموقع عن رأيه الشخصي في جودة عمله","احتساب عدد الأكواد البرمجية المكتوبة في ملفات المشروع"]'::jsonb, 1, NULL, NULL, NULL, '[]'::jsonb, 'اختبارات قابلية الاستخدام توفر بيانات نوعية حقيقية عبر مراقبة المستخدم الفعلي أثناء تنفيذه مهام واقعية داخل الموقع.')
ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, chunk_id, lesson_id, chapter_id, question_index, level, question, options, correct_index, is_true, correct_term, english_term, acceptable_answers, explanation)
VALUES ('ch4-l3-c1_q3_alt', 'ch4-l3-c1', '4-3', 4, 8, 'timed_fill', NULL, '["أ/ب","مور","إينياك","الكم"]'::jsonb, NULL, NULL, NULL, NULL, '[]'::jsonb, 'اختبار أ/ب يضمن اتخاذ القرار بناءً على سلوك حقيقي.')
ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, chunk_id, lesson_id, chapter_id, question_index, level, question, options, correct_index, is_true, correct_term, english_term, acceptable_answers, explanation)
VALUES ('ch4-l3-c2_q1', 'ch4-l3-c2', '4-3', 4, 1, 'mcq', 'مراجعة يقوم بها خبراء لواجهة المستخدم استناداً إلى قواعد ومبادئ إرشادية عملية تُسمى:', '["التقييم الإرشادي (Heuristic Evaluation)","قانون مور","التشفير غير المتماثل","الحوسبة السحابية"]'::jsonb, 0, NULL, NULL, NULL, '[]'::jsonb, 'التقييم الإرشادي هو مراجعة الخبراء الاستباقية للواجهات.')
ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, chunk_id, lesson_id, chapter_id, question_index, level, question, options, correct_index, is_true, correct_term, english_term, acceptable_answers, explanation)
VALUES ('ch4-l3-c2_q1_alt', 'ch4-l3-c2', '4-3', 4, 2, 'mcq', 'إظهار شريط تحميل متحرك ورسالة تفيد بأن ''جاري حفظ البيانات'' يطبق قاعدة إرشادية وهي:', '["وضوح حالة النظام (System Status)","منع التشفير","إلغاء الخادم","الاتصال أحادي الاتجاه"]'::jsonb, 0, NULL, NULL, NULL, '[]'::jsonb, 'وضوح حالة النظام يطمئن المستخدم بما يفعله النظام لحظياً.')
ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
