VALUES ('ch4-l3-c2_q2', 'ch4-l3-c2', '4-3', 4, 3, 'true_false', 'قاعدة ''منع الأخطاء'' (Error Prevention) تتضمن وضع إجراءات تحمي المستخدم مثل رسائل تأكيد الحذف وإبراز الحقول المطلوبة.', '[]'::jsonb, NULL, TRUE, NULL, NULL, '[]'::jsonb, 'صحيح؛ لمنع ارتكاب المستخدم لأخطاء غير مقصودة تسبب ضياع بياناته.')
