INSERT INTO public.questions (id, chunk_id, lesson_id, chapter_id, question_index, level, question, options, correct_index, is_true, correct_term, english_term, acceptable_answers, explanation)
VALUES ('ch4-l3-c2_q2_alt', 'ch4-l3-c2', '4-3', 4, 4, 'true_false', 'البيانات الإحصائية العددية وحدها تكفي لتفسير كافة مشاعر وأسباب عزوف المستخدمين عن الشراء دون الحاجة للتقييم النوعي.', '[]'::jsonb, NULL, FALSE, NULL, NULL, '[]'::jsonb, 'خطأ؛ كتاب ص 83: الأرقام توضح ما حدث وأين الفجوة، لكن التقييم النوعي وحده يفسر الأسباب ''لماذا''.')
