INSERT INTO public.questions (id, chunk_id, lesson_id, chapter_id, question_index, level, question, options, correct_index, is_true, correct_term, english_term, acceptable_answers, explanation)
VALUES ('ch4-l3-c2_q_best', 'ch4-l3-c2', '4-3', 4, 5, 'best_choice', 'جميع العبارات التالية تصف فحص الواجهات، ولكن ما هو التوصيف الأصح والأشمل لأسلوب ''التقييم الاستكشافي'' (Heuristic Evaluation) في تقييم قابلية الاستخدام؟', '["فحص الموقع عبر برامج مكافحة الفيروسات التلقائية للتأكد من خلوه من البرمجيات الخبيثة.","إجراء استطلاع رأي عام لمتابعي منصات التواصل الاجتماعي عن أجمل لون للخلفية.","مراجعة منهجية خبيرة يقوم بها متخصصون في تجربة الاستخدام لفحص عناصر الواجهة وتدفقاتها ومقارنتها بقواعد ومبادئ استرشادية معترف بها عالمياً (مثل مبادئ نيلسن لقابلية الاستخدام).","قياس قدرة خوادم الويب على تحمل الضغط الميداني عند دخول آلاف الزوار في نفس اللحظة."]'::jsonb, 2, NULL, NULL, NULL, '[]'::jsonb, 'التقييم الاستكشافي هو تدقيق خبير (Expert Review) يقيس التوافق مع قواعد نيلسن العشر مثل: وضوح حالة النظام، ومنع الأخطاء، والاتساق.')
