INSERT INTO public.questions (id, chunk_id, lesson_id, chapter_id, question_index, level, question, options, correct_index, is_true, correct_term, english_term, acceptable_answers, explanation)
VALUES ('ch4-l4-c1_q1', 'ch4-l4-c1', '4-4', 4, 1, 'mcq', 'الترتيب الصحيح لخطوات دورة التحسين التكراري المستمر (PDCA) هو:', '["خطط (Plan) ← نفّذ (Do) ← تحقق (Check) ← طوّر وتصرّف (Act)","نفّذ ← خطط ← طوّر ← تحقق","تحقق ← خطط ← نفّذ ← طوّر","طوّر ← تحقق ← نفّذ ← خطط"]'::jsonb, 0, NULL, NULL, NULL, '[]'::jsonb, 'الترتيب القياسي: خطط ثم نفّذ ثم تحقق ثم طوّر.')
ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, chunk_id, lesson_id, chapter_id, question_index, level, question, options, correct_index, is_true, correct_term, english_term, acceptable_answers, explanation)
VALUES ('ch4-l4-c1_q1_alt', 'ch4-l4-c1', '4-4', 4, 2, 'mcq', 'الخطوة التي نقوم فيها بقياس النتائج ومقارنتها بالأهداف السابقة في دورة PDCA هي خطوة:', '["تحقق (Check)","خطط (Plan)","نفّذ (Do)","طوّر (Act)"]'::jsonb, 0, NULL, NULL, NULL, '[]'::jsonb, 'Check تعني التحقق والقياس لمعرفة هل نجح التعديل أم لا.')
ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, chunk_id, lesson_id, chapter_id, question_index, level, question, options, correct_index, is_true, correct_term, english_term, acceptable_answers, explanation)
VALUES ('ch4-l4-c1_q2', 'ch4-l4-c1', '4-4', 4, 3, 'true_false', 'ينتهي تطوير الموقع الإلكتروني تماماً بمجرد إطلاقه أول مرة على الإنترنت ولا يحتاج لأي تحسين لاحق.', '[]'::jsonb, NULL, FALSE, NULL, NULL, '[]'::jsonb, 'خطأ؛ المواقع تتطلب دورة تحسين مستمرة وصيانة دورية ومواكبة لاحتياجات المستخدمين.')
