VALUES ('ch4-l4-c1_q2_alt', 'ch4-l4-c1', '4-4', 4, 4, 'true_false', 'حلقات التغذية الراجعة (Feedback Loops) تضمن الاستماع لشكاوى المستخدمين وتحويلها لتعديلات ملموسة.', '[]'::jsonb, NULL, TRUE, NULL, NULL, '[]'::jsonb, 'صحيح؛ وهي المصدر الأساسي لبيانات التطوير الواقعية.')
