INSERT INTO public.questions (id, chunk_id, lesson_id, chapter_id, question_index, level, question, options, correct_index, is_true, correct_term, english_term, acceptable_answers, explanation)
VALUES ('ch4-l4-c1_q_best', 'ch4-l4-c1', '4-4', 4, 5, 'best_choice', 'جميع العبارات التالية تصف أساليب التطوير، ولكن ما هو التوصيف الأصح والأشمل للمراحل الخمس المتتابعة والمتكررة في منهجية ''التفكير التصميمي'' (Design Thinking) لحل المشكلات؟', '["التفكير، البرمجة، التسويق، البيع، وتحصيل الأرباح التجارية.","الشراء، والتركيب، والتجربة العشوائية، والمراقبة، ثم الصيانة الدورية.","التعاطف مع المستخدم (Empathize)، ثم تحديد المشكلة بدقة (Define)، ثم توليد الأفكار الإبداعية (Ideate)، ثم بناء النماذج الأولية السريعة (Prototype)، ثم الاختبار والتحسين (Test).","التخطيط المالي، والتوظيف، والتنفيذ، والدفع، والتوثيق الورقي."]'::jsonb, 2, NULL, NULL, NULL, '[]'::jsonb, 'المراحل الخمس الرسمية للتفكير التصميمي (Design Thinking) المعتمدة في المنهج هي: Empathize ← Define ← Ideate ← Prototype ← Test.')
