INSERT INTO public.questions (id, chunk_id, lesson_id, chapter_id, question_index, level, question, options, correct_index, is_true, correct_term, english_term, acceptable_answers, explanation)
VALUES ('ch4-l4-c1_q_reinforce', 'ch4-l4-c1', '4-4', 4, 7, 'mcq', 'الحرف ''C'' في دورة التحسين المستمر للجودة (دورة PDCA) يرمز لمرحلة:', '["إنشاء الحساب (Create)","الفحص والتحقق من النتائج ومقارنتها بالأهداف (Check)","كتابة الشيفرة البرمجية (Code)","ضغط ملفات النظام (Compress)"]'::jsonb, 1, NULL, NULL, NULL, '[]'::jsonb, 'دورة PDCA تتألف من: التخطيط (Plan)، التنفيذ (Do)، الفحص والتحقق (Check)، والتصرف والتحسين (Act).')
