INSERT INTO public.questions (id, chunk_id, lesson_id, chapter_id, question_index, level, question, options, correct_index, is_true, correct_term, english_term, acceptable_answers, explanation)
VALUES ('ch4-l4-c2_q1', 'ch4-l4-c2', '4-4', 4, 1, 'mcq', 'القاعدة المنهجية الأساسية في اختبار A/B لمعرفة أثر تعديل تصميمي معين بدقة هي:', '["عزل المتغير الواحد (تعديل عنصر واحد فقط وتثبيت البقية)","تغيير جميع صفحات الموقع والألوان والخطوط معاً دفعة واحدة","إلغاء لغة JavaScript","إجراء الاختبار على شخص واحد فقط"]'::jsonb, 0, NULL, NULL, NULL, '[]'::jsonb, 'عزل المتغير الواحد يضمن قياس الأثر الدقيق للعنصر المعدل.')
ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, chunk_id, lesson_id, chapter_id, question_index, level, question, options, correct_index, is_true, correct_term, english_term, acceptable_answers, explanation)
VALUES ('ch4-l4-c2_q1_alt', 'ch4-l4-c2', '4-4', 4, 2, 'mcq', 'تغيير لون زر الشراء ونصه ومكانه وصور المنتجات كلها دفعة واحدة في النسخة B يؤدي إلى عيب منهجي يُعرف بـ:', '["قياس أثر الحزمة الإجمالي فقط والعجز عن عزل أثر كل عنصر","تدمير خادم الويب","زيادة الأمان بنسبة 100%","إيقاف قاعدة البيانات"]'::jsonb, 0, NULL, NULL, NULL, '[]'::jsonb, 'كتاب ص 91: تغيير الحزمة يعجز عن عزل أثر كل عنصر منفرد.')
ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, chunk_id, lesson_id, chapter_id, question_index, level, question, options, correct_index, is_true, correct_term, english_term, acceptable_answers, explanation)
VALUES ('ch4-l4-c2_q2', 'ch4-l4-c2', '4-4', 4, 3, 'true_false', 'في اختبار A/B السليم، يتم توزيع زوار الموقع عشوائياً بين النسخة A والنسخة B لقياس الأداء بموضوعية.', '[]'::jsonb, NULL, TRUE, NULL, NULL, '[]'::jsonb, 'صحيح؛ التوزيع العشوائي يضمن تكافؤ العينة وصحة النتائج الإحصائية.')
ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, chunk_id, lesson_id, chapter_id, question_index, level, question, options, correct_index, is_true, correct_term, english_term, acceptable_answers, explanation)
VALUES ('ch4-l4-c2_q2_alt', 'ch4-l4-c2', '4-4', 4, 4, 'true_false', 'التحسين التكراري عبر دورات مستمرة يقلل مخاطر الأخطاء الكبرى ويضمن تطور الموقع بناءً على سلوكيات فعلية.', '[]'::jsonb, NULL, TRUE, NULL, NULL, '[]'::jsonb, 'صحيح؛ هذا هو السبب الجوهري لاعتماد التحسين التكراري المستمر.')
ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, chunk_id, lesson_id, chapter_id, question_index, level, question, options, correct_index, is_true, correct_term, english_term, acceptable_answers, explanation)
VALUES ('ch4-l4-c2_q_best', 'ch4-l4-c2', '4-4', 4, 5, 'best_choice', 'جميع العبارات التالية تصف مقارنة تصميمات الويب، ولكن ما هو المبدأ المنهجي الأصح والأشمل لـ ''اختبارات A/B'' والسبب في اشتراط عزل متغير واحد فقط؟', '["توفير تكلفة استضافة السيرفرات باختبار صفحة واحدة فقط كل شهر للموقع بالكامل.","إرضاء كافة أذواق الزوار بإنشاء أزرار متعددة الألوان والأشكال العشوائية في نفس الصفحة.","تقسيم الزوار عشوائياً وبالتساوي بين نسختين متطابقتين تماماً باستثناء عنصر واحد فقط (مثل لون أو نص زر الشراء)، لعزل وتحديد الأثر السببي الحقيقي لهذا المتغير إحصائياً على معدل التحويل وتجنب التداخل المضلل.","اختيار التصميم الذي يفضله مدير الشركة شخصياً دون النظر للأرقام والبيانات الإحصائية."]'::jsonb, 2, NULL, NULL, NULL, '[]'::jsonb, 'قاعدة عزل المتغير الواحد (Single-Variable Isolation) هي جوهر اختبار A/B؛ فلو غيرنا النص واللون والموقع معاً، لن نعرف إحصائياً أي عامل هو الذي حقق الزيادة أو النقص.')
ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation;
